// ---------- Ares Speaking -> Smart Learning bridge ----------
// speaking.html and index.html share the same GitHub Pages origin, so their
// localStorage is shared. Import only meaningful corrections saved by Ares.
function syncAresSpeakingLearning(){
  let ares={};
  try{ ares=JSON.parse(localStorage.getItem('ares_v36')||'{}')||{}; }catch(e){ return; }
  const src=Array.isArray(ares.mistakes)?ares.mistakes:[];
  let changed=false;
  src.forEach(m=>{
    const original=String(m&&m.a||'').trim();
    const better=String(m&&m.b||'').trim();
    if(!original||!better)return;
    const exists=progress.mistakes.some(x=>x && String(x.source||'')==='ares-speaking' && String(x.en||'')===original && String(x.note||'')===better);
    if(!exists){
      progress.mistakes.unshift({en:original,tr:'Ares Speaking',note:better,type:'speaking',source:'ares-speaking',date:todayStr(),hits:1,streak:0,lastWrong:Date.now(),due:Date.now()});
      changed=true;
    }
  });
  if(progress.mistakes.length>200)progress.mistakes=progress.mistakes.slice(0,200);
  progress.learningBrain=progress.learningBrain||{patterns:{},responseTimes:[],realLifeUses:0};
  progress.learningBrain.speaking=progress.learningBrain.speaking||{};
  const turns=Number(ares.turns||0), minutes=Number(ares.minutes||0);
  if(progress.learningBrain.speaking.turns!==turns||progress.learningBrain.speaking.minutes!==minutes){
    progress.learningBrain.speaking.turns=turns;
    progress.learningBrain.speaking.minutes=minutes;
    progress.learningBrain.speaking.lastSync=Date.now();
    changed=true;
  }
  if(changed)saveProgress(progress);
}

