// Yedekleme hatırlatıcısı: ilerleme varsa ve uzun süredir dışa aktarım yapılmadıysa
// (veya hiç yapılmadıysa) panoda küçük bir uyarı kartı gösterir. Sadece tarayıcı
// hafızasında (localStorage) tutulan veriler cihaz değişince/temizlenince kaybolabilir.
function backupReminderCard(){
  const hasProgress = progress.lessonsDone.length>0 || progress.knownWords.length>5 || progress.mistakes.length>0;
  if(!hasProgress) return '';
  let daysSince = null;
  if(progress.lastExportDate){
    const d1 = new Date(progress.lastExportDate), d2 = new Date(todayStr());
    daysSince = Math.round((d2-d1)/(1000*60*60*24));
  }
  const shouldWarn = !progress.lastExportDate || daysSince>=14;
  if(!shouldWarn) return '';
  const msg = progress.lastExportDate
    ? `Son yedeklemenden bu yana ${daysSince} gün geçti.`
    : `İlerlemeni henüz hiç yedeklemedin.`;
  return `<div class="card" style="border-left:4px solid var(--gold);">
    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px;">
      <div>
        <b>💾 Yedekleme Hatırlatması</b>
        <p class="hint" style="margin:4px 0 0 0;">${msg} Tüm ilerleme (bilinen kelimeler, quiz skorları, düzeltmeler) sadece bu tarayıcıda saklanıyor — cihaz değişirse veya tarayıcı verileri temizlenirse kaybolur.</p>
      </div>
      <button class="pill primary" onclick="exportProgress(); render();">Export Progress</button>
    </div>
  </div>`;
}
function applySentenceEdits(){
  Object.keys(progress.sentenceEdits).forEach(key=>{
    const [lessonNo, idx] = key.split(':').map(Number);
    const l = DATA.lessons.find(x=>x.no===lessonNo);
    const edit = progress.sentenceEdits[key];
    if(l && l.sentences[idx]) l.sentences[idx] = [edit[0], edit[1]];
  });
}
applySentenceEdits();
// Kullanıcının derse eklediği özel cümleleri, sayfa her açıldığında DATA içine geri ekler
// (localStorage'da saklanır, orijinal ders verisine dokunmaz).
function applyCustomLessonSentences(){
  Object.keys(progress.customLessonSentences).forEach(key=>{
    const l = DATA.lessons.find(x=>x.no===Number(key));
    if(!l) return;
    progress.customLessonSentences[key].forEach(pair=>{ l.sentences.push(pair.slice()); });
  });
}
applyCustomLessonSentences();

