function v53PolishCurriculum(){
  DATA.lessons.forEach(lesson=>{
    if(lesson.no<11) return;
    lesson.sentences=(lesson.sentences||[]).map(pair=>{
      const en=String(pair?.[0]||'').trim();
      const fixed=V53_NATURAL_FIXES.get(en)||en;
      return [fixed,pair?.[1]||''];
    });
  });
}
v53PolishCurriculum();

// v53: Aynı İngilizce cümlenin birden fazla çekirdek derste tekrar etmesini önler.
// Büyük/küçük harf, son noktalama ve tipografik apostrof farkları aynı cümle kabul edilir.
function v52SentenceKey(en){
  return String(en||'')
    .normalize('NFKC')
    .replace(/[’‘]/g,"'")
    .trim().toLowerCase()
    .replace(/\s+/g,' ')
    .replace(/[.!?]+$/,'');
}
function v52DedupeCurriculum(){
  const seen=new Set();
  DATA.lessons.forEach(lesson=>{
    lesson.sentences=(lesson.sentences||[]).filter(pair=>{
      const key=v52SentenceKey(pair && pair[0]);
      if(!key || seen.has(key)) return false;
      seen.add(key); return true;
    });
  });
}
v52DedupeCurriculum();

// v54: Ders kelimelerinde kullanıcının yaptığı düzeltme ve silmeleri kalıcı uygula.
function wordPairKey(pair){
  return String(pair?.[0]||'').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ')+'|'+String(pair?.[1]||'').normalize('NFKC').trim().toLowerCase().replace(/\s+/g,' ');
}
function sameWordPair(a,b){ return wordPairKey(a)===wordPairKey(b); }
function applyLessonWordChanges(){
  Object.keys(progress.lessonWordEdits||{}).forEach(key=>{
    const l=DATA.lessons.find(x=>x.no===Number(key)); if(!l) return;
    (progress.lessonWordEdits[key]||[]).forEach(edit=>{
      const i=l.words.findIndex(w=>sameWordPair(w,edit.from));
      if(i>=0) l.words[i]=edit.to.slice();
    });
  });
  Object.keys(progress.deletedLessonWords||{}).forEach(key=>{
    const l=DATA.lessons.find(x=>x.no===Number(key)); if(!l) return;
    const deleted=progress.deletedLessonWords[key]||[];
    l.words=(l.words||[]).filter(w=>!deleted.some(d=>sameWordPair(w,d)));
  });
}
applyLessonWordChanges();

// Eski 1–60 ilerlemesini yalnızca bir kez yeni 42 modüle aktar.
if(!progress.v49CurriculumMigrated){
  const oldDone=new Set(progress.lessonsDone||[]);
  // v48 daha önce çalıştıysa mevcut 1–42 kayıtlarını koru; aksi halde eski 1–60 kaynak numaralarından taşı.
  const looksLikeV48=progress.v48CurriculumMigrated===true;
  progress.lessonsDone=looksLikeV48 ? [...oldDone].filter(n=>n>=1&&n<=42) : DATA.lessons.filter(l=>l.sourceNos.every(n=>oldDone.has(n))).map(l=>l.no);
  const oldDates=progress.lessonDoneDates||{}; const newDates={};
  if(looksLikeV48){ Object.keys(oldDates).forEach(k=>{const n=Number(k); if(n>=1&&n<=42)newDates[n]=oldDates[k];}); }
  else DATA.lessons.forEach(l=>{ const ds=l.sourceNos.map(n=>oldDates[n]).filter(Boolean).sort(); if(ds.length===l.sourceNos.length) newDates[l.no]=ds[ds.length-1]; });
  progress.lessonDoneDates=newDates; progress.v49CurriculumMigrated=true; saveProgress(progress);
}
function addLessonSentence(lessonNo){
  const l = DATA.lessons.find(x=>x.no===lessonNo);
  if(!l) return;
  const newEn = prompt('Yeni cümle ekle (İngilizce):');
  if(newEn===null) return;
  const en = newEn.trim();
  if(!en){ alert('Cümle boş bırakılamaz.'); return; }
  const newTr = prompt('Türkçe çevirisi:');
  if(newTr===null) return;
  const tr = newTr.trim();
  if(!tr){ alert('Çeviri boş bırakılamaz.'); return; }
  l.sentences.push([en, tr]);
  progress.customLessonSentences[lessonNo] = progress.customLessonSentences[lessonNo] || [];
  progress.customLessonSentences[lessonNo].push([en, tr]);
  allWordsCache = null;
  allSentencesCache = null;
  saveProgress(progress);
  if(currentView==='lesson') render();
}
function deleteLessonSentence(lessonNo, idx){
  const l = DATA.lessons.find(x=>x.no===lessonNo);
  if(!l || !l.sentences[idx]) return;
  if(!confirm('Bu cümleyi silmek istediğine emin misin?')) return;
  const removed = l.sentences[idx];
  l.sentences.splice(idx,1);
  const arr = progress.customLessonSentences[lessonNo];
  if(arr){
    const ci = arr.findIndex(p=>p[0]===removed[0] && p[1]===removed[1]);
    if(ci>=0) arr.splice(ci,1);
  }
  delete progress.sentenceEdits[lessonNo+':'+idx];
  allWordsCache = null;
  allSentencesCache = null;
  saveProgress(progress);
  if(currentView==='lesson') render();
}
function editSentence(lessonNo, idx){
  const l = DATA.lessons.find(x=>x.no===lessonNo);
  if(!l || !l.sentences[idx]) return;
  const current = l.sentences[idx];
  const newEn = prompt('İngilizce cümleyi düzenle:', current[0]);
  if(newEn===null) return;
  const newTr = prompt('Türkçe çevirisini düzenle:', current[1]);
  if(newTr===null) return;
  const en = newEn.trim(), tr = newTr.trim();
  if(!en || !tr){ alert('Cümle boş bırakılamaz.'); return; }
  l.sentences[idx] = [en, tr];
  progress.sentenceEdits[lessonNo+':'+idx] = [en, tr];
  allWordsCache = null;
  allSentencesCache = null;
  saveProgress(progress);
  if(currentView==='lesson') render();
}

// ---------- Ders kelimeleri: düzelt / sil / tekrarları göster ----------
function lessonWordNorm(en){
  return String(en||'').normalize('NFKC').replace(/[’‘]/g,"'").trim().toLowerCase().replace(/\s+/g,' ').replace(/[.!?]+$/,'');
}
// v56: bariz kelime/çeviri hataları için güvenli düzeltmeler.
// Yalnızca anlamı açıkça yanlış/yazımı bozuk kayıtlar düzeltilir; çok anlamlı kelimeler korunur.
const V56_WORD_FIXES = {
  'uncle|çirkin':['uncle','amca / dayı'],
  'give decision|karar vermek':['make a decision','karar vermek'],
  'lock|kitlemek':['lock','kilitlemek'],
  'carry|taşıt':['vehicle','taşıt'],
  'pain killer|ağrı kesici':['painkiller','ağrı kesici'],
  'water melon|karpuz':['watermelon','karpuz'],
  'tea pot|çaydanlık':['teapot','çaydanlık'],
  'maleesef|maalesef':['unfortunately','maalesef']
};
(function applyV56WordFixes(){
  DATA.lessons.forEach(l=>(l.words||[]).forEach((w,i)=>{
    const k=lessonWordNorm(w[0])+'|'+lessonWordNorm(w[1]);
    if(V56_WORD_FIXES[k]) l.words[i]=V56_WORD_FIXES[k].slice();
  }));
})();
function wordLessonOccurrences(en){
  const key=lessonWordNorm(en); if(!key) return [];
  const out=[];
  DATA.lessons.forEach(l=>(l.words||[]).forEach((w,idx)=>{
    if(lessonWordNorm(w[0])===key) out.push({lessonNo:l.no,idx,en:w[0],tr:w[1]});
  }));
  return out;
}
function wordLessonRefs(en){
  return [...new Set(wordLessonOccurrences(en).map(x=>x.lessonNo))];
}
function closeWordDuplicateManager(){
  const el=document.getElementById('word-dup-manager'); if(el) el.remove();
}
function setDuplicateSelection(mode,currentLessonNo,currentIdx){
  document.querySelectorAll('#word-dup-manager input.word-dup-check').forEach(cb=>{
    if(mode==='none') cb.checked=false;
    else if(mode==='others') cb.checked=!(Number(cb.dataset.lesson)===Number(currentLessonNo) && Number(cb.dataset.index)===Number(currentIdx));
    else if(mode==='all') cb.checked=true;
  });
}
function showWordDuplicates(en,currentLessonNo,currentIdx){
  const occ=wordLessonOccurrences(en);
  if(occ.length<=1){ alert('Bu kelimenin başka derste birebir tekrarı yok.'); return; }
  closeWordDuplicateManager();
  const rows=occ.map((o,n)=>{
    const isCurrent=Number(o.lessonNo)===Number(currentLessonNo) && Number(o.idx)===Number(currentIdx);
    return `<label style="display:flex;gap:10px;align-items:flex-start;padding:10px 8px;border-bottom:1px solid var(--line);cursor:pointer;">
      <input class="word-dup-check" type="checkbox" data-lesson="${o.lessonNo}" data-index="${o.idx}" ${isCurrent?'':'checked'} style="margin-top:4px;transform:scale(1.15)">
      <span style="flex:1"><b>${o.lessonNo}. Ders${isCurrent?' · şu an açık':''}</b><br><span>${esc(o.en)}</span><br><span class="hint">${esc(o.tr)}</span></span>
    </label>`;
  }).join('');
  const overlay=document.createElement('div');
  overlay.id='word-dup-manager';
  overlay.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.48);display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.innerHTML=`<div class="card" style="width:min(680px,96vw);max-height:86vh;overflow:auto;margin:0;box-shadow:0 20px 60px rgba(0,0,0,.28);">
    <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;">
      <div><h3 class="section-title" style="margin:0 0 6px">🔁 Tekrarlanan kelime / ifade</h3><div><b>${esc(en)}</b> · ${occ.length} kayıt / ${wordLessonRefs(en).length} ders</div></div>
      <button class="pill" onclick="closeWordDuplicateManager()">✓ Tamam ve Kapat</button>
    </div>
    <p class="hint">Silmek istediğin tekrarları işaretle. Varsayılan olarak şu an açık olan kayıt korunur, diğer tekrarlar seçilir.</p>
    <div style="border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:10px 0 14px">${rows}</div>
    <div class="btns" style="display:flex;gap:8px;flex-wrap:wrap">
      <button class="pill" onclick="setDuplicateSelection('others',${Number(currentLessonNo)||0},${Number(currentIdx)||0})">Diğerlerini seç</button>
      <button class="pill" onclick="setDuplicateSelection('none',${Number(currentLessonNo)||0},${Number(currentIdx)||0})">Seçimi temizle</button>
      <button class="pill" onclick="setDuplicateSelection('all',${Number(currentLessonNo)||0},${Number(currentIdx)||0})">Tümünü seç</button>
      <button class="pill bad" onclick="bulkDeleteWordDuplicates()">🗑️ Seçilenleri tek işlemle sil</button>
    </div>
  </div>`;
  overlay.addEventListener('click',e=>{ if(e.target===overlay) closeWordDuplicateManager(); });
  document.body.appendChild(overlay);
}
function deleteLessonWordInternal(lessonNo,idx){
  const l=DATA.lessons.find(x=>x.no===lessonNo); if(!l || !l.words[idx]) return false;
  const current=l.words[idx].slice();
  const edits=progress.lessonWordEdits[lessonNo] || (progress.lessonWordEdits[lessonNo]=[]);
  const ei=edits.findIndex(e=>sameWordPair(e.to,current) || sameWordPair(e.from,current));
  const original=ei>=0 ? edits[ei].from.slice() : current.slice();
  if(ei>=0) edits.splice(ei,1);
  const deleted=progress.deletedLessonWords[lessonNo] || (progress.deletedLessonWords[lessonNo]=[]);
  if(!deleted.some(d=>sameWordPair(d,original))) deleted.push(original);
  l.words.splice(idx,1);
  return true;
}
function bulkDeleteWordDuplicates(){
  const boxes=[...document.querySelectorAll('#word-dup-manager input.word-dup-check:checked')];
  if(!boxes.length){ alert('Silmek için en az bir tekrar seç.'); return; }
  const allCount=document.querySelectorAll('#word-dup-manager input.word-dup-check').length;
  const msg=boxes.length===allCount
    ? 'Bu kelimenin TÜM kayıtlarını sileceksin. Devam etmek istediğine emin misin?'
    : boxes.length+' seçili tekrarı tek işlemle silmek istediğine emin misin?';
  if(!confirm(msg)) return;
  const targets=boxes.map(cb=>({lessonNo:Number(cb.dataset.lesson),idx:Number(cb.dataset.index)}))
    .sort((a,b)=>a.lessonNo===b.lessonNo?b.idx-a.idx:b.lessonNo-a.lessonNo);
  let count=0;
  targets.forEach(t=>{ if(deleteLessonWordInternal(t.lessonNo,t.idx)) count++; });
  allWordsCache=null;
  saveProgress(progress);
  closeWordDuplicateManager();
  if(currentView==='lesson') render();
  alert(count+' kayıt silindi.');
}
function migrateEditedWordProgress(oldEn,newEn,newTr){
  const oldKey=String(oldEn||'').toLowerCase(), newKey=String(newEn||'').toLowerCase();
  if(oldKey===newKey) return;
  if(Array.isArray(progress.customWords)) progress.customWords=progress.customWords.map(x=>String(x[0]||'').toLowerCase()===oldKey?[newEn,newTr]:x);
  if(Array.isArray(progress.knownWords)) progress.knownWords=progress.knownWords.map(x=>x===oldKey?newKey:x);
  if(progress.knownWordDates && progress.knownWordDates[oldKey]){ progress.knownWordDates[newKey]=progress.knownWordDates[oldKey]; delete progress.knownWordDates[oldKey]; }
  if(progress.wordSR && progress.wordSR[oldKey]){ progress.wordSR[newKey]=progress.wordSR[oldKey]; delete progress.wordSR[oldKey]; }
}
function editLessonWord(lessonNo,idx){
  const l=DATA.lessons.find(x=>x.no===lessonNo); if(!l || !l.words[idx]) return;
  const current=l.words[idx].slice();
  const newEn=prompt('İngilizce kelime / ifade:',current[0]); if(newEn===null) return;
  const newTr=prompt('Türkçe anlamı:',current[1]); if(newTr===null) return;
  const en=newEn.trim(), tr=newTr.trim(); if(!en || !tr){ alert('Kelime ve anlam boş bırakılamaz.'); return; }
  const edits=progress.lessonWordEdits[lessonNo] || (progress.lessonWordEdits[lessonNo]=[]);
  let edit=edits.find(e=>sameWordPair(e.to,current) || sameWordPair(e.from,current));
  if(edit) edit.to=[en,tr]; else edits.push({from:current.slice(),to:[en,tr]});
  migrateEditedWordProgress(current[0],en,tr);
  l.words[idx]=[en,tr];
  allWordsCache=null; saveProgress(progress); render();
}
function deleteLessonWord(lessonNo,idx){
  const l=DATA.lessons.find(x=>x.no===lessonNo); if(!l || !l.words[idx]) return;
  const current=l.words[idx].slice();
  if(!confirm('“'+current[0]+'” kelimesini bu dersten silmek istediğine emin misin?')) return;
  if(deleteLessonWordInternal(lessonNo,idx)){
    // Bu ders satırı silinse de kullanıcının Kelimelerim listesine özellikle ekledikleri korunur.
    allWordsCache=null; saveProgress(progress); render();
  }
}

// ---------- Irregular verbs: correction (düzeltme) ----------
function applyIrregularEdits(){
  Object.keys(progress.irregularEdits).forEach(key=>{
    const idx = Number(key);
    const edit = progress.irregularEdits[key];
    if(DATA.irregular[idx]) DATA.irregular[idx] = Object.assign({}, DATA.irregular[idx], edit);
  });
}
applyIrregularEdits();
function editIrregular(idx){
  const r = DATA.irregular[idx];
  if(!r) return;
  const v1 = prompt('V1 (yalın hal):', r.v1);
  if(v1===null) return;
  const v2 = prompt('V2 (geçmiş zaman):', r.v2);
  if(v2===null) return;
  const v3 = prompt('V3 (geçmiş ortaç):', r.v3);
  if(v3===null) return;
  const pron = prompt('Okunuşu:', r.pron);
  if(pron===null) return;
  const meaning = prompt('Anlamı (Türkçe):', r.meaning);
  if(meaning===null) return;
  const edit = {v1:v1.trim(), v2:v2.trim(), v3:v3.trim(), pron:pron.trim(), meaning:meaning.trim()};
  if(!edit.v1 || !edit.v2 || !edit.v3 || !edit.meaning){ alert('V1, V2, V3 ve anlamı boş bırakılamaz.'); return; }
  DATA.irregular[idx] = Object.assign({}, r, edit);
  progress.irregularEdits[idx] = edit;
  IRREGULAR_V2.clear(); DATA.irregular.forEach(x=>IRREGULAR_V2.add(x.v2.toLowerCase()));
  IRREGULAR_V3.clear(); DATA.irregular.forEach(x=>IRREGULAR_V3.add(x.v3.toLowerCase()));
  saveProgress(progress);
  if(currentView==='irregular') render();
}
function resetIrregularEdit(idx){
  delete progress.irregularEdits[idx];
  saveProgress(progress);
  location.reload();
}

function isDone(n){ return progress.lessonsDone.includes(n); }
function toggleDone(n){
  const i = progress.lessonsDone.indexOf(n);
  if(i>=0){ progress.lessonsDone.splice(i,1); delete progress.lessonDoneDates[n]; }
  else { progress.lessonsDone.push(n); progress.lessonDoneDates[n] = todayStr(); }
  saveProgress(progress);
  renderLessonList();
}
function recordLessonStat(lessonNo, correct){
  if(!lessonNo) return;
  const s = progress.lessonStats[lessonNo] || {correct:0,total:0};
  s.total++;
  if(correct) s.correct++;
  progress.lessonStats[lessonNo] = s;
}
function recordDailyStat(correct){
  const d = todayStr();
  const s = progress.dailyStats[d] || {correct:0,total:0};
  s.total++;
  if(correct) s.correct++;
  progress.dailyStats[d] = s;
}
function lessonMastery(lessonNo){
  const s = progress.lessonStats[lessonNo];
  if(!s || !s.total) return null;
  return Math.round(100*s.correct/s.total);
}
function isFavorite(n){ return progress.favorites.includes(n); }
function toggleFavorite(n){
  const i = progress.favorites.indexOf(n);
  if(i>=0) progress.favorites.splice(i,1); else progress.favorites.push(n);
  saveProgress(progress);
  navigate('lesson', n);
}
function addMistake(en, tr, mtype){
  if(progress.mistakes.some(m=>m.en===en)) return;
  progress.mistakes.unshift({en, tr, type:mtype||'cümle'});
  if(progress.mistakes.length>200) progress.mistakes.pop();
}
function removeMistake(en){
  progress.mistakes = progress.mistakes.filter(m=>m.en!==en);
}

// ---------- dates / streak ----------
function todayStr(){
  const d = new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function dateStrOffset(days){
  const d = new Date(); d.setDate(d.getDate()+days);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function recordVisit(){
  const t = todayStr();
  if(!progress.visitDates.includes(t)){ progress.visitDates.push(t); saveProgress(progress); }
}
function computeStreak(){
  const dates = new Set(progress.visitDates);
  let streak = 0, i = 0;
  while(dates.has(dateStrOffset(-i))){ streak++; i++; }
  return streak;
}

