// ---------- export / import ----------
const API_KEY_STORAGE='ing_defter_api_key';
const API_KEY_STORAGE_BACKUP='ing_defter_api_key_local_backup';
const API_KEY_BACKUP='ing_defter_api_key_backup';
const API_KEY_LEGACY_KEYS=['gemini_api_key','api_key','claude_api_key','ing_api_key'];

function saveApiKeyPersistent(value){
  const v=(value||'').trim();
  if(!v) return;
  try{localStorage.setItem(API_KEY_STORAGE,v);}catch(e){}
  try{localStorage.setItem(API_KEY_STORAGE_BACKUP,v);}catch(e){}
  try{document.cookie=API_KEY_BACKUP+'='+encodeURIComponent(v)+'; Max-Age=31536000; Path=/; SameSite=Strict; Secure';}catch(e){}
}

function restoreApiKeyPersistent(){
  let v='';
  try{
    v=(localStorage.getItem(API_KEY_STORAGE)||'').trim();
    if(v) return v;
  }catch(e){}

  try{
    v=(localStorage.getItem(API_KEY_STORAGE_BACKUP)||'').trim();
    if(v){
      try{localStorage.setItem(API_KEY_STORAGE,v);}catch(e){}
      return v;
    }
  }catch(e){}

  try{
    for(const k of API_KEY_LEGACY_KEYS){
      v=(localStorage.getItem(k)||'').trim();
      if(v){
        saveApiKeyPersistent(v);
        return v;
      }
    }
  }catch(e){}

  try{
    const prefix=API_KEY_BACKUP+'=';
    const part=document.cookie.split('; ').find(x=>x.startsWith(prefix));
    if(part){
      v=decodeURIComponent(part.slice(prefix.length)).trim();
      if(v){
        saveApiKeyPersistent(v);
        return v;
      }
    }
  }catch(e){}

  return '';
}

function removeApiKeyPersistent(){
  try{localStorage.removeItem(API_KEY_STORAGE);}catch(e){}
  try{localStorage.removeItem(API_KEY_STORAGE_BACKUP);}catch(e){}
  try{for(const k of API_KEY_LEGACY_KEYS) localStorage.removeItem(k);}catch(e){}
  try{document.cookie=API_KEY_BACKUP+'=; Max-Age=0; Path=/; SameSite=Strict; Secure';}catch(e){}
}
restoreApiKeyPersistent();
function setApiKey(){
  const current=restoreApiKeyPersistent();
  const val=prompt('AI özelliklerini kullanmak için Google Gemini API anahtarını gir.\n\nBir kez kaydettikten sonra bu site adresinde tarayıcıyı kapatıp açsan da hatırlanır. Boş bırakıp Tamam dersen kayıtlı anahtar silinir.',current);
  if(val===null) return;
  if(val.trim()===''){removeApiKeyPersistent(); alert('API anahtarı kaldırıldı.');}
  else{saveApiKeyPersistent(val); alert('API anahtarı kalıcı olarak kaydedildi.');}
}
// ---------- Gemini API (2026 uyumlu, otomatik model seçimi) ----------
const GEMINI_MODEL_PREFERENCE = ['gemini-3.6-flash','gemini-3.5-flash-lite'];
let _geminiResolvedModel = null;
function geminiHeaders(apiKey){ return {'Content-Type':'application/json','x-goog-api-key':apiKey,'x-goog-api-client':'malta-habit-speaking-coach/1.1'}; }
async function resolveGeminiModel(apiKey){
  if(_geminiResolvedModel) return _geminiResolvedModel;
  const r = await fetch('https://generativelanguage.googleapis.com/v1beta/models?pageSize=1000',{method:'GET',headers:{'x-goog-api-key':apiKey,'x-goog-api-client':'malta-habit-speaking-coach/1.1'}});
  if(!r.ok){ const t=await r.text(); throw new Error('MODEL_LIST_ERROR: '+r.status+' '+t); }
  const data=await r.json();
  const models=(data.models||[]).filter(m=>{ const methods=m.supportedGenerationMethods||m.supportedActions||[]; return methods.includes('generateContent'); });
  const ids=models.map(m=>String(m.name||'').replace(/^models\//,''));
  for(const wanted of GEMINI_MODEL_PREFERENCE){ if(ids.includes(wanted)){ _geminiResolvedModel=wanted; return wanted; } }
  const any=ids.find(x=>/^gemini-.*flash/i.test(x)) || ids[0];
  if(!any) throw new Error('NO_GENERATE_MODEL');
  _geminiResolvedModel=any; return any;
}
async function geminiGenerate(system, contents, maxTokens, temperature){
  const apiKey=restoreApiKeyPersistent(); if(!apiKey) throw new Error('NO_API_KEY');
  const model=await resolveGeminiModel(apiKey);
  const url='https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(model)+':generateContent';
  const response=await fetch(url,{method:'POST',headers:geminiHeaders(apiKey),body:JSON.stringify({systemInstruction:{parts:[{text:system}]},contents,generationConfig:{maxOutputTokens:maxTokens||600,temperature:temperature??0.7}})});
  if(!response.ok){ const errText=await response.text(); if(response.status===404) _geminiResolvedModel=null; throw new Error('API_ERROR: '+response.status+' MODEL='+model+' '+errText); }
  const data=await response.json(); const cand=(data.candidates&&data.candidates[0])||null; const parts=(cand&&cand.content&&cand.content.parts)||[];
  const text=parts.map(p=>p.text||'').join('').trim(); if(!text) throw new Error('EMPTY_RESPONSE'); return text;
}
async function callClaudeAPI(system,userMsg,maxTokens){ return geminiGenerate(system,[{role:'user',parts:[{text:userMsg}]}],maxTokens||1000,0.3); }
function apiKeyMissingMessage(){ return '<div class="card hint" style="border-left:4px solid var(--accent);">🤖 Bu özellik için bir Google Gemini API anahtarı girmelisin.<br><br>Sol menüden <b>Ayarlar → 🔑 AI API Key</b> ile ekleyebilirsin.</div>'; }
async function callClaudeAPIChat(system, messages, maxTokens){
  if(isAppOffline()) throw new Error('OFFLINE_MODE');
  const key = restoreApiKeyPersistent();
  if(!key) throw new Error('NO_API_KEY');

  // Discover models that this exact key can use.
  const listResp = await fetch('https://generativelanguage.googleapis.com/v1beta/models', {
    method:'GET',
    headers:{'x-goog-api-key':key}
  });
  if(!listResp.ok){
    const body = await listResp.text();
    throw new Error('API_ERROR: '+listResp.status+' MODEL_LIST '+body);
  }
  const listData = await listResp.json();
  let models = (listData.models||[]).filter(m =>
    (m.supportedGenerationMethods||[]).includes('generateContent')
  );

  // Prefer stable/lightweight Flash models. Avoid preview/experimental models when possible.
  const scoreModel = m => {
    const n=(m.name||'').replace(/^models\//,'').toLowerCase();
    let s=0;
    if(n.includes('flash')) s+=100;
    if(n.includes('lite')) s+=25;
    if(n.includes('3.6')) s+=60;
    else if(n.includes('3.5')) s+=50;
    else if(n.includes('3.')) s+=35;
    if(n.includes('2.5')) s+=10;
    if(n.includes('preview') || n.includes('experimental') || n.includes('exp')) s-=80;
    if(n.includes('thinking')) s-=20;
    return s;
  };
  models.sort((a,b)=>scoreModel(b)-scoreModel(a));
  if(!models.length) throw new Error('API_ERROR: 404 NO_GENERATE_CONTENT_MODEL');

  const contents = messages.map(m => ({
    role: m.role==='model' ? 'model' : 'user',
    parts:[{text:m.text}]
  }));
  const payload = JSON.stringify({
    systemInstruction:{parts:[{text:system}]},
    contents,
    generationConfig:{maxOutputTokens:maxTokens||400, temperature:0.7}
  });

  const attempted=[];
  let lastErr='';
  // Try several eligible models. 429/500/502/503/504 are transient/capacity errors:
  // immediately fail over instead of making the learner retry manually.
  for(const model of models.slice(0,8)){
    const modelName=(model.name||'').replace(/^models\//,'');
    attempted.push(modelName);
    const url='https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(modelName)+':generateContent';
    try{
      const response=await fetch(url,{
        method:'POST',
        headers:{'Content-Type':'application/json','x-goog-api-key':key},
        body:payload
      });
      if(response.ok){
        const data=await response.json();
        const cand=(data.candidates&&data.candidates[0])||null;
        const parts=(cand&&cand.content&&cand.content.parts)||[];
        const answer=parts.map(p=>p.text||'').join('').trim();
        if(answer) return answer;
        lastErr='Empty response from '+modelName;
        continue;
      }
      const errText=await response.text();
      lastErr='HTTP '+response.status+' MODEL='+modelName+' '+errText;
      if([429,500,502,503,504].includes(response.status)) continue;
      // A model-specific 404 can also be skipped because the list endpoint may briefly be stale.
      if(response.status===404) continue;
      throw new Error('API_ERROR: '+response.status+' MODEL='+modelName+' '+errText);
    }catch(err){
      const raw=String((err&&err.message)||err||'');
      lastErr=raw;
      if(raw.includes('Failed to fetch') || raw.includes('NetworkError') || raw.includes('Load failed')) throw err;
      // Continue for model/capacity failures, but not auth/request errors.
      if(/API_ERROR:\s*(400|401|403)/.test(raw)) throw err;
    }
  }
  throw new Error('API_ERROR: 503 ALL_MODELS_BUSY Tried='+attempted.join(', ')+' Last='+lastErr);
}

// ---------- AI Speaking Coach ----------
function ensureAICoachFocusState(){
  ensureAICoachV2State();
  const validLesson = DATA.lessons.some(l=>l.no===progress.aiCoachV2.focusLessonNo);
  if(!validLesson){
    progress.aiCoachV2.focusLessonNo = getTodayLessonNo();
    progress.aiCoachV2.focusWordOffset = 0;
  }
  if(!Number.isInteger(progress.aiCoachV2.focusWordOffset) || progress.aiCoachV2.focusWordOffset < 0){
    progress.aiCoachV2.focusWordOffset = 0;
  }
}
function advanceAICoachFocus(){
  ensureAICoachV2State();

  const allLessons = (DATA.lessons || []).filter(l => Array.isArray(l.words) && l.words.length);
  if(!allLessons.length) return;

  const previousLessonNo = Number(progress.aiCoachV2.focusLessonNo);

  // Mevcut dersi adaylardan tamamen çıkar.
  // Örn. odak 4. dersteyse buton 4. dersi ASLA tekrar seçmez;
  // kalan çekirdek derslerden (1-42) birini rastgele seçer.
  let candidates = allLessons.filter(l => Number(l.no) !== previousLessonNo);
  if(!candidates.length) candidates = allLessons;

  const pickedLesson = candidates[Math.floor(Math.random() * candidates.length)];

  // Seçilen YENİ dersin kelimelerini karıştır ve rastgele 5 tanesini al.
  const pool = (pickedLesson.words || []).map(w => w[0]).filter(Boolean);
  for(let i = pool.length - 1; i > 0; i--){
    const j = Math.floor(Math.random() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const pickedWords = pool.slice(0, Math.min(5, pool.length));

  progress.aiCoachV2.focusLessonNo = pickedLesson.no;
  progress.aiCoachV2.focusWords = pickedWords;
  progress.aiCoachV2.focusWordOffset = 0;
  saveProgress(progress);
}
function buildAICoachContext(){
  ensureAICoachV2State();

  // İlk açılışta da rastgele bir odak üret.
  if(!progress.aiCoachV2.focusLessonNo || !Array.isArray(progress.aiCoachV2.focusWords) || !progress.aiCoachV2.focusWords.length){
    advanceAICoachFocus();
  }

  const lessonNo = progress.aiCoachV2.focusLessonNo;
  const targetWords = Array.isArray(progress.aiCoachV2.focusWords)
    ? progress.aiCoachV2.focusWords.slice(0,5)
    : [];

  const recentMistakes = (progress.mistakes || []).slice(0,5).map(m=>m.note ? `${m.en} → ${m.note}` : m.en);
  return {lessonNo, targetWords, recentMistakes};
}
function buildAICoachSystemPrompt(){
  const ctx = buildAICoachContext();
  const words = ctx.targetWords.length ? ctx.targetWords.join(', ') : 'none';
  const mistakes = ctx.recentMistakes.length ? ctx.recentMistakes.join(' | ') : 'none';
  return `Your name is Ares. You are Erhan's personal English Speaking Coach. Refer to yourself as Ares when useful. His main goal is speaking fluency: producing English spontaneously without translating sentence-by-sentence in his head. His practical level is around A2-B1, so use natural but accessible English.

TODAY'S STUDY CONTEXT
- Current lesson: ${ctx.lessonNo}
- Target words from today's lesson: ${words}
- Recent mistakes to recycle naturally: ${mistakes}

COACHING RULES
1. Conversation comes first. Keep your normal reply short (1-3 sentences) and make Erhan speak more than you.
2. Ask ONE clear question at a time. Prefer follow-up questions based on what he just said instead of jumping to unrelated topics.
3. Quietly try to make him use today's target words and structures. Do not turn every message into a grammar lesson.
4. Do NOT interrupt fluency for tiny punctuation/style issues, but DO correct clear A2-B1 learning errors: grammar, tense, preposition, spelling that changes meaning, word choice, or unnatural expressions. Never ignore a useful clear error just to preserve flow.
5. When a correction is useful, reply naturally first, then add exactly one line beginning with '📝 Düzeltme:' and explain briefly in Turkish. Show the user's problematic form and the corrected/natural English form. For example, correct "I feel energetic myself" to "I feel energetic" and "may be I'll study" to "maybe I'll study". Do not over-correct valid informal English such as "chill at home".
6. If he gets stuck, first give a small hint or useful chunk; do not immediately give a full ready-made answer unless necessary.
7. Vary topics and examples. Do not repeat the same practice sentence patterns.
8. Occasionally recycle one of the recent mistakes naturally in a later question so he gets another chance to produce the correct form.
9. For Malta/travel role-play, behave like the real person in the situation (receptionist, waiter, classmate, passport officer, etc.), not like a textbook.
10. Never praise every sentence. Keep feedback realistic, calm, and useful.
11. Always answer mainly in English. Turkish is only for short correction explanations or when Erhan explicitly asks for Turkish.
12. End each normal turn with one natural question that keeps Erhan talking.

The purpose of this chat is not to demonstrate English to Erhan; it is to get Erhan to produce as much English as possible.`;
}

function ensureAICoachV2State(){
  if(!progress.aiCoachV2) progress.aiCoachV2 = {sessionCorrections:[], reviews:[], lastReviewDate:null};
  if(!Array.isArray(progress.aiCoachV2.sessionCorrections)) progress.aiCoachV2.sessionCorrections=[];
  if(!Array.isArray(progress.aiCoachV2.reviews)) progress.aiCoachV2.reviews=[];
}
function captureAICorrection(reply){
  ensureAICoachV2State();
  const m=String(reply||'').match(/📝\s*Düzeltme:\s*([\s\S]*)/i);
  if(!m) return;
  const correction=m[1].trim();
  const lastUser=[...progress.aiChatHistory].reverse().find(x=>x.role==='user');
  const original=lastUser ? lastUser.text : '';
  if(!correction || !original) return;
  const duplicate=progress.aiCoachV2.sessionCorrections.some(x=>x.original===original && x.correction===correction);
  if(!duplicate){
    progress.aiCoachV2.sessionCorrections.push({original,correction,date:todayStr()});
    if(Array.isArray(progress.mistakes)){
      const already=progress.mistakes.some(x=>String(x.en||'')===original && String(x.note||'')===correction);
      if(!already) progress.mistakes.unshift({en:original,tr:'Ares — English Coach',note:correction,date:todayStr(),source:'ai-speaking'});
    }
  }
}
async function finishAISpeakingSession(){
  ensureAICoachV2State();
  if(!progress.aiChatHistory.length){ alert('Önce kısa bir konuşma yap.'); return; }
  const loading=document.getElementById('ai-chat-loading');
  if(loading) loading.style.display='block';
  const stored=progress.aiCoachV2.sessionCorrections.slice(-8);
  const request=`Konuşma seansını şimdi bitir ve SADECE bu konuşmaya dayanarak kısa bir değerlendirme yap. Türkçe yaz. Şu başlıkları aynen kullan:
🎯 Akıcılık: X/10 — tek cümle gerekçe
🧩 Gramer: X/10 — tek cümle gerekçe
🗣️ Doğallık: X/10 — tek cümle gerekçe
📝 Bugünün 3 önemli noktası
🔁 Bir sonraki konuşmada tekrar
Olmayan hata uydurma. En fazla 3 düzeltme seç. Kayıtlı düzeltmeler: ${JSON.stringify(stored)}`;
  try{
    const history=progress.aiChatHistory.concat([{role:'user',text:request}]);
    const review=await callClaudeAPIChat(buildAICoachSystemPrompt(),history,650);
    progress.aiChatHistory.push({role:'model',text:review||'Değerlendirme oluşturulamadı.'});
    progress.aiCoachV2.reviews.push({date:todayStr(),text:review||''});
    progress.aiCoachV2.lastReviewDate=todayStr();
    progress.aiCoachV2.sessionCorrections=[];
    saveProgress(progress);
  }catch(err){
    progress.aiChatHistory.push({role:'model',text:'⚠️ Review oluşturulamadı: '+friendlyApiErrorMessage(err)});
    saveProgress(progress);
  }
  if(currentView==='aichat'){ document.getElementById('content').innerHTML=viewAIChat(); scrollAIChatToBottom(); }
}

function scrollAIChatToBottom(){
  setTimeout(()=>{
    const box = document.getElementById('ai-chat-box');
    if(box) box.scrollTop = box.scrollHeight;
  }, 30);
}

let aiVoiceRec = null;
let aiVoiceActive = false;
let aiVoiceManualStop = false;
let aiVoiceCommittedText = '';
let aiAutoSpeak = true;
function speakAIReply(text){
  if(!aiAutoSpeak || !text || !('speechSynthesis' in window)) return;
  // Do not read the Turkish correction aloud; speak only the natural English reply.
  const english = String(text).split(/📝\s*Düzeltme:/i)[0].trim();
  if(!english) return;
  try{
    window.speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(english);
    u.lang='en-US';
    u.rate=0.92;
    window.speechSynthesis.speak(u);
  }catch(e){}
}
function setAIVoiceButton(){
  const btn=document.getElementById('ai-voice-btn');
  if(btn) btn.textContent=aiVoiceActive?'⏹️ Konuşmayı Bitir':'🎤 Konuş';
}
function startAIVoiceRecognition(){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR || !aiVoiceActive) return false;
  try{ aiVoiceRec=new SR(); }catch(e){ aiVoiceRec=null; return false; }
  aiVoiceRec.lang='en-US';
  aiVoiceRec.continuous=true;
  aiVoiceRec.interimResults=true;
  aiVoiceRec.maxAlternatives=3;
  aiVoiceRec.onresult=(e)=>{
    let interim='';
    for(let i=e.resultIndex;i<e.results.length;i++){
      const t=(e.results[i][0]&&e.results[i][0].transcript)||'';
      if(e.results[i].isFinal) aiVoiceCommittedText += t+' ';
      else interim += t+' ';
    }
    const input=document.getElementById('ai-chat-input');
    if(input) input.value=(aiVoiceCommittedText+interim).trim();
  };
  aiVoiceRec.onerror=(e)=>{
    // Chrome can report no-speech/aborted when the speaker pauses. Keep listening.
    if(aiVoiceActive && (e.error==='no-speech'||e.error==='aborted')) return;
    const msg=voiceErrorMessage(e.error);
    aiVoiceActive=false; aiVoiceManualStop=true; aiVoiceRec=null; setAIVoiceButton();
    if(e.error!=='aborted') alert(msg||'Konuşma algılanamadı. Tekrar deneyebilirsin.');
  };
  aiVoiceRec.onend=()=>{
    aiVoiceRec=null;
    // Some Chrome/Android builds end recognition after a short pause even with
    // continuous=true. Restart automatically instead of treating the pause as "done".
    if(aiVoiceActive && !aiVoiceManualStop){
      setTimeout(()=>{ if(aiVoiceActive && !aiVoiceRec) startAIVoiceRecognition(); },250);
    }else{
      setAIVoiceButton();
    }
  };
  try{ aiVoiceRec.start(); return true; }catch(e){ aiVoiceRec=null; return false; }
}
function finishAIVoiceInput(){
  if(!aiVoiceActive) return;
  aiVoiceManualStop=true;
  aiVoiceActive=false;
  if(aiVoiceRec){ try{aiVoiceRec.stop();}catch(e){} }
  aiVoiceRec=null;
  setAIVoiceButton();
  const input=document.getElementById('ai-chat-input');
  // Give the browser a moment to deliver the final recognition result.
  setTimeout(()=>{
    const latest=document.getElementById('ai-chat-input');
    if(latest && latest.value.trim()) sendAIChatMessage();
  },350);
}
function toggleAIVoiceInput(){
  if(isAppOffline()){ alert(offlineAIMessage()); return; }
  if(!voiceEnvironmentGuard()) return false;
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){ alert('Bu tarayıcı konuşmayı yazıya çevirme özelliğini desteklemiyor. Chrome kullanmanı öneririm.'); return; }
  if(aiVoiceActive){ finishAIVoiceInput(); return; }
  const input=document.getElementById('ai-chat-input');
  aiVoiceCommittedText=(input&&input.value.trim()) ? input.value.trim()+' ' : '';
  aiVoiceManualStop=false;
  aiVoiceActive=true;
  setAIVoiceButton();
  if(!startAIVoiceRecognition()){
    aiVoiceActive=false; aiVoiceManualStop=true; setAIVoiceButton();
    alert('Mikrofon başlatılamadı. Mikrofon iznini kontrol et.');
  }
}

function viewAIChat(){
  const hasKey = !!restoreApiKeyPersistent();
  const ctx = buildAICoachContext();
  let html = `<div class="card" style="margin-bottom:16px; border-left:4px solid var(--leaf);"><b>🐾 Ares — English Coach</b><p class="hint" style="margin:6px 0 0 0;">Bugünkü odak: <b>${ctx.lessonNo}. ders</b> · Hedef kelimeler: ${ctx.targetWords.map(esc).join(', ') || '—'}<br>Konuşmayı mümkün olduğunca sen yapacaksın; koç yalnızca gerekli hataları düzeltecek ve geçmiş hatalarını doğal biçimde tekrar karşına çıkaracak.<br><b>🎤 Sesli mod:</b> “Konuş” düğmesine bas ve rahatça konuş. Kısa duraksamalarda dinlemeye devam eder. Cümlen bitince “⏹️ Konuşmayı Bitir”e bas; ardından mesajın gönderilir ve AI cevabını sesli okur.</p></div>`;
  if(!hasKey){
    html += apiKeyMissingMessage();
    return html;
  }
  html += `<div id="ai-chat-box" style="display:flex; flex-direction:column; gap:12px; max-height:52vh; overflow-y:auto; padding:4px 4px 8px 4px; margin-bottom:14px;">`;
  if(!progress.aiChatHistory.length){
    html += `<div class="hint" style="text-align:center; padding:24px 0;">Henüz mesaj yok. Aşağıya bir şeyler yazıp sohbete başla — ör. "Hi! I'm learning English for Malta."</div>`;
  }
  progress.aiChatHistory.forEach(m=>{
    const isUser = m.role==='user';
    let text = esc(m.text);
    let noteHtml = '';
    const noteIdx = text.indexOf('📝 Düzeltme:');
    if(!isUser && noteIdx>=0){
      const main = text.slice(0, noteIdx).trim();
      const note = text.slice(noteIdx).trim();
      text = main;
      noteHtml = `<div style="margin-top:8px; padding-top:8px; border-top:1px dashed var(--line); font-size:13px; color:var(--ink-soft);">${note.replace(/\n/g,'<br>')}</div>`;
    }
    html += `<div style="align-self:${isUser?'flex-end':'flex-start'}; max-width:80%;">
      <div style="background:${isUser?'var(--accent)':'var(--card)'}; color:${isUser?'#fff':'var(--ink)'}; border:1px solid ${isUser?'var(--accent)':'var(--line)'}; border-radius:14px; padding:10px 14px; line-height:1.5; white-space:pre-wrap;">${text.replace(/\n/g,'<br>')}${noteHtml}</div>
    </div>`;
  });
  html += `<div id="ai-chat-loading" class="hint" style="display:none;">🤖 yazıyor…</div>`;
  html += `</div>`;
  html += `<div style="display:flex; gap:8px; align-items:flex-end;">
    <textarea id="ai-chat-input" placeholder="İngilizce bir şeyler yaz…" style="flex:1; min-height:44px; max-height:120px; resize:vertical; border:1px solid var(--line); border-radius:10px; padding:10px 12px; font-family:var(--sans); font-size:14px; background:var(--paper); color:var(--ink);" onkeydown="if(event.key==='Enter' && !event.shiftKey){ event.preventDefault(); sendAIChatMessage(); }"></textarea>
    <button class="pill" id="ai-voice-btn" onclick="toggleAIVoiceInput()">🎤 Konuş</button><button class="pill primary" onclick="sendAIChatMessage()">Gönder</button>
  </div>`;
  html += `<div style="margin-top:10px; display:flex; gap:8px; flex-wrap:wrap;"><button class="pill primary" onclick="startAICoachSession()">▶️ Bugünkü Konuşmayı Başlat</button><button class="pill" onclick="changeAICoachFocus()">🎲 Başka Dersten Rastgele Odak</button><button class="pill" onclick="clearAIChat()">🗑️ Sohbeti Temizle</button><button class="pill primary" onclick="finishAISpeakingSession()">🏁 Konuşmayı Bitir &amp; Değerlendir</button><span class="hint" style="align-self:center;">Tamamlanan AI günleri: ${progress.aiCoachStats.sessions}</span></div>`;
  return html;
}
async function sendAIChatMessage(){
  const input = document.getElementById('ai-chat-input');
  if(!input) return;
  const val = input.value.trim();
  if(!val) return;
  input.value = '';
  progress.aiChatHistory.push({role:'user', text: val});
  saveProgress(progress);
  if(currentView==='aichat'){ document.getElementById('content').innerHTML = viewAIChat(); scrollAIChatToBottom(); }
  const loading = document.getElementById('ai-chat-loading');
  if(loading) loading.style.display = 'block';
  scrollAIChatToBottom();
  try{
    const reply = await callClaudeAPIChat(buildAICoachSystemPrompt(), progress.aiChatHistory, 400);
    progress.aiChatHistory.push({role:'model', text: reply || '...'});
    speakAIReply(reply || '');
    captureAICorrection(reply || '');
    const today = todayStr();
    if(progress.aiCoachStats.lastSessionDate!==today){
      progress.aiCoachStats.sessions += 1;
      progress.aiCoachStats.lastSessionDate = today;
    }
    saveProgress(progress);
  }catch(err){
    const msg = '⚠️ Hata detayı: ' + friendlyApiErrorMessage(err);
    progress.aiChatHistory.push({role:'model', text: msg});
    saveProgress(progress);
  }
  if(currentView==='aichat'){ document.getElementById('content').innerHTML = viewAIChat(); scrollAIChatToBottom(); }
}
// Ham hatayı (network/CORS/HTTP kod/anahtar sorunu) kullanıcının anlayabileceği,
// asıl sebebi gösteren bir Türkçe mesaja çevirir — genel "bir hata oluştu" mesajı yerine.
function friendlyApiErrorMessage(err){
  if(String((err&&err.message)||err||'').includes('OFFLINE_MODE')) return offlineAIMessage();
  const raw=String((err&&err.message)||err||'');
  if(raw.includes('NO_API_KEY')) return 'API anahtarı bulunamadı. Ayarlar → 🔑 AI API Key üzerinden ekle.';
  if(raw.includes('Failed to fetch')||raw.includes('NetworkError')||raw.includes('Load failed')) return 'Tarayıcı Google API isteğine erişemedi. İnternet bağlantısını kontrol et. content:// üzerinden açıyorsan Chrome bazı cihazlarda dış isteği engelleyebilir.';
  if(raw.includes('401')) return 'Google 401: API anahtarı doğrulanamadı. AI Studio’dan yeni bir Gemini auth key oluşturup tekrar kaydet.';
  if(raw.includes('403')) return 'Google 403: Anahtarın veya projen bu isteğe yetkili değil. AI Studio’da anahtarın Gemini API için etkin olduğunu kontrol et.';
  if(raw.includes('429')) return 'Google 429: kullanım kotası doldu. Bir süre sonra tekrar dene.';
  if(raw.includes('NO_GENERATE_MODEL')) return 'Bu API anahtarına açık bir metin üretme modeli bulunamadı.';
  if(raw.includes('404')) return 'Google 404. Teknik detay: '+raw;
  if(raw.includes('MODEL_LIST_ERROR:')||raw.includes('API_ERROR:')) return 'Google API hatası: '+raw;
  return 'Beklenmeyen hata: '+raw;
}

function changeAICoachFocus(){
  advanceAICoachFocus();
  const content = document.getElementById('content');
  if(content){
    content.innerHTML = viewAIChat();
    scrollAIChatToBottom();
  }
}
async function startAICoachSession(){
  if(isAppOffline()){ alert(offlineAIMessage()); return; }
  const key=restoreApiKeyPersistent();
  if(!key){ alert('Önce Ayarlar bölümünden Gemini API anahtarını kaydet.'); return; }
  if(progress.aiChatHistory && progress.aiChatHistory.length){
    if(!confirm('Yeni bir Ares konuşması başlatılsın mı? Mevcut sohbet temizlenecek.')) return;
  }
  progress.aiChatHistory=[];
  ensureAICoachV2State();
  progress.aiCoachV2.sessionCorrections=[];
  // Her yeni konuşma seansında odak otomatik olarak ilerler.
  advanceAICoachFocus();
  saveProgress(progress);
  const loading=document.getElementById('ai-chat-loading');
  if(loading) loading.style.display='block';
  try{
    const ctx=buildAICoachContext();
    const kickoff=`Start today's speaking practice now. Greet Erhan briefly as Ares, then ask ONE natural English question connected to today's lesson (${ctx.lessonNo}) or one of these target words: ${ctx.targetWords.join(', ')}. Do not explain grammar before he answers.`;
    const reply=await callClaudeAPIChat(buildAICoachSystemPrompt(),[{role:'user',text:kickoff}],350);
    progress.aiChatHistory.push({role:'model',text:reply||'Hi Erhan! Ready to practise?'});
    speakAIReply(reply||'');
    saveProgress(progress);
  }catch(err){
    progress.aiChatHistory.push({role:'model',text:'⚠️ '+friendlyApiErrorMessage(err)});
    saveProgress(progress);
  }
  if(currentView==='aichat'){ document.getElementById('content').innerHTML=viewAIChat(); scrollAIChatToBottom(); }
}
function clearAIChat(){
  if(!progress.aiChatHistory.length) return;
  if(!confirm('Tüm sohbet geçmişini silmek istediğine emin misin?')) return;
  progress.aiChatHistory = [];
  saveProgress(progress);
  if(currentView==='aichat') document.getElementById('content').innerHTML = viewAIChat();
}
function exportProgress(){
  progress.lastExportDate = todayStr();
  saveProgress(progress);
  const blob = new Blob([JSON.stringify(progress, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'ingilizce_defteri_ilerleme.json';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(()=>URL.revokeObjectURL(url), 1000);
}
function importProgress(file){
  if(!file) return;
  const reader = new FileReader();
  reader.onload = (e)=>{
    try{
      const imported = JSON.parse(e.target.result);
      progress = Object.assign({}, progress, imported);
      progress.lessonsDone = progress.lessonsDone || [];
      progress.quizScore = progress.quizScore || {correct:0,total:0};
      progress.wordQuizScore = progress.wordQuizScore || {correct:0,total:0};
      progress.knownWords = progress.knownWords || [];
      progress.notes = progress.notes || {};
      progress.customZor = progress.customZor || [];
      progress.customWords = progress.customWords || [];
      progress.customYeniKelimeler = progress.customYeniKelimeler || [];
      progress.lessonWordEdits = progress.lessonWordEdits || {};
      progress.deletedLessonWords = progress.deletedLessonWords || {};
      progress.visitDates = progress.visitDates || [];
      progress.lessonDoneDates = progress.lessonDoneDates || {};
      progress.wordSR = progress.wordSR || {};
      progress.customTopics = progress.customTopics || [];
      progress.aiChatHistory = progress.aiChatHistory || [];
      saveProgress(progress);
      applyDark();
      renderLessonList();
      renderCustomTopicsNav();
      updateDueBadge();
      navigate('dashboard');
      alert('İlerleme başarıyla içe aktarıldı.');
    }catch(err){
      alert('Dosya okunamadı: geçersiz format.');
    }
  };
  reader.readAsText(file);
}

// ---------- navigation ----------
let currentView = 'dashboard';
let currentLesson = null;
let highlightSentenceIdx = null;
let currentCustomTopicId = null;
let customTopicGroupFilter = {}; // { [customTopicId]: selectedCategoryName }
let customTopicSubFilter = {}; // { [customTopicId]: { [categoryName]: selectedSubheadingName } }

function navigate(view, lessonNo, sentenceIdx){
  currentView = view;
  updateTopActionButton();
  currentLesson = lessonNo || null;
  highlightSentenceIdx = (sentenceIdx===undefined || sentenceIdx===null) ? null : sentenceIdx;
  document.querySelectorAll('.navitem[data-view]').forEach(el=>{
    el.classList.toggle('active', el.dataset.view===view && !lessonNo);
  });
  document.querySelectorAll('.lesson-item').forEach(el=>{
    el.classList.toggle('active', lessonNo && parseInt(el.dataset.n)===lessonNo);
  });
  document.querySelectorAll('.custom-topic-item').forEach(el=> el.classList.remove('active'));
  if(window.innerWidth<=820) document.getElementById('sidebar').classList.remove('open');
  render();
}
// Ders görünümü çizildikten sonra, aranan/işaretli cümleye kaydırıp kısa süreliğine vurgular.
function scrollToHighlightedSentence(){
  if(highlightSentenceIdx===null || currentLesson===null) return;
  const targetId = 'sent-'+currentLesson+'-'+highlightSentenceIdx;
  const idx = highlightSentenceIdx;
  highlightSentenceIdx = null;
  setTimeout(()=>{
    const row = document.getElementById(targetId);
    if(!row) return;
    row.scrollIntoView({behavior:'smooth', block:'center'});
    row.classList.add('sentence-highlight');
    setTimeout(()=> row.classList.remove('sentence-highlight'), 2500);
  }, 30);
}

function toggleLessons(){
  document.getElementById('lessons-toggle').classList.toggle('open');
  document.getElementById('lesson-list').classList.toggle('open');
}

function renderLessonList(){
  const wrap = document.getElementById('lesson-list');
  wrap.innerHTML = DATA.lessons.map(l=>{
    const done = isDone(l.no);
    return `<div class="navitem lesson-item ${done?'done':''}" data-n="${l.no}" onclick="navigate('lesson', ${l.no})">
      <span class="dot"></span> ${l.no}. Ders <span style="opacity:.55;font-size:10px">${l.sourceNos?.length>1?'('+l.sourceNos[0]+'–'+l.sourceNos[l.sourceNos.length-1]+')':''}</span>
    </div>`;
  }).join('');
}

// ---------- My Topics (kullanıcının sol menüye eklediği özel başlıklar) ----------
function renderCustomTopicsNav(){
  const wrap = document.getElementById('custom-topics-list');
  if(!wrap) return;
  wrap.innerHTML = progress.customTopics.map(t=>{
    const icon = t.type==='note' ? '📝' : '💬';
    const active = (currentView==='customtopic' && currentCustomTopicId===t.id) ? ' active' : '';
    return `<div class="navitem custom-topic-item${active}" data-ctid="${t.id}" onclick="openCustomTopic('${t.id}')"><span class="dot"></span> ${icon} ${esc(t.title)}</div>`;
  }).join('');
}
function openCustomTopic(id){
  currentView = 'customtopic';
  currentCustomTopicId = id;
  document.querySelectorAll('.navitem[data-view]').forEach(el=> el.classList.remove('active'));
  if(window.innerWidth<=820) document.getElementById('sidebar').classList.remove('open');
  render();
  renderCustomTopicsNav();
}
function addCustomTopic(){
  const title = prompt('Yeni başlık adı (ör. "İş Görüşmesi Kalıpları"):');
  if(title===null) return;
  const t = title.trim();
  if(!t){ alert('Başlık boş bırakılamaz.'); return; }
  const typeChoice = prompt('İçerik türü:\n1 = İngilizce–Türkçe cümle/kalıp listesi\n2 = Serbest not (yazı)\n\nBir rakam gir (1 veya 2):', '1');
  if(typeChoice===null) return;
  const type = typeChoice.trim()==='2' ? 'note' : 'sentences';
  const id = 'ct_' + Date.now() + '_' + Math.floor(Math.random()*1000);
  const topic = { id, title: t, type, items: [], categories: [], subcategories: {}, content: '' };
  progress.customTopics.push(topic);
  saveProgress(progress);
  renderCustomTopicsNav();
  openCustomTopic(id);
}
function renameCustomTopic(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  const title = prompt('Başlığı düzenle:', t.title);
  if(title===null) return;
  const nt = title.trim();
  if(!nt){ alert('Başlık boş bırakılamaz.'); return; }
  t.title = nt;
  saveProgress(progress);
  renderCustomTopicsNav();
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function deleteCustomTopic(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  if(!confirm(`"${t.title}" başlığını ve tüm içeriğini silmek istediğine emin misin?`)) return;
  progress.customTopics = progress.customTopics.filter(x=>x.id!==id);
  saveProgress(progress);
  renderCustomTopicsNav();
  if(currentView==='customtopic' && currentCustomTopicId===id){ currentCustomTopicId=null; navigate('dashboard'); }
}
function addCustomTopicCategory(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  if(!t.categories) t.categories = [];
  const name = prompt('Yeni kategori adı gir (ör. "in", "on", "up"):');
  if(name===null) return;
  const g = name.trim();
  if(!g){ alert('Kategori adı boş bırakılamaz.'); return; }
  if(!t.categories.includes(g)) t.categories.push(g);
  customTopicGroupFilter[id] = g;
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function deleteCustomTopicCategory(id, cat){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  if(!confirm(`"${cat}" kategorisini silmek istiyor musun? İçindeki alt başlıklar da silinir. Cümleler silinmez, sadece kategorisiz kalır.`)) return;
  t.categories = (t.categories||[]).filter(c=>c!==cat);
  if(t.subcategories) delete t.subcategories[cat];
  t.items.forEach(it=>{ if((it[2]||'').trim()===cat){ it[2]=''; it[3]=''; } });
  if(customTopicSubFilter[id]) delete customTopicSubFilter[id][cat];
  if(customTopicGroupFilter[id]===cat){
    const cats = getCustomTopicCategories(t);
    customTopicGroupFilter[id] = cats.length ? cats[0] : undefined;
  }
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function getCustomTopicCategories(t){
  const cats = Array.from(t.categories || []);
  t.items.forEach(it=>{
    const g = (it[2]||'').trim();
    if(g && !cats.includes(g)) cats.push(g);
  });
  return cats;
}
function addCustomTopicSubcategory(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  const cat = customTopicGroupFilter[id];
  if(!cat){ alert('Önce bir kategori seç.'); return; }
  const name = prompt(`"${cat}" kategorisine yeni alt başlık gir (ör. "come in", "give up"):`);
  if(name===null) return;
  const g = name.trim();
  if(!g){ alert('Alt başlık adı boş bırakılamaz.'); return; }
  if(!t.subcategories) t.subcategories = {};
  if(!t.subcategories[cat]) t.subcategories[cat] = [];
  if(!t.subcategories[cat].includes(g)) t.subcategories[cat].push(g);
  if(!customTopicSubFilter[id]) customTopicSubFilter[id] = {};
  customTopicSubFilter[id][cat] = g;
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function getCustomTopicSubcategories(t, cat){
  const subs = Array.from((t.subcategories && t.subcategories[cat]) || []);
  t.items.forEach(it=>{
    if((it[2]||'').trim()!==cat) return;
    const s = (it[3]||'').trim();
    if(s && !subs.includes(s)) subs.push(s);
  });
  return subs;
}
function renameCustomTopicSubcategory(id, cat, oldSub){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  const name = prompt(`"${oldSub}" alt başlığını yeniden adlandır:`, oldSub);
  if(name===null) return;
  const g = name.trim();
  if(!g){ alert('Alt başlık adı boş bırakılamaz.'); return; }
  t.items.forEach(it=>{ if((it[2]||'').trim()===cat && (it[3]||'').trim()===oldSub) it[3] = g; });
  if(t.subcategories && t.subcategories[cat]){
    const idx = t.subcategories[cat].indexOf(oldSub);
    if(idx>-1) t.subcategories[cat][idx] = g;
  }
  if(customTopicSubFilter[id] && customTopicSubFilter[id][cat]===oldSub) customTopicSubFilter[id][cat] = g;
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function deleteCustomTopicSubcategory(id, cat, sub){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  if(!confirm(`"${sub}" alt başlığını silmek istiyor musun? Cümleler silinmez, sadece alt başlıksız kalır.`)) return;
  if(t.subcategories && t.subcategories[cat]) t.subcategories[cat] = t.subcategories[cat].filter(s=>s!==sub);
  t.items.forEach(it=>{ if((it[2]||'').trim()===cat && (it[3]||'').trim()===sub) it[3]=''; });
  if(customTopicSubFilter[id] && customTopicSubFilter[id][cat]===sub){
    const subs = getCustomTopicSubcategories(t, cat);
    customTopicSubFilter[id][cat] = subs.length ? subs[0] : undefined;
  }
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function addCustomTopicSentence(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  const newEn = prompt('Yeni cümle ekle (İngilizce):');
  if(newEn===null) return;
  const en = newEn.trim();
  if(!en){ alert('Cümle boş bırakılamaz.'); return; }
  const newTr = prompt('Türkçe çevirisi:');
  if(newTr===null) return;
  const tr = newTr.trim();
  if(!tr){ alert('Çeviri boş bırakılamaz.'); return; }
  const activeCat = customTopicGroupFilter[id];
  let category, subheading;
  if(activeCat){
    category = activeCat;
    const subs = getCustomTopicSubcategories(t, activeCat);
    const activeSub = (customTopicSubFilter[id] && customTopicSubFilter[id][activeCat]) || '';
    subheading = subs.length ? activeSub : '';
  } else {
    const cats = getCustomTopicCategories(t);
    const hint = cats.length ? (' (mevcut kategoriler: ' + cats.join(', ') + ')') : '';
    const newGroup = prompt('Kategori adı' + hint + ' — boş bırakabilirsin:', '');
    if(newGroup===null) return;
    category = newGroup.trim();
    subheading = '';
  }
  t.items.push([en, tr, category, subheading]);
  if(category){
    if(!t.categories) t.categories=[];
    if(!t.categories.includes(category)) t.categories.push(category);
  }
  if(category && subheading){
    if(!t.subcategories) t.subcategories={};
    if(!t.subcategories[category]) t.subcategories[category]=[];
    if(!t.subcategories[category].includes(subheading)) t.subcategories[category].push(subheading);
  }
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function editCustomTopicSentence(id, idx){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t || !t.items[idx]) return;
  const current = t.items[idx];
  const newEn = prompt('İngilizce cümleyi düzenle:', current[0]);
  if(newEn===null) return;
  const newTr = prompt('Türkçe çevirisini düzenle:', current[1]);
  if(newTr===null) return;
  const cats = getCustomTopicCategories(t);
  const catHint = cats.length ? (' (mevcut kategoriler: ' + cats.join(', ') + ')') : '';
  const newCat = prompt('Kategori adı' + catHint + ' — boş bırakabilirsin:', current[2] || '');
  if(newCat===null) return;
  const category = newCat.trim();
  let subheading = '';
  if(category){
    const subs = getCustomTopicSubcategories(t, category);
    const subHint = subs.length ? (' (mevcut alt başlıklar: ' + subs.join(', ') + ')') : '';
    const newSub = prompt('Alt başlık (kategori içi)' + subHint + ' — boş bırakabilirsin:', current[3] || '');
    if(newSub===null) return;
    subheading = newSub.trim();
  }
  const en = newEn.trim(), tr = newTr.trim();
  if(!en || !tr){ alert('Cümle boş bırakılamaz.'); return; }
  t.items[idx] = [en, tr, category, subheading];
  if(category){
    if(!t.categories) t.categories=[];
    if(!t.categories.includes(category)) t.categories.push(category);
  }
  if(category && subheading){
    if(!t.subcategories) t.subcategories={};
    if(!t.subcategories[category]) t.subcategories[category]=[];
    if(!t.subcategories[category].includes(subheading)) t.subcategories[category].push(subheading);
  }
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function deleteCustomTopicSentence(id, idx){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t || !t.items[idx]) return;
  if(!confirm('Bu cümleyi silmek istediğine emin misin?')) return;
  t.items.splice(idx,1);
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function saveCustomTopicNote(id, content){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  t.content = content;
  saveProgress(progress);
}
function toggleAllCustomTopicCheckboxes(id, checked){
  document.querySelectorAll('.ct-sel-'+id).forEach(cb=> cb.checked = checked);
}
function assignGroupToSelectedCustomTopicItems(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  const boxes = Array.from(document.querySelectorAll('.ct-sel-'+id)).filter(cb=>cb.checked);
  if(!boxes.length){ alert('Önce kategori vermek istediğin cümlelerin kutucuklarını işaretle.'); return; }
  const cats = getCustomTopicCategories(t);
  const hint = cats.length ? ('\n\nMevcut kategoriler: ' + cats.join(', ')) : '';
  const name = prompt(`Seçilen ${boxes.length} cümle için kategori adı gir. Boş bırakırsan kategorisiz olur:${hint}`, '');
  if(name===null) return;
  const g = name.trim();
  boxes.forEach(cb=>{
    const idx = parseInt(cb.dataset.idx);
    if(t.items[idx]){ t.items[idx][2] = g; t.items[idx][3] = ''; }
  });
  if(g){ if(!t.categories) t.categories=[]; if(!t.categories.includes(g)) t.categories.push(g); }
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function renameCustomTopicGroup(id, oldGroup){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return;
  const name = prompt(`"${oldGroup}" kategorisini yeniden adlandır:`, oldGroup);
  if(name===null) return;
  const g = name.trim();
  if(!g){ alert('Kategori adı boş bırakılamaz.'); return; }
  t.items.forEach(it=>{ if((it[2]||'').trim()===oldGroup) it[2] = g; });
  if(t.categories){
    const idx = t.categories.indexOf(oldGroup);
    if(idx>-1) t.categories[idx] = g;
  }
  if(t.subcategories && t.subcategories[oldGroup]){
    t.subcategories[g] = t.subcategories[oldGroup];
    delete t.subcategories[oldGroup];
  }
  if(customTopicGroupFilter[id]===oldGroup) customTopicGroupFilter[id] = g;
  if(customTopicSubFilter[id] && customTopicSubFilter[id][oldGroup]!==undefined){
    customTopicSubFilter[id][g] = customTopicSubFilter[id][oldGroup];
    delete customTopicSubFilter[id][oldGroup];
  }
  saveProgress(progress);
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function setCustomTopicGroupFilter(id, group){
  customTopicGroupFilter[id] = group;
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
function setCustomTopicSubFilter(id, cat, sub){
  if(!customTopicSubFilter[id]) customTopicSubFilter[id] = {};
  customTopicSubFilter[id][cat] = sub;
  if(currentView==='customtopic' && currentCustomTopicId===id) render();
}
// ---------- Hikayeler özel çalışma alanı ----------
function ensureStoryTopic(t){
  if(!t.storySubheadings) t.storySubheadings = [];
  if(!t.stories) t.stories = [];
  // Eski tek-parça notu ilk açılışta bir hikayeye dönüştür; veri kaybolmasın.
  if(t.title==='Hikayeler' && t.content && t.content.trim() && !t.stories.length){
    const lines = t.content.trim().split(/\n+/);
    const guessedTitle = (lines[0] || 'İlk Hikaye').trim();
    const body = t.content.trim();
    t.stories.push({id:'story_'+Date.now(), title:guessedTitle, en:body, tr:'', subheading:''});
    t.content = '';
    saveProgress(progress);
  }
}
function addStorySubheading(id){
  const t=progress.customTopics.find(x=>x.id===id); if(!t) return;
  ensureStoryTopic(t);
  const v=prompt('Yeni alt başlık adı (ör. A2 Hikayeler, Masallar, Seyahat):');
  if(v===null) return; const name=v.trim(); if(!name){alert('Alt başlık boş bırakılamaz.');return;}
  if(!t.storySubheadings.includes(name)) t.storySubheadings.push(name);
  saveProgress(progress); render();
}
function addStory(id){
  const t=progress.customTopics.find(x=>x.id===id); if(!t) return; ensureStoryTopic(t);
  const a=prompt('Hikaye adı:'); if(a===null) return; const title=a.trim(); if(!title){alert('Hikaye adı boş bırakılamaz.');return;}
  const e=prompt('İngilizce hikaye metni:'); if(e===null) return; const en=e.trim(); if(!en){alert('İngilizce metin boş bırakılamaz.');return;}
  const trRaw=prompt('Türkçe çeviri (isteğe bağlı):',''); if(trRaw===null) return; const tr=trRaw.trim();
  let sub='';
  if(t.storySubheadings.length){
    const s=prompt('Alt başlık seç/yaz (mevcut: '+t.storySubheadings.join(', ')+') — boş bırakabilirsin:','');
    if(s===null) return; sub=s.trim(); if(sub && !t.storySubheadings.includes(sub)) t.storySubheadings.push(sub);
  }
  t.stories.push({id:'story_'+Date.now()+'_'+Math.floor(Math.random()*1000),title,en,tr,subheading:sub});
  saveProgress(progress); render();
}
function editStory(id,sid){
  const t=progress.customTopics.find(x=>x.id===id); if(!t) return; ensureStoryTopic(t);
  const st=t.stories.find(x=>x.id===sid); if(!st) return;
  const a=prompt('Hikaye adını düzenle:',st.title); if(a===null) return;
  const e=prompt('İngilizce metni düzenle:',st.en); if(e===null) return;
  const tr=prompt('Türkçe çeviriyi düzenle:',st.tr||''); if(tr===null) return;
  const sub=prompt('Alt başlık:',st.subheading||''); if(sub===null) return;
  st.title=a.trim()||st.title; st.en=e.trim()||st.en; st.tr=tr.trim(); st.subheading=sub.trim();
  if(st.subheading && !t.storySubheadings.includes(st.subheading)) t.storySubheadings.push(st.subheading);
  saveProgress(progress); render();
}
function deleteStory(id,sid){
  const t=progress.customTopics.find(x=>x.id===id); if(!t) return;
  const st=(t.stories||[]).find(x=>x.id===sid); if(!st) return;
  if(!confirm('"'+st.title+'" hikayesini silmek istediğine emin misin?')) return;
  t.stories=t.stories.filter(x=>x.id!==sid); saveProgress(progress); render();
}
function editStorySubheading(id,name){
  const t=progress.customTopics.find(x=>x.id===id); if(!t) return; ensureStoryTopic(t);
  const v=prompt('Alt başlık adını düzenle:',name); if(v===null) return;
  const newName=v.trim(); if(!newName){alert('Alt başlık boş bırakılamaz.');return;}
  if(newName===name) return;
  if(t.storySubheadings.includes(newName)){alert('Bu alt başlık zaten var.');return;}
  const idx=t.storySubheadings.indexOf(name); if(idx<0) return;
  t.storySubheadings[idx]=newName;
  t.stories.forEach(st=>{if(st.subheading===name) st.subheading=newName;});
  saveProgress(progress); render();
}
function deleteStorySubheading(id,name){
  const t=progress.customTopics.find(x=>x.id===id); if(!t) return; ensureStoryTopic(t);
  if(!confirm('"'+name+'" alt başlığını silmek istiyor musun? Hikayeler silinmez, alt başlıksız kalır.')) return;
  t.storySubheadings=t.storySubheadings.filter(x=>x!==name);
  t.stories.forEach(st=>{if(st.subheading===name) st.subheading='';}); saveProgress(progress); render();
}
function viewStoryTopic(id,t){
  ensureStoryTopic(t);
  let h=`<div class="card" style="margin-bottom:14px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
    <button class="pill primary" onclick="addStory('${id}')">📖 + Yeni Hikaye</button>
    <button class="pill" onclick="addStorySubheading('${id}')">🗂️ + Alt Başlık Ekle</button>
    <span class="hint">Hikayelerini alt başlıklara ayırabilir, düzenleyebilir ve silebilirsin.</span></div>`;
  if(t.storySubheadings.length){
    h+=`<div class="card" style="margin-bottom:14px;"><b>Alt Başlıklar</b><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;">`;
    t.storySubheadings.forEach(x=>{h+=`<span class="pill">${esc(x)} <button class="spk" title="Alt başlığı düzenle" onclick="editStorySubheading('${id}','${escJs(x)}')">✏️</button> <button class="spk" title="Alt başlığı sil" onclick="deleteStorySubheading('${id}','${escJs(x)}')">🗑️</button></span>`});
    h+=`</div></div>`;
  }
  if(!t.stories.length) h+=`<div class="card"><div class="hint">Henüz hikaye yok. “+ Yeni Hikaye” ile ilk hikayeni ekleyebilirsin.</div></div>`;
  const groups=['',...t.storySubheadings];
  groups.forEach(g=>{
    const arr=t.stories.filter(st=>(st.subheading||'')===g); if(!arr.length) return;
    h+=`<div style="margin:18px 0 8px;font-weight:800;">${g?esc(g):'Alt Başlıksız Hikayeler'}</div>`;
    arr.forEach(st=>{
      h+=`<details class="card" style="margin-bottom:10px;"><summary style="cursor:pointer;font-weight:800;">📘 ${esc(st.title)}</summary>
      <div style="white-space:pre-wrap;line-height:1.7;margin-top:14px;">${esc(st.en)}</div>`;
      if(st.tr) h+=`<hr style="border:0;border-top:1px solid var(--line);margin:16px 0;"><div class="hint" style="margin-bottom:6px;">Türkçe çeviri</div><div style="white-space:pre-wrap;line-height:1.7;">${esc(st.tr)}</div>`;
      h+=`<div style="display:flex;gap:8px;margin-top:16px;"><button class="pill" onclick="editStory('${id}','${st.id}')">✏️ Düzenle</button><button class="pill" onclick="deleteStory('${id}','${st.id}')">🗑️ Sil</button></div></details>`;
    });
  });
  return h;
}

