const ESSENTIAL_CATEGORIES=['Tümü',...Array.from(new Set(ESSENTIAL_100.map(x=>x.cat)))];
function essentialKey(en){return String(en||'').toLowerCase().replace(/[’]/g,"'").replace(/[^a-z0-9' ]/g,'').replace(/\s+/g,' ').trim();}
const ESSENTIAL_LEGACY_KEYS=new Set(["How's it going?", "Long time no see!", "What have you been up to?", "How do you know each other?", "What do you do for a living?", "How was your day?", "What are you up to today?", "How have you been?", "Nice to meet you.", "Keep in touch!", "Let me think for a second.", "That's a good question.", "I'm not sure, but...", "I'd say...", "It depends.", "Give me a moment.", "How can I put it?", "What I mean is...", "Let me see...", "If I had to choose...", "Could you speak a bit slower, please?", "Could you repeat that, please?", "What do you mean by that?", "I don't understand.", "Could you say that again?", "I'm not sure I understand.", "What does that mean?", "How do you say this in English?", "Could you explain that?", "Did you mean...?", "In my opinion, ...", "To be honest, ...", "If you ask me, ...", "As far as I'm concerned, ...", "I think...", "I guess...", "It seems to me that...", "From my point of view, ...", "The way I see it, ...", "As far as I know, ...", "I agree with you.", "I don't think so.", "That makes sense.", "I'm not sure about that.", "I totally agree.", "I see your point, but...", "That's true, but...", "I'm not sure I agree.", "I disagree because...", "You may be right, but...", "I prefer...", "I'd rather...", "My first choice would be...", "I'm more into...", "Either one is fine with me.", "I don't mind.", "It depends on my mood.", "I'd go with...", "Both sound good, but...", "I'd probably choose...", "Could you do me a favor?", "Would you mind helping me?", "Do you need any help?", "Is it okay if I use this?", "Could you give me a hand?", "Let me know if you need anything.", "Thanks in advance!", "Could you help me with this?", "Would it be possible to...?", "Can I ask you something?", "That sounds like a great idea!", "That's great!", "I'm glad to hear that.", "I'm sorry to hear that.", "No way!", "Really? Tell me more.", "That must be difficult.", "I'm really looking forward to it.", "I'm a bit nervous about it.", "It slipped my mind.", "Are you free this weekend?", "Let's catch up soon.", "Something has come up.", "Can we reschedule for another time?", "I'm running a bit late.", "It depends on my schedule.", "Let's call it a day.", "I have to run now.", "What time works for you?", "I'll get back to you later.", "How much does this cost?", "Where can I buy a ticket?", "Could I have the bill, please?", "I'd like to check in.", "I have a reservation.", "How do I get to the city center?", "Is this seat taken?", "Could you show me on the map?", "I'm just looking, thanks.", "Could I get this to go?"].map(essentialKey));
const ESSENTIAL_META=Object.fromEntries(ESSENTIAL_100.map(x=>[essentialKey(x.en),x]));
function ensureEssential100(t){
  if(!t||!Array.isArray(t.items))return false;
  const canonical=new Set(ESSENTIAL_100.map(x=>essentialKey(x.en)));
  // v67: remove only old built-in Essential items; preserve genuinely user-added phrases.
  const extras=t.items.filter(x=>{const k=essentialKey(x?.[0]);return k&&!ESSENTIAL_LEGACY_KEYS.has(k)&&!canonical.has(k);});
  t.items=ESSENTIAL_100.map(x=>[x.en,x.tr]).concat(extras);
  return true;
}
function essentialCategory(it){return ESSENTIAL_META[essentialKey(it?.[0])]?.cat||'Diğer';}
function essentialFiltered(t){const all=t.items||[];return essentialProState.cat==='Tümü'?all:all.filter(x=>essentialCategory(x)===essentialProState.cat);}
function setEssentialCategory(id,cat){essentialProState={id,mode:essentialProState.mode||'learn',idx:0,cat};render();}
function setEssentialMode(id,mode){essentialProState={id,mode,idx:0,cat:essentialProState.cat||'Tümü'};render();}
function nextEssentialItem(id){const t=progress.customTopics.find(x=>x.id===id);if(!t)return;const a=essentialFiltered(t);if(!a.length)return;essentialProState.idx=(essentialProState.idx+1)%a.length;render();}
function recordEssential(en,ok){const k=essentialKey(en),m=progress.essentialTraining[k]||{correct:0,wrong:0};ok?m.correct++:m.wrong++;m.lastSeen=Date.now();progress.essentialTraining[k]=m;saveProgress(progress);}
function currentEssential(id){const t=progress.customTopics.find(x=>x.id===id);if(!t)return null;ensureEssential100(t);const a=essentialFiltered(t);return {t,a,it:a[essentialProState.idx%Math.max(1,a.length)]};}
function essentialCheckRecall(id){const c=currentEssential(id),it=c?.it;if(!it)return;const inp=document.getElementById('essential-answer'),fb=document.getElementById('essential-feedback');const ok=normalizeAnswer(inp.value)===normalizeAnswer(it[0]);recordEssential(it[0],ok);fb.innerHTML=ok?`<b>✅ Doğru.</b> ${esc(it[0])}`:`<b>❌ Henüz değil.</b><br>Doğal ifade: <b>${esc(it[0])}</b>`;}
function essentialFallbackUse(target,val,phraseOk){
  if(!phraseOk)return `<b>🔁 Hedef kalıp henüz cümlede görünmüyor.</b><br>Önce <b>${esc(target)}</b> ifadesini doğal bir cümlede kullan.`;
  return `<b>✅ Kalıbı kullandın.</b><br><span class="hint">🤖 Ayrıntılı öğretmen değerlendirmesi şu an alınamadı. Cümleni tense, kelime sırası ve doğallık açısından bir kez daha oku; kalıp kullanımı doğru olarak kaydedildi.</span>`;
}
async function essentialCheckUse(id){
  const c=currentEssential(id),it=c?.it;if(!it)return;
  const val=(document.getElementById('essential-answer')?.value||'').trim(),fb=document.getElementById('essential-feedback');if(!val){fb.textContent='Önce kendi cümleni yaz.';return;}
  const target=essentialKey(it[0]).trim(), words=target.split(' ').filter(w=>w.length>2),low=essentialKey(val),hits=words.filter(w=>low.includes(w)).length;
  const phraseOk=words.length?hits/words.length>=0.65:val.length>4; recordEssential(it[0],phraseOk);
  if(!phraseOk){fb.innerHTML=essentialFallbackUse(it[0],val,false);return;}
  fb.innerHTML='🤖 Cümlenin tamamını değerlendiriyorum…';
  try{
    const sys=`You are an English speaking/writing coach for an A2-B1 Turkish learner. Fluency and communication come first. The learner is practising one target phrase inside a self-made sentence. Do not over-correct minor articles, punctuation, or tiny preposition issues unless they affect naturalness. Check the WHOLE sentence, especially tense consistency, word order, meaning and natural usage. Return ONLY valid JSON with keys phrase_use, sentence, correction, reason. phrase_use must be "good" or "retry". sentence must be "natural", "understandable", or "needs_fix". correction: empty string if no meaningful correction is needed, otherwise one natural corrected sentence. reason: one short Turkish explanation.`;
    const raw=await callClaudeAPI(sys,`TARGET PHRASE: ${it[0]}\nTURKISH MEANING: ${it[1]}\nLEARNER SENTENCE: ${val}`,500);
    const clean=raw.replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim(); const j=JSON.parse(clean);
    const good=j.phrase_use!=='retry';
    fb.innerHTML=`<b>${good?'✅':'🔁'} Kalıp kullanımı:</b> ${good?'Doğru yerde kullanılmış.':'Bir kez daha dene.'}<br><b>🧩 Cümlenin tamamı:</b> ${j.sentence==='natural'?'Doğal':j.sentence==='understandable'?'Anlaşılır; geliştirilebilir':'Önemli düzeltme gerekiyor'}${j.correction?`<br><b>✨ Daha doğal:</b> ${esc(j.correction)}`:''}${j.reason?`<br><b>💡 Neden?</b> ${esc(j.reason)}`:''}`;
  }catch(e){fb.innerHTML=essentialFallbackUse(it[0],val,true);}
}
function essentialSpeak(id){const c=currentEssential(id),it=c?.it;if(!it)return;const SR=window.SpeechRecognition||window.webkitSpeechRecognition,fb=document.getElementById('essential-feedback');if(!SR){fb.textContent='Bu tarayıcıda konuşma tanıma yok. Yazarak çalışabilirsin.';return;}const r=new SR();r.lang='en-US';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const heard=e.results[0][0].transcript||'';const score=orderedWordScore(it[0],heard);recordEssential(it[0],score>=0.65);fb.innerHTML=`Duyduğum: <b>${esc(heard)}</b><br>${score>=0.65?'✅ Yeterince yakın.':'🔁 Tekrar dene.'}`;};r.onerror=e=>fb.textContent='Mikrofon: '+e.error;r.start();fb.textContent='🎤 Dinliyorum…';}
function viewEssentialPro(id,t){
  ensureEssential100(t);
  const items=t.items||[]; if(!items.length)return '<div class="card">Henüz ifade yok.</div>';
  if(essentialProState.id!==id) essentialProState={id,mode:'learn',idx:0,cat:'Tümü'};
  const filtered=essentialFiltered(t); if(!filtered.length){essentialProState.cat='Tümü';essentialProState.idx=0;}
  const list=essentialFiltered(t),it=list[essentialProState.idx%list.length],mode=essentialProState.mode;
  const canonicalCount=items.filter(x=>ESSENTIAL_META[essentialKey(x[0])]).length;
  const trained=items.filter(x=>{const m=progress.essentialTraining[essentialKey(x[0])];return m&&(m.correct||m.wrong)}).length;
  let h=`<div class="card" style="border-left:4px solid var(--gold);"><h3 style="margin-top:0;">💬 Essential 100 · Conversation Fluency PRO</h3><div class="hint"><b>${canonicalCount}/100</b> temel ifade hazır. Amaç seyahat cümlesi ezberlemek değil: gerçek sohbette cevabı başlat → zaman kazan → tepki ver → konuşmayı sürdür. <b>${trained}</b> ifadeyle aktif pratik yaptın.</div>`;
  h+=`<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:13px;">${ESSENTIAL_CATEGORIES.map(cat=>`<button class="pill ${essentialProState.cat===cat?'primary':''}" onclick="setEssentialCategory('${id}','${escJs(cat)}')">${cat==='Tümü'?'🌐 ':''}${esc(cat)}${cat==='Tümü'?' · '+items.length:''}</button>`).join('')}</div>`;
  h+=`<div class="tab-row" style="margin-top:12px;">${[['learn','👁 Öğren'],['recall','🧠 Hatırla'],['speak','🎤 Söyle'],['use','🎲 Kullan']].map(([k,l])=>`<button class="tab-btn ${mode===k?'active':''}" onclick="setEssentialMode('${id}','${k}')">${l}</button>`).join('')}</div></div>`;
  h+=`<div class="card"><div class="hint"><b>${esc(essentialProState.cat)}</b> · ${essentialProState.idx+1} / ${list.length}</div>`;
  if(mode==='learn')h+=`<h2>${spk(it[0])}${esc(it[0])}</h2><p>${esc(it[1])}</p><div class="hint">Önce dinle, sonra ekrana bakmadan bir kez söyle.</div>`;
  if(mode==='recall')h+=`<h3>🇹🇷 ${esc(it[1])}</h3><input id="essential-answer" class="quiz-input" placeholder="İngilizcesini hatırla…"><button class="pill primary" onclick="essentialCheckRecall('${id}')">Kontrol Et</button>`;
  if(mode==='speak')h+=`<h3>🇹🇷 ${esc(it[1])}</h3><div class="hint">İngilizcesini yüksek sesle söyle. Mikrofon hedef ifadeye yakınlığını kontrol eder.</div><button class="pill primary" onclick="essentialSpeak('${id}')">🎤 Şimdi Söyle</button>`;
  if(mode==='use')h+=`<h3>${esc(it[0])}</h3><div class="hint">Bu ifadeyi doğal bir İngilizce cümlenin içinde kullan. Kontrol, sadece kalıbı değil <b>cümlenin tamamını</b> değerlendirir.</div><input id="essential-answer" class="quiz-input" placeholder="Kendi cümlen…"><button class="pill primary" onclick="essentialCheckUse('${id}')">🤖 Cümleyi Değerlendir</button>`;
  h+=`<div id="essential-feedback" class="hint" style="margin-top:10px;"></div><div style="margin-top:14px;"><button class="pill" onclick="nextEssentialItem('${id}')">Sonraki İfade ›</button></div></div>`;
  h+=`<details class="card"><summary>📚 Tüm ifadeleri / düzenleme araçlarını göster</summary><div class="hint" style="margin:10px 0;">Kendi eklediğin ifadeler korunur. Temel 100 ifade kategori sistemiyle çalışır.</div><table class="data"><tbody>${items.map((x,i)=>`<tr><td class="en">${spk(x[0])}${esc(x[0])}</td><td class="tr">${esc(x[1])}</td><td>${esc(essentialCategory(x))}</td><td><button class="spk" onclick="editCustomTopicSentence('${id}',${i})">✏️</button></td></tr>`).join('')}</tbody></table><button class="pill primary" onclick="addCustomTopicSentence('${id}')">➕ Cümle Ekle</button></details>`;
  return h;
}

function viewCustomTopic(id){
  const t = progress.customTopics.find(x=>x.id===id);
  if(!t) return '<div class="card">Başlık bulunamadı.</div>';
  if(!t.categories) t.categories = [];
  if(!t.subcategories) t.subcategories = {};
  let html = `<div style="display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; margin-bottom:16px;">
    <div class="hint">${t.type==='note' ? 'Serbest not' : 'İngilizce–Türkçe kalıp listesi'}</div>
    <div style="display:flex; gap:8px;">
      <button class="pill" onclick="renameCustomTopic('${id}')">✏️ Başlığı Düzenle</button>
      <button class="pill" onclick="deleteCustomTopic('${id}')">🗑️ Başlığı Sil</button>
    </div>
  </div>`;
  if(/100\s+Essential English Phrases/i.test(t.title)){
    html += viewEssentialPro(id,t);
  } else if(t.title==='Hikayeler'){
    html += viewStoryTopic(id,t);
  } else if(t.type==='note'){
    html += `<div class="card">
      <textarea id="custom-note-${id}" style="width:100%; min-height:320px; resize:vertical; font-size:15px; line-height:1.6; border:1px solid var(--line); border-radius:8px; padding:12px; background:transparent; color:inherit;" placeholder="Notlarını buraya yaz…" onblur="saveCustomTopicNote('${id}', this.value)">${esc(t.content)}</textarea>
      <div class="hint" style="margin-top:8px;">Yazdıkların, bu alandan çıktığında (odak kaybolduğunda) otomatik kaydedilir.</div>
    </div>`;
  } else {
    html += `<div class="card" style="margin-bottom:14px; display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
      <button class="pill primary" onclick="addCustomTopicCategory('${id}')">🗂️ Kategori Ekle</button>
      <span class="hint">Önce kategori oluştur (ör. "in"), sonra o kategori içinde alt başlık oluştur (ör. "come in"), sonra cümle ekle.</span>
    </div>`;

    const categories = getCustomTopicCategories(t);
    let activeCat = customTopicGroupFilter[id];
    if(categories.length && (activeCat===undefined || !categories.includes(activeCat))){
      activeCat = categories[0];
      customTopicGroupFilter[id] = activeCat;
    }
    if(!categories.length) activeCat = undefined;

    if(categories.length){
      html += `<div class="tab-row">`;
      categories.forEach(cat=>{
        const isActive = (activeCat===cat) ? ' active' : '';
        html += `<button class="tab-btn${isActive}" onclick="setCustomTopicGroupFilter('${id}', '${escJs(cat)}')">${esc(cat)}</button>`;
      });
      html += `</div>`;
      if(activeCat){
        html += `<div class="hint" style="margin:-6px 0 14px 2px;">Kategori: <b>${esc(activeCat)}</b> <button class="spk" title="Kategoriyi yeniden adlandır" onclick="renameCustomTopicGroup('${id}', '${escJs(activeCat)}')">✏️</button><button class="spk" title="Kategoriyi sil" onclick="deleteCustomTopicCategory('${id}', '${escJs(activeCat)}')">🗑️</button></div>`;
      }
    }

    let activeSub;
    let subs = [];
    if(activeCat){
      subs = getCustomTopicSubcategories(t, activeCat);
      if(!customTopicSubFilter[id]) customTopicSubFilter[id] = {};
      activeSub = customTopicSubFilter[id][activeCat];
      if(subs.length && (activeSub===undefined || !subs.includes(activeSub))){
        activeSub = subs[0];
        customTopicSubFilter[id][activeCat] = activeSub;
      }
      html += `<div class="card" style="margin-bottom:14px; display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
        <button class="pill" onclick="addCustomTopicSubcategory('${id}')">➕ "${esc(activeCat)}" içine Alt Başlık Ekle</button>
        <span class="hint">Ör. "come in", "give up" gibi — bu kategori içindeki cümleleri gruplar.</span>
      </div>`;
      if(subs.length){
        html += `<div class="tab-row">`;
        subs.forEach(sub=>{
          const isActive = (activeSub===sub) ? ' active' : '';
          html += `<button class="tab-btn${isActive}" onclick="setCustomTopicSubFilter('${id}', '${escJs(activeCat)}', '${escJs(sub)}')">${esc(sub)}</button>`;
        });
        html += `</div>`;
        if(activeSub){
          html += `<div class="hint" style="margin:-6px 0 14px 2px;">Alt başlık: <b>${esc(activeSub)}</b> <button class="spk" title="Alt başlığı yeniden adlandır" onclick="renameCustomTopicSubcategory('${id}', '${escJs(activeCat)}', '${escJs(activeSub)}')">✏️</button><button class="spk" title="Alt başlığı sil" onclick="deleteCustomTopicSubcategory('${id}', '${escJs(activeCat)}', '${escJs(activeSub)}')">🗑️</button></div>`;
        }
      }
    }

    if(t.items.length){
      html += `<div class="card" style="margin-bottom:14px; display:flex; align-items:center; gap:14px; flex-wrap:wrap;">
        <label style="display:flex; align-items:center; gap:6px; font-size:13px; cursor:pointer;"><input type="checkbox" onclick="toggleAllCustomTopicCheckboxes('${id}', this.checked)"> Tümünü Seç</label>
        <button class="pill" onclick="assignGroupToSelectedCustomTopicItems('${id}')">🏷️ Seçilenlere Kategori Ata</button>
        <span class="hint">Cümleleri işaretle, sonra bir kategori adı ver — o kategoriye taşınırlar (alt başlıkları sıfırlanır).</span>
      </div>`;
    }

    const visibleItems = [];
    t.items.forEach((item, idx)=>{
      const cat = (item[2]||'').trim();
      const sub = (item[3]||'').trim();
      if(activeCat){
        if(cat!==activeCat) return;
        if(subs.length && sub!==activeSub) return;
      }
      visibleItems.push({item, idx});
    });

    html += `<table class="data"><tbody>`;
    visibleItems.forEach(({item, idx})=>{
      const en = item[0], tr = item[1];
      html += `<tr><td style="width:26px;"><input type="checkbox" class="ct-sel-${id}" data-idx="${idx}"></td><td class="en">${spk(en)}${esc(en)}</td><td class="tr">${esc(tr)}</td><td style="white-space:nowrap;"><button class="spk" title="Cümleyi düzenle" onclick="editCustomTopicSentence('${id}', ${idx})">✏️</button><button class="spk" title="Cümleyi sil" onclick="deleteCustomTopicSentence('${id}', ${idx})">🗑️</button></td></tr>`;
    });
    if(!visibleItems.length){
      html += `<tr><td colspan="4" class="hint" style="padding:8px 10px;">Henüz cümle yok — aşağıdaki "Cümle Ekle" ile buraya cümle ekleyebilirsin.</td></tr>`;
    }
    html += `</tbody></table>`;
    html += `<div class="card" style="margin-top:16px;">
      <button class="pill primary" onclick="addCustomTopicSentence('${id}')">➕ Cümle Ekle</button>
    </div>`;
  }
  return html;
}

// ---------- helpers ----------
function esc(s){
  return (s===undefined||s===null?'':String(s)).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function escJs(s){
  return (s===undefined||s===null?'':String(s)).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
}
function speak(text){
  try{
    if(!('speechSynthesis' in window) || !text) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'en-US';
    u.rate = progress.speechRate || 1;
    window.speechSynthesis.speak(u);
  }catch(e){}
}
function toggleSpeechRate(){
  progress.speechRate = progress.speechRate>=1 ? 0.65 : 1;
  saveProgress(progress);
  const lbl = document.getElementById('rate-label');
  if(lbl) lbl.textContent = 'Konuşma Hızı: ' + (progress.speechRate>=1 ? 'Normal' : 'Yavaş');
}
function spk(text){
  return `<button class="spk" title="Dinle" onclick="event.stopPropagation(); speak('${escJs(text)}')">🔊</button><button class="spk" title="Yavaş dinle" onclick="event.stopPropagation(); speakRate('${escJs(text)}', 0.5)">🐢</button><button class="spk mic" title="Telaffuz pratiği (mikrofon)" onclick="event.stopPropagation(); practicePronunciation('${escJs(text)}', this)">🎤</button>`;
}
function speakRate(text, rate){
  try{
    if(!('speechSynthesis' in window) || !text) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'en-US';
    u.rate = rate;
    window.speechSynthesis.speak(u);
  }catch(e){}
}
function normalizePracticeText(s, opts={}){
  let x=(s||'').normalize('NFKC').toLowerCase()
    .replace(/[\u2018\u2019\u0060\u00b4]/g, "'")
    .replace(/[\u201c\u201d]/g, '"');
  if(opts.ignorePunctuation!==false) x=x.replace(/[^a-z0-9\s]/g,' ');
  return x.replace(/\s+/g,' ').trim();
}
function normSpeech(s){ return normalizePracticeText(s); }
function mergeTranscriptText(base, incoming){
  const a=normalizePracticeText(base).split(' ').filter(Boolean), b=normalizePracticeText(incoming).split(' ').filter(Boolean);
  if(!a.length) return (incoming||'').trim(); if(!b.length) return (base||'').trim();
  if(a.join(' ')==b.join(' ')) return (base||'').trim();
  let overlap=0, max=Math.min(a.length,b.length);
  for(let k=1;k<=max;k++) if(a.slice(-k).join(' ')==b.slice(0,k).join(' ')) overlap=k;
  if(overlap) return (base+' '+b.slice(overlap).join(' ')).replace(/\s+/g,' ').trim();
  if(a.length>=b.length && a.slice(-b.length).join(' ')==b.join(' ')) return (base||'').trim();
  return (base+' '+incoming).replace(/\s+/g,' ').trim();
}
function wordSequenceScore(a,b){
  const x=normalizePracticeText(a).split(' ').filter(Boolean), y=normalizePracticeText(b).split(' ').filter(Boolean);
  if(!x.length||!y.length) return 0;
  const dp=Array.from({length:x.length+1},()=>Array(y.length+1).fill(0));
  for(let i=0;i<=x.length;i++) dp[i][0]=i; for(let j=0;j<=y.length;j++) dp[0][j]=j;
  for(let i=1;i<=x.length;i++) for(let j=1;j<=y.length;j++) dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(x[i-1]===y[j-1]?0:1));
  const dist=dp[x.length][y.length], denom=Math.max(x.length,y.length);
  return Math.max(0,Math.round(100*(1-dist/denom)));
}
function wordMatchScore(a,b){ return wordSequenceScore(a,b); }

// ---------- shared toggleable recorder (speech-to-text + playable audio) ----------
// MediaRecorder drives start/stop reliably (its stop() event always fires).
// SpeechRecognition runs alongside, best-effort, just to accumulate a transcript —
// we never wait on its own onend, since some browsers don't fire it reliably.
let recordingActive = false;
let activeMediaRec = null;
let activeMediaChunks = [];
let activeSpeechRec = null;
let activeTranscript = '';
let activeTranscriptInterim = '';
let speechRecSupported = true;
let speechRecErrorReason = '';
function beginVoiceRecording(onAudioReady){
  if(!voiceEnvironmentGuard()) return false;
  activeTranscript = '';
  activeTranscriptInterim = '';
  activeMediaChunks = [];
  activeMediaRec = null;
  activeSpeechRec = null;
  speechRecErrorReason = '';
  recordingActive = true;

  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  speechRecSupported = !!SR;

  // IMPORTANT: Never open SpeechRecognition and MediaRecorder at the same time.
  // Samsung/Android Chrome often gives one of them an empty mic stream, which caused
  // Shadowing to show "(algılanamadı)" even when the learner spoke clearly.
  if(SR){
    try{
      activeSpeechRec = new SR();
      activeSpeechRec.lang = 'en-US';
      activeSpeechRec.continuous = true;
      activeSpeechRec.interimResults = true;
      activeSpeechRec.maxAlternatives = 3;
      activeSpeechRec.onresult = (e)=>{
        let interim = '';
        for(let i=e.resultIndex;i<e.results.length;i++){
          const txt = (e.results[i][0] && e.results[i][0].transcript) || '';
          if(e.results[i].isFinal) activeTranscript = mergeTranscriptText(activeTranscript, txt);
          else interim = mergeTranscriptText(interim, txt);
        }
        activeTranscriptInterim = interim;
      };
      activeSpeechRec.onerror = (e)=>{
        speechRecErrorReason = e.error || 'unknown';
      };
      activeSpeechRec.onend = ()=>{};
      activeSpeechRec.start();
      return true;
    }catch(e){
      activeSpeechRec = null;
      speechRecSupported = false;
      speechRecErrorReason = 'speech-start-failed';
    }
  }

  // Fallback: if speech recognition is unavailable, at least record playable audio
  // so the learner can self-check manually.
  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia || typeof MediaRecorder==='undefined'){
    recordingActive = false;
    alert('Bu tarayıcı konuşma tanıma veya mikrofon kaydı özelliklerini desteklemiyor.');
    return false;
  }
  navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{
    if(!recordingActive){ stream.getTracks().forEach(t=>t.stop()); return; }
    try{
      const mr = new MediaRecorder(stream);
      activeMediaRec = mr;
      mr.ondataavailable = e=>{ if(e.data.size>0) activeMediaChunks.push(e.data); };
      mr.onstop = ()=>{
        stream.getTracks().forEach(t=>t.stop());
        const audioUrl = activeMediaChunks.length ? URL.createObjectURL(new Blob(activeMediaChunks, {type:mr.mimeType||'audio/webm'})) : null;
        if(onAudioReady) onAudioReady(audioUrl);
      };
      mr.start();
    }catch(e){
      stream.getTracks().forEach(t=>t.stop());
      speechRecErrorReason='media-recorder-failed';
    }
  }).catch(e=>{
    recordingActive=false;
    speechRecErrorReason='not-allowed';
    alert('Mikrofon açılamadı. Chrome → Site ayarları → Mikrofon iznini kontrol et.');
  });
  return true;
}
function stopVoiceRecording(onDone){
  recordingActive = false;
  if(activeSpeechRec){ try{ activeSpeechRec.stop(); }catch(e){} }
  if(activeMediaRec && activeMediaRec.state!=='inactive'){ try{ activeMediaRec.stop(); }catch(e){} }
  // grace period lets the last speech-recognition result finalize; the button
  // itself never waits longer than this, regardless of what the browser events do.
  setTimeout(()=>{
    // fall back to whatever interim (not-yet-final) text was heard, if nothing finalized
    const transcript = (activeTranscript.trim() || activeTranscriptInterim.trim());
    if(onDone) onDone(transcript, speechRecSupported, speechRecErrorReason);
  }, 1200);
}


let manualOfflineMode = localStorage.getItem('ing_defter_offline_mode') === '1';
function isAppOffline(){ return manualOfflineMode || !navigator.onLine; }
function updateOfflineUI(){
  const badge=document.getElementById('offline-badge');
  if(!badge) return;
  const off=isAppOffline();
  badge.textContent=off?'✈️ Offline':'🌐 Online';
  badge.title=off?'AI ve internet gerektiren özellikler kapalı.':'İnternet bağlantısı aktif.';
}
function toggleOfflineMode(){
  manualOfflineMode=!manualOfflineMode;
  localStorage.setItem('ing_defter_offline_mode',manualOfflineMode?'1':'0');
  updateOfflineUI();
  alert(manualOfflineMode ? '✈️ Offline Mod açıldı. AI çağrıları yapılmayacak.' : '🌐 Offline Mod kapatıldı. İnternet varsa AI yeniden kullanılabilir.');
}
function offlineAIMessage(){ return '✈️ Offline Mod: Ares ve AI değerlendirmeleri internet gerektiriyor.'; }
window.addEventListener('online',updateOfflineUI);
window.addEventListener('offline',updateOfflineUI);
window.addEventListener('load',updateOfflineUI);

function voiceEnvironmentStatus(){
  const proto=location.protocol;
  const secure=window.isSecureContext;
  const hasSR=!!(window.SpeechRecognition||window.webkitSpeechRecognition);
  const hasGUM=!!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia);
  return {proto,secure,hasSR,hasGUM};
}
function voiceEnvironmentGuard(){
  const s=voiceEnvironmentStatus();
  if(s.secure) return true;
  alert('🎤 Sesli özellikler bu açılış biçiminde kullanılamıyor.\n\nŞu an: '+s.proto+' üzerinden açıldı.\n\nProgramı HTTPS adresinden veya localhost üzerinden aç. Chrome mikrofon iznin açık olsa bile content:// / file:// sayfalarında tarayıcı erişimi engelleyebilir.');
  return false;
}

function voiceErrorMessage(code){
  const map={
    'no-speech':'Ses algılanamadı. Konuşmaya düğmeye bastıktan yaklaşık yarım saniye sonra başla ve mikrofona biraz daha yakın konuş.',
    'not-allowed':'Mikrofon izni verilmedi.',
    'service-not-allowed':'Chrome konuşma tanıma servisine izin vermedi.',
    'audio-capture':'Mikrofon kullanılamıyor veya başka bir uygulama tarafından tutuluyor.',
    'network':'Google konuşma tanıma servisine ulaşılamadı; internet bağlantısını kontrol et.',
    'aborted':'Kayıt yarıda kesildi.',
    'speech-start-failed':'Konuşma tanıma başlatılamadı.'
  };
  return map[code] || (code ? 'Ses tanıma hatası: '+code : '');
}
function playbackHtml(audioUrl){
  return audioUrl ? `<div style="margin-top:8px;"><audio controls src="${audioUrl}" style="width:100%; max-width:320px;"></audio></div>` : '';
}
function practicePronunciation(target, btn){
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SR){ btn.title = 'Tarayıcın ses tanımayı desteklemiyor'; btn.textContent='🚫'; setTimeout(()=>btn.textContent='🎤', 1500); return; }
  if(window.isSecureContext===false){
    alert('Telaffuz pratiği (mikrofon) için dosyanın bir web sunucusundan (https) açılması gerekiyor — doğrudan diskten (file://) açıldığında tarayıcı mikrofon erişimini engelliyor. Diğer tüm özellikler normal çalışır.');
    return;
  }
  let rec;
  try{ rec = new SR(); }catch(e){ return; }
  rec.lang = 'en-US';
  rec.interimResults = false;
  rec.maxAlternatives = 1;
  const orig = '🎤';
  btn.textContent = '🔴';
  const targetNorm = normSpeech(target);
  rec.onresult = (e)=>{
    const said = normSpeech(e.results[0][0].transcript);
    const pct = said===targetNorm ? 100 : wordMatchScore(targetNorm, said);
    progress.pronScore.sum += pct;
    progress.pronScore.count++;
    saveProgress(progress);
    btn.textContent = pct+'%';
    btn.title = 'Duyulan: "'+said+'" — Skor: '+pct+'%';
    setTimeout(()=>{ btn.textContent = orig; btn.title='Telaffuz pratiği (mikrofon)'; }, 2400);
  };
  rec.onerror = (e)=>{
    btn.textContent='⚠️';
    if(e.error==='not-allowed' || e.error==='service-not-allowed'){
      btn.title = 'Mikrofon izni verilmedi';
    }
    setTimeout(()=>btn.textContent=orig, 1500);
  };
  rec.onend = ()=>{ if(btn.textContent==='🔴') btn.textContent = orig; };
  try{ rec.start(); }catch(e){ btn.textContent = orig; }
}

// ---------- voice navigation ----------
function voiceNavigate(btn){
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SR){ alert('Tarayıcın sesli komutu desteklemiyor.'); return; }
  if(window.isSecureContext===false){
    alert('Sesli komut çalışmıyor çünkü dosya doğrudan diskten (file://) açılmış — tarayıcılar mikrofon erişimini sadece "güvenli" bağlantılarda (https veya bir web sunucusu üzerinden) veriyor.\n\nÇözüm: Dosyayı basit ve ücretsiz bir barındırma servisine (örn. Netlify Drop, GitHub Pages) yükleyip oradan açarsan bu özellik çalışır. Diğer tüm özellikler (quiz, kelime kartları, sesli okuma vb.) dosyadan açıldığında zaten normal çalışıyor, sadece mikrofon gerektiren özellikler (sesli komut ve telaffuz pratiği) güvenli bağlantı istiyor.');
    return;
  }
  let rec;
  try{ rec = new SR(); }catch(e){ alert('Ses tanıma başlatılamadı: '+e.message); return; }
  rec.lang = 'tr-TR';
  rec.interimResults = false;
  rec.maxAlternatives = 1;
  const orig = btn.textContent;
  btn.textContent = '🔴 Dinliyor…';
  rec.onresult = (e)=>{
    const said = e.results[0][0].transcript.toLowerCase();
    btn.textContent = orig;
    handleVoiceCommand(said);
  };
  rec.onerror = (e)=>{
    btn.textContent = orig;
    const reasons = {
      'not-allowed':'Mikrofon izni verilmedi. Tarayıcı adres çubuğundaki kilit/site ayarları simgesinden bu sayfa için mikrofon iznini açman gerekiyor.',
      'service-not-allowed':'Mikrofon izni verilmedi. Tarayıcı adres çubuğundaki kilit/site ayarları simgesinden bu sayfa için mikrofon iznini açman gerekiyor.',
      'no-speech':'Ses algılanamadı, tekrar dener misin?',
      'audio-capture':'Mikrofon bulunamadı. Cihazında çalışan bir mikrofon olduğundan emin ol.',
      'network':'Ses tanıma için internet bağlantısı gerekiyor, bağlantını kontrol et.'
    };
    const msg = reasons[e.error];
    if(msg) alert(msg);
    else if(e.error && e.error!=='aborted') alert('Ses tanıma hatası: '+e.error);
  };
  rec.onend = ()=>{ if(btn.textContent==='🔴 Dinliyor…') btn.textContent = orig; };
  try{ rec.start(); }catch(e){ btn.textContent = orig; alert('Ses tanıma başlatılamadı: '+e.message); }
}
function handleVoiceCommand(said){
  const numMatch = said.match(/(\d+)/);
  if(numMatch && /ders/.test(said)){
    const n = parseInt(numMatch[1]);
    if(n>=1 && n<=DATA.lessons.length){ navigate('lesson', n); return; }
  }
  const cmdMap = [
    [/bu hafta/, ()=>navigate('weekly')],
    [/ana ?sayfa/, ()=>navigate('dashboard')],
    [/bugün.*tekrar|tekrar et/, ()=>navigate('review')],
    [/kelime kart/, ()=>navigate('flashcards')],
    [/dikte/, ()=>navigate('dictation')],
    [/cümle kur/, ()=>navigate('builder')],
    [/yazma günlü|günlük/, ()=>navigate('journal')],
    [/yanlış/, ()=>navigate('mistakes')],
    [/favori/, ()=>navigate('favorites')],
    [/fiil test/, ()=>navigate('irregularquiz')],
    [/düzensiz/, ()=>navigate('irregular')],
    [/zaman/, ()=>navigate('tenses')],
    [/prefix|suffix|ek al/, ()=>navigate('prefixsuffix')],
    [/açıklama/, ()=>navigate('aciklamalar')],
    [/çeviri/, ()=>{ navigate('quiz'); setTimeout(()=>setQuizMode('translate'),80); }],
    [/kelime testi/, ()=>{ navigate('quiz'); setTimeout(()=>setQuizMode('word'),80); }],
    [/quiz|test/, ()=>navigate('quiz')]
  ];
  for(const [re, fn] of cmdMap){
    if(re.test(said)){ fn(); return; }
  }
  alert('Komut anlaşılamadı: "'+said+'".\nÖrnekler: "quiz aç", "5. derse git", "kelime kartları", "dikte", "bu hafta".');
}


// ---------- Smart Learning Brain v1 ----------
const FAST_ENGLISH_PROMPTS=[
  'What did you do this morning?','Any plans for tonight?','What do you usually do at weekends?',
  'Tell me something you enjoyed this week.','What would you recommend to a visitor here?',
  'What do you do when you do not understand someone?','Describe your day in three sentences.',
  'What is something you are getting used to?','What might you do tomorrow?','What made you smile today?'
];
const LISTEN_RESPOND=[
  {q:'Are you paying by cash or card?',hint:'Answer naturally with your choice.'},
  {q:'Would you like anything else?',hint:'Accept, decline, or ask for something.'},
  {q:'How long have you been living here?',hint:'Give a short natural answer.'},
  {q:'Do you want me to get you anything?',hint:'Respond naturally.'},
  {q:'What are you up to this weekend?',hint:'Say your plans or say you are not sure yet.'}
];
function brainPatternRows(){
  const b=progress.learningBrain||{patterns:{}};
  const rows=Object.entries(b.patterns||{}).map(([pattern,r])=>({pattern,score:Number(r.score||0),uses:Number(r.uses||0),last:r.last||''}));
  return rows.sort((a,b)=>a.score-b.score);
}
function brainLevel(score){if(score>=8)return 'Automatic';if(score>=5)return 'Can say';if(score>=3)return 'Can build';if(score>=1)return 'Recognise';return 'New';}
function brainRecordPattern(pattern,success){
  if(!pattern)return; const b=progress.learningBrain, r=b.patterns[pattern]||{score:0,uses:0};
  r.uses++; r.score=Math.max(0,Math.min(10,Number(r.score||0)+(success?1:-1))); r.last=todayStr(); b.patterns[pattern]=r; saveProgress(progress);
}
function learningBrainDashboardCard(){
  const rows=brainPatternRows(), strong=rows.filter(x=>x.score>=5).length, weak=rows.filter(x=>x.score<3).length;
  const avg=(progress.learningBrain.responseTimes||[]).slice(-20); const sec=avg.length?(avg.reduce((a,b)=>a+b,0)/avg.length/1000).toFixed(1):'—';
  return `<div class="card"><div class="travel-kicker">🧠 LEARNING BRAIN</div><div class="stat-grid" style="margin-top:10px"><div class="stat"><div class="num">${strong}</div><div class="label">Speaking-ready patterns</div></div><div class="stat"><div class="num">${weak}</div><div class="label">Weak patterns</div></div><div class="stat"><div class="num">${sec}${sec==='—'?'':'s'}</div><div class="label">Response time</div></div><div class="stat"><div class="num">${Number(progress.learningBrain.realLifeUses||0)}</div><div class="label">Real-life uses</div></div></div><div class="row" style="margin-top:10px"><button class="pill" onclick="navigate('learningbrain')">Open Learning Brain</button><button class="pill" onclick="navigate('errorclinic')">🩹 Error Clinic</button><button class="pill" onclick="navigate('fastenglish')">⚡ 60-sec English</button></div></div>`;
}
function viewLearningBrain(){
  const rows=brainPatternRows(); const mistakes=(progress.mistakes||[]).length, due=getDueWords().length;
  let list=rows.slice(0,12).map(x=>`<div class="card" style="margin:8px 0"><b>${esc(x.pattern)}</b><span class="hint" style="float:right">${brainLevel(x.score)} · ${x.uses} uses</span><div style="height:6px;background:var(--paper-dark);border-radius:8px;margin-top:8px"><div style="height:6px;width:${x.score*10}%;background:var(--accent);border-radius:8px"></div></div></div>`).join('');
  if(!list)list='<p class="hint">Pattern profili, Micro Practice ve tekrarları kullandıkça oluşacak.</p>';
  return `<div class="card"><div class="travel-kicker">YOUR LEARNING SYSTEM</div><h3>Learn → Recall → Say → Use → Don’t forget</h3><p class="hint">Bu ekran tek tek özellik saymak yerine hangi İngilizcenin aktif, hangisinin tekrar istediğini gösterir.</p><div class="stat-grid"><div class="stat"><div class="num">${due}</div><div class="label">Due review</div></div><div class="stat"><div class="num">${mistakes}</div><div class="label">Mistakes to fix</div></div><div class="stat"><div class="num">${progress.myEnglish.length}</div><div class="label">My English phrases</div></div></div></div><h3 class="section-title">Pattern confidence</h3>${list}`;
}
function mistakeText(m){return String((m&&(m.en||m.answer||m.wrong||m.sentence))||'').trim();}
function viewErrorClinic(){
  const arr=(progress.mistakes||[]).filter(Boolean).slice().reverse();
  if(!arr.length)return `<div class="card"><h3>🩹 Error Clinic</h3><p class="hint">Henüz kayıtlı hata yok. Quiz, lesson practice ve speaking sonrası kaydedilen hatalar burada aktif üretim görevine dönüşecek.</p></div>`;
  return `<div class="card"><h3>🩹 Error Clinic</h3><p class="hint">Hata listesi değil: hatayı gör → düzelt → yeni bağlamda üret → tekrar et.</p></div>`+arr.slice(0,20).map((m,i)=>{const en=mistakeText(m),tr=String(m.tr||m.translation||'Bu fikri doğru ve doğal İngilizceyle yeniden söyle.');return `<div class="card"><div class="travel-kicker">ERROR ${i+1}</div><div style="font-size:18px;margin:6px 0">${esc(tr)}</div>${en?`<details><summary class="hint">Reference / saved form</summary><p><b>${esc(en)}</b></p></details>`:''}<div class="row"><button class="pill primary" onclick="errorClinicProduce(${i})">🎤 / ⌨ Produce</button><button class="pill" onclick="errorClinicFixed(${i})">✓ Fixed</button></div></div>`}).join('');
}
function errorClinicProduce(i){const arr=(progress.mistakes||[]).filter(Boolean).slice().reverse(),m=arr[i];if(!m)return;const a=prompt((m.tr||'Say this idea naturally in English:')+'\n\nType without looking at the reference:');if(a===null)return;const ref=mistakeText(m);alert(ref&&orderedWordScore(ref,a)>=.55?'✅ Good recall. Now try to say it aloud once.':'🟡 Keep the meaning, but compare with the saved reference after your attempt.');}
function errorClinicFixed(i){progress.learningBrain.fixedMistakes.push({date:todayStr(),i});progress.learningBrain.fixedMistakes=progress.learningBrain.fixedMistakes.slice(-100);saveProgress(progress);alert('✓ Marked as repaired. It can return later in a new context.');}
let fastEnglishState={idx:0,start:0,times:[]};
function viewFastEnglish(){const q=FAST_ENGLISH_PROMPTS[fastEnglishState.idx%FAST_ENGLISH_PROMPTS.length];return `<div class="card"><div class="travel-kicker">⚡ 60-SECOND ENGLISH</div><h2 style="margin:8px 0">${esc(q)}</h2><p class="hint">Amaç mükemmellik değil: düşünmeden cevap vermeye başlamak.</p><div class="row"><button class="pill primary" onclick="fastEnglishStart()">▶ Start response</button><button class="pill" onclick="fastEnglishNext()">Next question</button><button class="pill" onclick="quickListening()">👂 Listen → Respond</button></div><div id="fast-feedback" class="hint" style="margin-top:12px"></div></div>`;}
function fastEnglishStart(){
  const el=document.getElementById('fast-feedback');
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!el)return;
  if(!SR){el.innerHTML='🎧 Speech recognition is unavailable in this browser. This is a technical issue, not an English mistake.';return;}
  if(fastEnglishState.recognition){try{fastEnglishState.recognition.stop()}catch(e){}}
  const r=new SR(); fastEnglishState.recognition=r; fastEnglishState.start=Date.now();
  r.lang='en-GB'; r.interimResults=true; r.continuous=true; r.maxAlternatives=1;
  let finalText='', interimText='', finished=false;
  const finish=()=>{if(finished)return;finished=true;fastEnglishState.recognition=null;const heard=(finalText||interimText||'').trim();if(!heard){el.innerHTML='🎧 I could not capture your answer. Nothing was recorded as completed. <button class="pill" onclick="fastEnglishStart()">Retry</button>';return;}const ms=Math.max(1000,Date.now()-fastEnglishState.start);fastEnglishState.times.push(ms);progress.learningBrain.responseTimes.push(ms);progress.learningBrain.responseTimes=progress.learningBrain.responseTimes.slice(-100);progress.learningBrain.speakingLog=progress.learningBrain.speakingLog||[];progress.learningBrain.speakingLog.push({date:Date.now(),source:'fast-english',text:heard,durationMs:ms});progress.learningBrain.speakingLog=progress.learningBrain.speakingLog.slice(-200);if(progress.dailyPlan&&progress.dailyPlan.date===todayStr()){progress.dailyPlan.fastEnglishCompleted=true;progress.dailyPlan.fastEnglishTranscript=heard;}saveProgress(progress);el.innerHTML=`✅ <b>Recorded:</b> ${esc(heard)}<br><span class="hint">This speaking turn is saved.</span>`;const done=document.getElementById('dp-fast-done');if(done){done.disabled=false;done.style.opacity='1';done.style.cursor='pointer';}};
  r.onresult=e=>{interimText='';for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript||'';if(e.results[i].isFinal)finalText+=(finalText?' ':'')+t;else interimText+=(interimText?' ':'')+t;}const heard=(finalText||interimText).trim();el.innerHTML=`🎤 Listening…${heard?`<br>I heard: <b>${esc(heard)}</b>`:''}<br><button class="pill" onclick="fastEnglishStop()">✓ Finish answer</button>`;};
  r.onerror=e=>{fastEnglishState.recognition=null;el.innerHTML=`🎧 I couldn't process the audio (${esc(e.error||'unknown')}). Nothing was marked complete. <button class="pill" onclick="fastEnglishStart()">Retry</button>`;};
  r.onend=()=>{if(!finished)finish();};
  try{r.start();el.innerHTML='🎤 Listening… Speak your full answer, then tap <b>Finish answer</b>.';}catch(e){el.textContent='Microphone could not start. Nothing was marked complete.';}
}
function fastEnglishStop(){const r=fastEnglishState.recognition;if(r){try{r.stop()}catch(e){}}}
function fastEnglishNext(){if(fastEnglishState.start){const ms=Date.now()-fastEnglishState.start;progress.learningBrain.responseTimes.push(ms);progress.learningBrain.responseTimes=progress.learningBrain.responseTimes.slice(-100);saveProgress(progress);fastEnglishState.start=0;}fastEnglishState.idx=(fastEnglishState.idx+1)%FAST_ENGLISH_PROMPTS.length;document.getElementById('content').innerHTML=viewFastEnglish();}
function quickListening(){const x=LISTEN_RESPOND[Math.floor(Math.random()*LISTEN_RESPOND.length)];try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(x.q);u.lang='en-GB';speechSynthesis.speak(u);}catch(e){}const el=document.getElementById('fast-feedback');if(el)el.innerHTML='👂 Listen without reading. <button class="pill" onclick="alert('+JSON.stringify('Meaning: '+x.q+'\\n\\n'+x.hint)+')">Show after answering</button>';}
function viewMyEnglish(){const a=progress.myEnglish||[];return `<div class="card"><h3>❤️ My English</h3><p class="hint">Rastgele binlerce cümle yerine gerçekten kullanmak istediğin kişisel cümle bankan.</p><div class="row"><input id="myeng-new" placeholder="A phrase I want to use…" style="flex:1;min-width:240px"><button class="pill primary" onclick="addMyEnglish()">+ Save phrase</button></div></div>`+(a.length?a.slice().reverse().map((x,i)=>`<div class="card"><b>${esc(x.text||x)}</b><div class="hint">${esc(x.date||'')}</div></div>`).join(''):'<div class="card hint">Henüz kayıtlı kişisel cümlen yok.</div>');}
function addMyEnglish(){const el=document.getElementById('myeng-new'),v=(el&&el.value||'').trim();if(!v)return;progress.myEnglish.push({text:v,date:todayStr()});progress.myEnglish=progress.myEnglish.slice(-300);saveProgress(progress);document.getElementById('content').innerHTML=viewMyEnglish();}

