function updateMistakeBadge(){
  const el = document.getElementById('mistake-badge');
  if(!el) return;
  const n = progress.mistakes.length;
  el.textContent = n>99 ? '99+' : n;
  el.style.display = n>0 ? 'inline-flex' : 'none';
}
function updateDueBadge(){
  const el = document.getElementById('due-badge');
  if(!el) return;
  const n = getDueWords().length;
  el.textContent = n>99 ? '99+' : n;
  el.style.display = n>0 ? 'inline-flex' : 'none';
}

function viewDashboardSafe(err){
  const lessons=(typeof DATA!=="undefined"&&DATA&&Array.isArray(DATA.lessons))?DATA.lessons:[];
  const done=(typeof progress!=="undefined"&&progress&&Array.isArray(progress.lessonsDone))?progress.lessonsDone.length:0;
  const cards=lessons.map(l=>`<div class="lesson-chip ${(progress&&Array.isArray(progress.lessonsDone)&&progress.lessonsDone.includes(l.no))?'done':''}" onclick="navigate('lesson', ${l.no})">${l.no}</div>`).join('');
  return `<div class="card" style="border-left:4px solid var(--accent)"><h3 class="section-title" style="margin-top:0">▶️ Today’s Study</h3><p class="hint">Ana sayfa güvenli modda açıldı. Tüm derslerin erişilebilir.</p><div class="row"><button class="pill primary" onclick="startDailyPlan()">▶️ Başla</button><button class="pill" onclick="navigate('weekly')">Bu Hafta</button></div></div><div class="stat-grid"><div class="stat"><div class="num">${done}/${lessons.length}</div><div class="label">Tamamlanan Ders</div></div></div><h3 class="section-title">Dersler</h3><div class="lesson-grid">${cards}</div>`;
}
function dashboardPart(name, fn){
  try { return fn() || ''; }
  catch(err){ console.error('Dashboard part failed:', name, err); return ''; }
}
function viewDashboard(){
  const enginePlan=aresBuildDailyPlan();
  const engineSnap=enginePlan.snapshot;
  const lessons = (DATA && Array.isArray(DATA.lessons)) ? DATA.lessons : [];
  const totalWords = lessons.reduce((a,l)=>a+((l.words||[]).length),0);
  const done = Array.isArray(progress.lessonsDone) ? progress.lessonsDone.length : 0;
  const streak = dashboardPart('streak', ()=>String(computeStreak())) || '0';
  const due = dashboardPart('due words', ()=>String(getDueWords().length)) || '0';
  let html = `<div class="card ares-today-hero">
    <div class="ares-today-top">
      <div><div class="ares-eyebrow">ARES · ADAPTIVE DAILY PLAN</div><h2 class="ares-today-title">Today’s Study</h2><p class="ares-today-sub">Tek bir akış: ısın → tekrar et → öğren → konuş → hatanı düzelt.</p></div>
      <div class="ares-today-time"><b>${enginePlan.total}</b><span>MIN</span></div>
    </div>
    <div class="ares-flow">
      <div class="ares-flow-step"><span>01</span><b>Warm-up</b><small>Quick response · 3 min</small></div>
      <div class="ares-flow-step"><span>02</span><b>Smart Review</b><small>${engineSnap.due||engineSnap.weakVocab} priority items · 7 min</small></div>
      <div class="ares-flow-step"><span>03</span><b>Learn</b><small>Core ${engineSnap.nextLesson} / Language Hub · 7 min</small></div>
      <div class="ares-flow-step"><span>04</span><b>Speak</b><small>Active transfer · 6 min</small></div>
      <div class="ares-flow-step"><span>05</span><b>Repair</b><small>${engineSnap.mistakes} saved errors · 2 min</small></div>
    </div>
    <div class="ares-today-actions"><button type="button" class="pill primary ares-main-cta" onclick="startDailyPlan()">▶ Start Today’s Study</button><button type="button" class="pill" onclick="navigate('learningbrain')">View learning insights</button></div>
  </div>`;

  html += dashboardPart('ARES learning engine', ()=>aresEngineSummaryCard());

  // Each dashboard module is isolated: one broken module can no longer erase the whole home page.
  html += dashboardPart('travel', ()=>maltaCountdownBanner());
  html += dashboardPart('backup reminder', ()=>backupReminderCard());
  html += dashboardPart('micro task', ()=>microTaskCard());
  html += dashboardPart('learning brain', ()=>learningBrainDashboardCard());

  const pron = progress.pronScore || {sum:0,count:0};
  html += `<div class="stat-grid">
    <div class="stat"><div class="num">${done}/${lessons.length}</div><div class="label">Tamamlanan Ders</div></div>
    <div class="stat"><div class="num">${streak}</div><div class="label">🔥 Günlük Seri</div></div>
    <div class="stat" style="cursor:pointer" onclick="navigate('review')"><div class="num">${due}</div><div class="label">Bugün Tekrar Edilecek</div></div>
    <div class="stat"><div class="num">${totalWords}</div><div class="label">Kelime</div></div>
    ${pron.count ? `<div class="stat"><div class="num">${Math.round(pron.sum/pron.count)}%</div><div class="label">🎤 Telaffuz Skoru</div></div>` : ''}
  </div>`;

  html += dashboardPart('weekly chart', ()=>`<div class="card"><h3 class="section-title" style="margin-top:0;">Son 14 Gün — Tamamlanan Ders</h3><div class="chart-wrap">${renderWeeklyChart()}</div></div>`);
  html += dashboardPart('sentence of day', ()=>viewSentenceOfDay());
  html += `<h3 class="section-title">Dersler</h3>`;
  html += dashboardPart('topic filter', ()=>topicFilterRow());
  html += dashboardPart('topic panel', ()=> topicFilter ? topicSentencesPanel(topicFilter) : '');

  let topics={};
  try{ topics=computeLessonTopics()||{}; }catch(err){ console.error('Dashboard topics failed:',err); }
  html += `<div class="lesson-grid">`;
  lessons.filter(l=> !topicFilter || (topics[l.no]&&topics[l.no].key===topicFilter)).forEach(l=>{
    let pct=null, doneLesson=false;
    try{pct=lessonMastery(l.no)}catch(e){}
    try{doneLesson=isDone(l.no)}catch(e){doneLesson=Array.isArray(progress.lessonsDone)&&progress.lessonsDone.includes(l.no)}
    html += `<div class="lesson-chip ${doneLesson?'done':''}" onclick="navigate('lesson', ${l.no})">${l.no}${pct!==null?`<div class="chip-pct">${pct}%</div>`:''}</div>`;
  });
  html += `</div>`;
  return html;
}
// ---------- topic tagging ----------
const TOPIC_CATEGORIES = [
  {key:'aile', label:'Aile', words:['mother','father','sister','brother','family','parent','child','son','daughter','wife','husband','grandmother','grandfather','aunt','uncle','cousin','baby','parents']},
  {key:'seyahat', label:'Seyahat', words:['travel','trip','airport','flight','hotel','passport','vacation','holiday','tourist','map','journey','abroad','luggage','ticket']},
  {key:'yemek', label:'Yemek', words:['food','eat','drink','breakfast','lunch','dinner','restaurant','cook','recipe','meal','hungry','kitchen','fruit','vegetable']},
  {key:'is', label:'İş', words:['work','job','office','boss','meeting','salary','employee','company','career','colleague','business','project','interview']},
  {key:'okul', label:'Okul / Eğitim', words:['school','student','teacher','class','study','exam','homework','university','lesson','book','education','learn']},
  {key:'saglik', label:'Sağlık', words:['health','doctor','hospital','sick','medicine','pain','disease','nurse','patient','exercise','body']},
  {key:'hava', label:'Hava Durumu', words:['weather','rain','sun','snow','wind','cloud','hot','cold','storm','temperature']},
  {key:'ev', label:'Ev / Yaşam', words:['house','home','room','kitchen','garden','furniture','apartment','door','window','bed']},
  {key:'alisveris', label:'Alışveriş', words:['shop','buy','sell','money','price','market','store','pay','cheap','expensive']},
  {key:'spor', label:'Spor', words:['sport','play','game','team','ball','run','swim','football','win','lose']},
  {key:'duygular', label:'Duygular', words:['happy','sad','angry','afraid','love','hate','feel','emotion','worry','excited']},
  {key:'doga', label:'Doğa / Hayvanlar', words:['animal','dog','cat','tree','forest','mountain','river','sea','bird','nature']},
  {key:'teknoloji', label:'Teknoloji', words:['computer','phone','internet','technology','email','software','screen','app']}
];
let lessonTopicsCache = null;
let topicFilter = null;
function computeLessonTopics(){
  if(lessonTopicsCache) return lessonTopicsCache;
  const map = {};
  DATA.lessons.forEach(l=>{
    const textWords = new Set(l.words.map(w=>w[0].toLowerCase()));
    let best=null, bestScore=0;
    TOPIC_CATEGORIES.forEach(cat=>{
      let score=0;
      cat.words.forEach(kw=>{ if(textWords.has(kw)) score++; });
      if(score>bestScore){ bestScore=score; best=cat; }
    });
    map[l.no] = (best && bestScore>=2) ? best : {key:'genel', label:'Genel'};
  });
  lessonTopicsCache = map;
  return map;
}
function topicFilterRow(){
  const topics = computeLessonTopics();
  const seen = {};
  Object.values(topics).forEach(t=>{ seen[t.key]=t.label; });
  let row = `<div class="tab-row">
    <button class="tab-btn ${!topicFilter?'active':''}" onclick="filterByTopic(null)">Tümü</button>`;
  Object.entries(seen).forEach(([k,label])=>{
    row += `<button class="tab-btn ${topicFilter===k?'active':''}" onclick="filterByTopic('${k}')">${esc(label)}</button>`;
  });
  row += `</div>`;
  return row;
}
function filterByTopic(key){
  topicFilter = key;
  document.getElementById('content').innerHTML = viewDashboard();
}
function getTopicSentences(key){
  const cat = TOPIC_CATEGORIES.find(c=>c.key===key);
  if(!cat) return [];
  const kwSet = new Set(cat.words);
  const results = [];
  DATA.lessons.forEach(l=>{
    l.sentences.forEach((s,sIdx)=>{
      const enWords = s[0].toLowerCase().replace(/[^a-z'\s]/g,' ').split(/\s+/).filter(Boolean);
      if(enWords.some(w=>kwSet.has(w))) results.push({lesson:l.no, en:s[0], tr:s[1], sIdx});
    });
  });
  return results;
}
function topicSentencesPanel(key){
  const cat = TOPIC_CATEGORIES.find(c=>c.key===key);
  const sentences = getTopicSentences(key);
  let html = `<div class="card searchresults" style="margin-bottom:20px;">
    <p class="hint">${cat?esc(cat.label):''} konusuyla ilgili ${sentences.length} cümle bulundu — derse gitmeden hepsini burada görebilirsin.</p>`;
  if(!sentences.length){
    html += `<div class="hint">Bu konuyla eşleşen cümle bulunamadı.</div>`;
  } else {
    sentences.forEach(r=>{
      html += `<div class="hit" style="cursor:pointer" onclick="navigate('lesson', ${r.lesson}, ${r.sIdx})">
        <div class="src">${r.lesson}. Ders</div>
        <div class="en">${spk(r.en)}${esc(r.en)}</div>
        <div class="tr">${esc(r.tr)}</div>
      </div>`;
    });
  }
  html += `</div>`;
  return html;
}
function viewWeeklySummary(){
  const days = [];
  for(let i=6;i>=0;i--) days.push(dateStrOffset(-i));
  const lessonsThisWeek = Object.entries(progress.lessonDoneDates)
    .filter(([no,d])=>days.includes(d)).map(([no])=>parseInt(no)).sort((a,b)=>a-b);
  const wordsThisWeek = Object.entries(progress.knownWordDates).filter(([w,d])=>days.includes(d));
  let totalCorrect=0, totalCount=0;
  days.forEach(d=>{ const s=progress.dailyStats[d]; if(s){ totalCorrect+=s.correct; totalCount+=s.total; } });
  const acc = totalCount ? Math.round(100*totalCorrect/totalCount) : 0;
  let html = `<div class="stat-grid">
    <div class="stat"><div class="num">${lessonsThisWeek.length}</div><div class="label">Tamamlanan Ders</div></div>
    <div class="stat"><div class="num">${wordsThisWeek.length}</div><div class="label">Yeni Öğrenilen Kelime</div></div>
    <div class="stat"><div class="num">${totalCount}</div><div class="label">Çözülen Soru</div></div>
    <div class="stat"><div class="num">${acc}%</div><div class="label">Bu Hafta Başarı</div></div>
  </div>`;
  html += `<div class="card"><h3 class="section-title" style="margin-top:0;">Son 7 Gün — Soru / Başarı</h3><div class="chart-wrap">${renderWeeklyAccuracyChart(days)}</div></div>`;
  if(lessonsThisWeek.length){
    html += `<h3 class="section-title">Bu Hafta Tamamlanan Dersler</h3><div class="lesson-grid">`;
    lessonsThisWeek.forEach(no=>{ html += `<div class="lesson-chip done" onclick="navigate('lesson', ${no})">${no}</div>`; });
    html += `</div>`;
  }
  if(wordsThisWeek.length){
    const wmap = {}; getAllWords().forEach(w=>wmap[w.en.toLowerCase()]=w);
    html += `<h3 class="section-title">Bu Hafta Öğrenilen Kelimeler (${wordsThisWeek.length})</h3><div class="table-scroll"><table class="wide-table"><thead><tr><th>Kelime</th><th>Anlamı</th><th>Tarih</th></tr></thead><tbody>`;
    wordsThisWeek.sort((a,b)=> b[1].localeCompare(a[1])).forEach(([w,d])=>{
      const info = wmap[w];
      html += `<tr><td>${spk(info?info.en:w)}<b>${esc(info?info.en:w)}</b></td><td>${esc(info?info.tr:'')}</td><td>${esc(d)}</td></tr>`;
    });
    html += `</tbody></table></div>`;
  }
  if(!lessonsThisWeek.length && !wordsThisWeek.length && !totalCount){
    html += `<div class="card hint">Bu hafta henüz kayıtlı bir etkinlik yok — ders tamamla, kelime kartlarında yeni kelime öğren ya da quiz çöz; burada görünecek.</div>`;
  }
  return html;
}
function renderWeeklyAccuracyChart(days){
  const counts = days.map(d=> (progress.dailyStats[d]||{total:0}).total );
  const accs = days.map(d=>{ const s=progress.dailyStats[d]; return s&&s.total? Math.round(100*s.correct/s.total) : null; });
  const labels = days.map(d=>{ const dt=new Date(d+'T00:00:00'); return dt.getDate()+'/'+(dt.getMonth()+1); });
  const max = Math.max(1, ...counts);
  const w=420, h=90, slot=w/7, bw=slot-10;
  let bars='';
  counts.forEach((c,i)=>{
    const bh = c ? Math.max(6,(c/max)*70) : 2;
    const x = i*slot+5, y=80-bh;
    const acc = accs[i];
    const color = acc===null ? 'var(--line)' : acc>=70 ? 'var(--leaf)' : acc>=40 ? 'var(--gold)' : 'var(--accent)';
    bars += `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="3" fill="${color}"></rect>`;
  });
  return `<svg width="100%" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" style="display:block;">${bars}</svg>
    <div class="chart-labels"><span>${labels[0]}</span><span>${labels[3]}</span><span>${labels[6]} (bugün)</span></div>
    <div class="hint" style="margin-top:4px;">🟢 %70+ başarı · 🟡 %40-70 · 🔴 %40 altı · gri: o gün soru çözülmedi</div>`;
}

function sentenceOfDayPick(){
  const list=getAllSentences().filter(x=>{
    const en=String(x.en||'').trim();
    if(en.length<12 || en.length>120) return false;
    if(!/[.!?]$/.test(en)) return false;
    if(/\b(tv|coke)\b/i.test(en)) return false;
    if(/\b(is|are) directed by\b/i.test(en)) return false;
    if(!/\b(I|you|he|she|it|we|they|this|that|there|my|your|his|her|our|their|who|what|where|when|why|how|can|could|would|will|do|does|did|is|are|am|have|has|had)\b/i.test(en)) return false;
    if(/^[a-z]/.test(en)) return false;
    return true;
  });
  if(!list.length) return null;
  const seed=todayStr().split('-').join(''); let h=0;
  for(let i=0;i<seed.length;i++) h=(h*31+seed.charCodeAt(i))>>>0;
  return list[h%list.length];
}
function sodKey(s){return `${s.lesson}|${s.en}`;}
function toggleSodMeaning(){const el=document.getElementById('sod-meaning');if(el)el.hidden=!el.hidden;}
function saveSodSentence(){
  const s=sentenceOfDayPick(); if(!s)return;
  progress.savedSentences=Array.isArray(progress.savedSentences)?progress.savedSentences:[];
  const k=sodKey(s), i=progress.savedSentences.findIndex(x=>x.key===k);
  if(i>=0) progress.savedSentences.splice(i,1); else progress.savedSentences.push({key:k,en:s.en,tr:s.tr,lesson:s.lesson,date:todayStr()});
  saveProgress(progress); render();
}
function saveSodOwn(){
  const s=sentenceOfDayPick(), inp=document.getElementById('sod-own'), fb=document.getElementById('sod-own-fb'); if(!s||!inp)return;
  const val=inp.value.trim(); if(!val){if(fb)fb.textContent='Önce kendi İngilizce cümleni yaz.';return;}
  progress.sentenceOfDayOwn=Array.isArray(progress.sentenceOfDayOwn)?progress.sentenceOfDayOwn:[];
  progress.sentenceOfDayOwn.push({date:todayStr(),source:s.en,text:val,lesson:s.lesson}); saveProgress(progress);
  if(fb)fb.textContent='✓ Kendi cümlen kaydedildi.';
}
function startSodRepeat(){
  const s=sentenceOfDayPick(), fb=document.getElementById('sod-repeat-fb'); if(!s||!fb)return;
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){fb.innerHTML='🎧 Bu tarayıcı konuşma tanımayı desteklemiyor. Cümleyi sesli tekrar et; bu teknik durum hata sayılmaz.';return;}
  const r=new SR(); r.lang='en-GB'; r.interimResults=false; r.maxAlternatives=1;
  fb.textContent='🎤 Listening…';
  r.onresult=e=>{const heard=e.results[0][0].transcript||''; const a=essentialKey(heard).split(' ').filter(Boolean), b=essentialKey(s.en).split(' ').filter(Boolean); const hit=b.filter(w=>a.includes(w)).length, score=b.length?Math.round(hit/b.length*100):0; fb.innerHTML=`I heard: <b>${esc(heard)}</b><br>${score>=75?'✓ Good match.':'↻ Try once more if you want.'} <span class="hint">Word match: ${score}%</span>`;};
  r.onerror=()=>{fb.textContent='🎧 I couldn’t process the audio. This is not marked as an English mistake.';};
  try{r.start();}catch(e){fb.textContent='🎧 Microphone could not start. Try again.';}
}
function viewSentenceOfDay(){
  const s=sentenceOfDayPick(); if(!s)return '';
  progress.savedSentences=Array.isArray(progress.savedSentences)?progress.savedSentences:[];
  const saved=progress.savedSentences.some(x=>x.key===sodKey(s));
  return `<div class="card" style="border-left:3px solid var(--gold);">
    <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><h3 class="section-title" style="margin:0;">📌 SENTENCE OF THE DAY</h3><button class="pill" onclick="navigate('lesson',${s.lesson})">Lesson ${s.lesson} →</button></div>
    <div class="quiz-sentence" style="font-size:21px;margin:14px 0 10px;">${esc(s.en)}</div>
    <div class="row" style="gap:8px;flex-wrap:wrap"><button class="pill" onclick="speak('${escJs(s.en)}')">🔊 Listen</button><button class="pill primary" onclick="startSodRepeat()">🎤 Repeat</button><button class="pill" onclick="toggleSodMeaning()">🇹🇷 Show meaning</button><button class="pill ${saved?'done':''}" onclick="saveSodSentence()">${saved?'★ Saved':'☆ Save'}</button></div>
    <div id="sod-repeat-fb" class="hint" style="margin-top:8px"></div>
    <div id="sod-meaning" hidden style="margin-top:12px;padding:10px 12px;border:1px solid var(--line);border-radius:10px"><b>${esc(s.tr)}</b></div>
    <div style="margin-top:14px"><div class="hint"><b>✍️ Make my own sentence</b> — aynı yapı veya fikri kullanarak yeni bir İngilizce cümle üret.</div><div class="row" style="gap:8px;margin-top:7px"><input id="sod-own" class="quiz-input" style="flex:1" placeholder="Write your own sentence…"><button class="pill" onclick="saveSodOwn()">Save mine</button></div><div id="sod-own-fb" class="hint" style="margin-top:5px"></div></div>
  </div>`;
}
function renderWeeklyChart(){
  const countByDate = {};
  Object.values(progress.lessonDoneDates).forEach(d=> countByDate[d] = (countByDate[d]||0)+1 );
  const labels = [], counts = [];
  for(let i=13;i>=0;i--){
    const s = dateStrOffset(-i);
    const d = new Date(s+'T00:00:00');
    labels.push(d.getDate()+'/'+(d.getMonth()+1));
    counts.push(countByDate[s]||0);
  }
  const max = Math.max(1, ...counts);
  const w=560, h=90, slot=w/14, bw=slot-6;
  let bars='';
  counts.forEach((c,i)=>{
    const bh = c ? Math.max(6,(c/max)*70) : 2;
    const x = i*slot+3, y=80-bh;
    bars += `<rect x="${x}" y="${y}" width="${bw}" height="${bh}" rx="3" fill="${c? 'var(--leaf)':'var(--line)'}"></rect>`;
  });
  return `<svg width="100%" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" style="display:block;">${bars}</svg>
    <div class="chart-labels"><span>${labels[0]}</span><span>${labels[6]}</span><span>${labels[13]} (bugün)</span></div>`;
}

