function irregularKey(r){ return String(r.v1||'').toLowerCase(); }
function irregularStatus(r){
  const m=progress.irregularMastery[irregularKey(r)]||{correct:0,wrong:0};
  const tries=(m.correct||0)+(m.wrong||0), rate=tries?m.correct/tries:0;
  if(tries>=4 && rate>=0.8) return {k:'known',label:'🟢 Biliyorum'};
  if(tries>0) return {k:'learning',label:'🟡 Öğreniyorum'};
  return {k:'new',label:'⚪ Yeni'};
}
function recordIrregularMastery(r,ok){
  const k=irregularKey(r), m=progress.irregularMastery[k]||{correct:0,wrong:0,streak:0,lastSeen:null};
  if(ok){m.correct++;m.streak=(m.streak||0)+1}else{m.wrong++;m.streak=0}
  m.lastSeen=Date.now(); progress.irregularMastery[k]=m;
}
function viewIrregular(){
  const stats={new:0,learning:0,known:0}; DATA.irregular.forEach(r=>stats[irregularStatus(r).k]++);
  let html = `<div class="card" style="margin-bottom:18px;border-left:4px solid var(--gold);">
    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;"><div><h3 style="margin:0 0 6px;">🔄 Irregular Verbs Pro</h3><div class="hint">Bak → hatırla → test et → kendi cümlende kullan. Yanlış yaptığın fiiller öğrenme durumunda kalır ve tekrar karşılaşır.</div></div><button class="pill primary" onclick="navigate('irregularquiz')">🧠 Çalışmaya Başla</button></div>
    <div style="display:grid;grid-template-columns:repeat(3,minmax(110px,1fr));gap:8px;margin-top:14px;"><div><b>${stats.new}</b><br><span class="hint">⚪ Yeni</span></div><div><b>${stats.learning}</b><br><span class="hint">🟡 Öğreniyorum</span></div><div><b>${stats.known}</b><br><span class="hint">🟢 Biliyorum</span></div></div>
    <div class="hint" style="margin-top:12px;"><b>V1</b> = temel fiil · <b>V2</b> = Past Simple · <b>V3</b> = have/has/had + V3 ve passive yapılarda kullanılır.</div>
  </div>`;
  html += `<div class="table-scroll"><table class="wide-table"><thead><tr><th>#</th><th>Durum</th><th>V1</th><th>V2</th><th>V3</th><th>Okunuşu</th><th>Anlamı</th><th></th></tr></thead><tbody>`;
  DATA.irregular.forEach((r,i)=>{
    const edited = progress.irregularEdits[i] ? `<span class="override-note">✎ düzeltildi</span>` : '';
    html += `<tr><td>${i+1}</td><td>${irregularStatus(r).label}</td><td>${spk(r.v1+', '+r.v2+', '+r.v3)}<b>${esc(r.v1)}</b></td><td>${esc(r.v2)}</td><td>${esc(r.v3)}</td><td>${esc(r.pron)}</td><td>${esc(r.meaning)} ${edited}</td><td style="white-space:nowrap;"><button class="spk" title="Bu satırı düzelt" onclick="editIrregular(${i})">✏️</button></td></tr>`;
  });
  html += `</tbody></table></div>`;
  return html;
}

// ---------- Irregular verbs quiz (V1 -> V2 / V3 / Anlamı) ----------
let irregularQuizMode = 'v2'; // 'v2' | 'v3' | 'meaning' | 'mixed'
let irregularQuizState = { current:null };
function setIrregularQuizMode(m){
  irregularQuizMode = m;
  navigate('irregularquiz');
}
function viewIrregularQuizPage(){
  const modes = [['v2','Hatırla V2'],['v3','Hatırla V3'],['meaning','Anlam'],['mixed','Karışık'],['produce','Cümlede Kullan']];
  const tabs = `<div class="tab-row">${modes.map(([k,l])=>
    `<button class="tab-btn ${irregularQuizMode===k?'active':''}" onclick="setIrregularQuizMode('${k}')">${esc(l)}</button>`
  ).join('')}</div>`;
  return tabs + `<div class="quiz-box card">
    <div class="score-row">
      <div class="score-item"><b id="iq-correct">${progress.irregularQuizScore.correct}</b>Doğru</div>
      <div class="score-item"><b id="iq-total">${progress.irregularQuizScore.total}</b>Toplam Soru</div>
      <div class="score-item"><b id="iq-rate">${progress.irregularQuizScore.total? Math.round(100*progress.irregularQuizScore.correct/progress.irregularQuizScore.total):0}%</b>Başarı</div>
    </div>
    <div class="hint" id="iq-source"></div>
    <div class="quiz-sentence" id="iq-word"></div>
    <input id="iq-input" class="quiz-input" placeholder="Cevabı yaz…" onkeydown="if(event.key==='Enter') checkIrregularQuiz()">
    <div class="btns" style="display:flex; gap:8px;">
      <button class="pill primary" onclick="checkIrregularQuiz()">Kontrol Et</button>
      <button class="pill" onclick="nextIrregularQuiz()">Yeni Soru ›</button>
    </div>
    <div class="quiz-feedback" id="iq-feedback"></div>
  </div>`;
}
function normIrregularAnswer(s){
  return (s||'').trim().toLowerCase().replace(/[^a-zçğıöşü' /,-]/gi,'').replace(/\s+/g,' ').trim();
}
function nextIrregularQuiz(){
  const pool = DATA.irregular;
  if(!pool.length) return;
  const r = pool[Math.floor(Math.random()*pool.length)];
  let askKind = irregularQuizMode;
  if(askKind==='mixed') askKind = ['v2','v3','meaning'][Math.floor(Math.random()*3)];
  const askLabel = askKind==='v2' ? 'V2 (Past Simple) biçimini hatırla.' : askKind==='v3' ? 'V3 (past participle) biçimini hatırla.' : askKind==='produce' ? 'Bu fiilin V1, V2 veya V3 biçimlerinden biriyle kendi İngilizce cümleni yaz.' : 'Türkçe anlamını hatırla.';
  irregularQuizState.current = { r, askKind, answered:false };
  const src = document.getElementById('iq-source');
  if(!src) return;
  src.textContent = askLabel;
  document.getElementById('iq-word').innerHTML = `${spk(r.v1)}${esc(r.v1)}`;
  document.getElementById('iq-input').value='';
  document.getElementById('iq-feedback').textContent='';
  document.getElementById('iq-feedback').className='quiz-feedback';
  document.getElementById('iq-input').focus();
}
function checkIrregularQuiz(){
  const st = irregularQuizState.current;
  if(!st || st.answered) return;
  st.answered = true;
  const val = normIrregularAnswer(document.getElementById('iq-input').value);
  const fb = document.getElementById('iq-feedback');
  let isCorrect = false, correctDisplay = '';
  if(st.askKind==='v2'){
    correctDisplay = st.r.v2;
    isCorrect = val===normIrregularAnswer(st.r.v2);
  } else if(st.askKind==='v3'){
    correctDisplay = st.r.v3;
    isCorrect = val===normIrregularAnswer(st.r.v3);
  } else if(st.askKind==='produce'){
    correctDisplay = `${st.r.v1} / ${st.r.v2} / ${st.r.v3}`;
    const raw=(document.getElementById('iq-input').value||'').toLowerCase().replace(/[’]/g,"'");
    const forms=[st.r.v1,st.r.v2,st.r.v3].map(x=>String(x).toLowerCase());
    isCorrect = raw.trim().split(/\s+/).length>=3 && forms.some(f=>new RegExp('(^|\\b)'+f.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(\\b|$)','i').test(raw));
  } else {
    correctDisplay = st.r.meaning;
    const parts = st.r.meaning.split(/[\/,]/).map(p=>normIrregularAnswer(p)).filter(Boolean);
    isCorrect = val && parts.some(p=>p===val);
  }
  recordIrregularMastery(st.r,isCorrect);
  progress.irregularQuizScore.total++;
  const label = 'V1: '+st.r.v1+' — V2: '+st.r.v2+' — V3: '+st.r.v3+' — Anlamı: '+st.r.meaning;
  if(isCorrect){
    progress.irregularQuizScore.correct++;
    fb.innerHTML = '✓ Doğru! — '+esc(label);
    fb.className='quiz-feedback ok';
    removeMistake(st.r.v1);
  } else {
    fb.innerHTML = '✕ Yanlış. Doğru cevap: "'+esc(correctDisplay)+'" — '+esc(label);
    fb.className='quiz-feedback bad';
    addMistake(st.r.v1, st.r.meaning, 'fiil');
  }
  recordDailyStat(isCorrect);
  saveProgress(progress);
  updateMistakeBadge();
  document.getElementById('iq-correct').textContent = progress.irregularQuizScore.correct;
  document.getElementById('iq-total').textContent = progress.irregularQuizScore.total;
  document.getElementById('iq-rate').textContent = Math.round(100*progress.irregularQuizScore.correct/progress.irregularQuizScore.total)+'%';
}

