function colSpeakUseExample(c){
  return (c.examples&&c.examples[0]) || c.phrase;
}
function colSpeakCleanTranscript(s){
  s=String(s||'').replace(/\s+/g,' ').trim();
  if(!s)return '';
  // Remove adjacent repeated word sequences caused by interim/final overlap.
  let words=s.split(' ');
  for(let pass=0;pass<4;pass++){
    let changed=false;
    outer: for(let size=Math.min(12,Math.floor(words.length/2));size>=1;size--){
      for(let i=0;i+size*2<=words.length;i++){
        const a=words.slice(i,i+size).join(' ').toLowerCase().replace(/[.,!?]/g,'');
        const b=words.slice(i+size,i+size*2).join(' ').toLowerCase().replace(/[.,!?]/g,'');
        if(a===b){
          words.splice(i,size); changed=true; break outer;
        }
      }
    }
    if(!changed)break;
  }
  // If one transcript is a prefix of the next, keep the longer one.
  const out=[];
  for(const w of words){
    if(out.length && out[out.length-1].toLowerCase()===w.toLowerCase()) continue;
    out.push(w);
  }
  return out.join(' ').trim();
}
function colSpeakSetButton(){
  const b=document.getElementById('col-speak-mic');
  if(b) b.textContent=colSpeakActive?'⏹️ Konuşmayı Bitir':'🎤 Konuş';
}
function colSpeakStartRecognition(){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR || !colSpeakActive) return false;
  try{ colSpeakRec=new SR(); }catch(e){ colSpeakRec=null; return false; }
  colSpeakRec.lang='en-US';
  colSpeakRec.continuous=true;
  colSpeakRec.interimResults=true;
  colSpeakRec.maxAlternatives=3;
  colSpeakRec.onresult=(e)=>{
    let interim='';
    for(let i=e.resultIndex;i<e.results.length;i++){
      const t=(e.results[i][0]&&e.results[i][0].transcript)||'';
      if(e.results[i].isFinal){
        // Only FINAL recognition is committed permanently.
        colSpeakCommittedText=colSpeakCleanTranscript(
          mergeTranscriptText(colSpeakCommittedText,t)
        );
      }else{
        // INTERIM is display-only. It is never appended to committed text.
        interim=String(t||'').trim();
      }
    }
    colSpeakInterimText=interim;
    const inp=document.getElementById(colSpeakTargetId||'col-speak-answer');
    if(inp){
      inp.value=colSpeakCleanTranscript(
        colSpeakCommittedText + (interim ? ' ' + interim : '')
      );
    }
  };
  colSpeakRec.onerror=(e)=>{
    if(colSpeakActive && (e.error==='no-speech'||e.error==='aborted')) return;
    colSpeakActive=false; colSpeakManualStop=true; colSpeakRec=null; colSpeakSetButton();
    if(e.error!=='aborted') alert(voiceErrorMessage(e.error)||'Konuşma algılanamadı. Tekrar deneyebilirsin.');
  };
  colSpeakRec.onend=()=>{
    colSpeakRec=null;
    if(colSpeakActive && !colSpeakManualStop){
      setTimeout(()=>{if(colSpeakActive&&!colSpeakRec) colSpeakStartRecognition();},250);
    }else colSpeakSetButton();
  };
  try{colSpeakRec.start();return true;}catch(e){colSpeakRec=null;return false;}
}
function colSpeakFinish(){
  window.colSpeakStopRequested=true;
  colSpeakActive=false;
  window.colSpeakActive=false;
  try{ if(colSpeakRecognition) colSpeakRecognition.stop(); }catch(e){}
  const b=document.getElementById('col-speak-mic');
  if(b){
    b.dataset.listening='false';
    b.innerHTML=(typeof colV12Icon==='function'?colV12Icon('mic'):'')+'Konuş';
  }
}
function colSpeakToggleMic(targetId){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){ alert('Bu tarayıcı konuşma tanımayı desteklemiyor.'); return; }
  if(colSpeakActive){ colSpeakFinish(); return; }

  const el=document.getElementById(targetId||'col-v12-input');
  if(!el)return;

  // v12.7: one recognition session per tap. No automatic restart.
  // Keep existing/manual text, never show interim guesses, and rebuild finals by result index.
  colSpeakActive=true;
  window.colSpeakActive=true;
  window.colSpeakTargetId=targetId||'col-v12-input';
  window.colSpeakStopRequested=false;
  const baseText=String(el.value||'').replace(/\s+/g,' ').trim();
  const finalByIndex={};

  const r=new SR();
  r.lang='en-US';
  r.continuous=true;
  r.interimResults=true;
  r.maxAlternatives=3;
  colSpeakRecognition=r;
  window.colSpeakRecognition=r;

  const updateButton=()=>{
    const b=document.getElementById('col-speak-mic');
    if(!b)return;
    const listening=!!colSpeakActive;
    b.dataset.listening=listening?'true':'false';
    b.innerHTML=(typeof colV12Icon==='function'?colV12Icon(listening?'stop':'mic'):'')+(listening?'Durdur':'Konuş');
  };

  r.onresult=(event)=>{
    for(let i=event.resultIndex;i<event.results.length;i++){
      const res=event.results[i];
      if(!res.isFinal) continue; // never commit unstable interim hypotheses
      const part=String((res[0]&&res[0].transcript)||'').replace(/\s+/g,' ').trim();
      if(part) finalByIndex[i]=part;
    }
    const heard=Object.keys(finalByIndex).map(Number).sort((a,b)=>a-b).map(i=>finalByIndex[i]).join(' ').replace(/\s+/g,' ').trim();
    if(heard) el.value=colSpeakCleanTranscript((baseText?baseText+' ':'')+heard);
  };

  r.onerror=(event)=>{
    if(event.error==='not-allowed'||event.error==='service-not-allowed'){
      window.colSpeakStopRequested=true;
    }
    if(event.error!=='no-speech'&&event.error!=='aborted'&&event.error!=='not-allowed'&&event.error!=='service-not-allowed'){
      const st=document.getElementById('col-v12-status');
      if(st) st.textContent='Ses net algılanamadı. Metni kontrol edip yeniden konuşabilirsin.';
    }
  };

  r.onend=()=>{
    // Do not auto-restart: Android/Chrome restarts can replay or invent final fragments.
    colSpeakActive=false;
    window.colSpeakActive=false;
    colSpeakRecognition=null;
    window.colSpeakRecognition=null;
    updateButton();
    const st=document.getElementById('col-v12-status');
    if(st) st.textContent='Metni kontrol et; hazırsan Gönder’e bas veya Konuş ile devam et.';
  };

  updateButton();
  try{ r.start(); }
  catch(e){ colSpeakActive=false; window.colSpeakActive=false; updateButton(); }
}
function colSpeakSay(text){
  if(!text||!('speechSynthesis' in window))return;
  try{
    speechSynthesis.cancel();
    const u=new SpeechSynthesisUtterance(text); u.lang='en-US'; u.rate=.9; speechSynthesis.speak(u);
  }catch(e){}
}
function colSpeakParseJSON(raw){
  let s=String(raw||'').trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
  const a=s.indexOf('{'), b=s.lastIndexOf('}');
  if(a>=0&&b>a)s=s.slice(a,b+1);
  try{return JSON.parse(s);}catch(e){}
  try{
    s=s.replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/,\s*([}\]])/g,'$1');
    return JSON.parse(s);
  }catch(e){}
  // Safe fallback: extract fields independently if the model made a JSON punctuation error.
  const rawText=String(raw||'');
  function field(key){
    const marker='"'+key+'"';
    let p=rawText.indexOf(marker);
    if(p<0)return '';
    p=rawText.indexOf(':',p+marker.length); if(p<0)return '';
    p++;
    while(/\s/.test(rawText[p]||''))p++;
    const quote=rawText[p];
    if(quote!=='"'&&quote!=="'")return '';
    p++;
    let out='';
    for(;p<rawText.length;p++){
      const ch=rawText[p];
      if(ch===quote && rawText[p-1]!=='\\')break;
      out+=ch;
    }
    return out.replace(/\\n/g,'\n').replace(/\\"/g,'"');
  }
  const sm=rawText.match(/["']?success["']?\s*:\s*(true|false)/i);
  const qm=rawText.match(/["']?score["']?\s*:\s*(\d{1,3})/i);
  return {
    success:sm?sm[1].toLowerCase()==='true':true,
    score:qm?Math.min(100,Number(qm[1])):80,
    feedback_tr:field('feedback_tr')||'Cümlen anlaşılıyor ve hedef kalıbı kullandın.',
    natural_version:field('natural_version')||'',
    follow_up:field('follow_up')||'Can you tell me a little more?'
  };
}
async function evaluateCollocationSpeaking(phrase){
  if(colSpeakActive) colSpeakFinish();
  const c=getStudyCollocations().find(x=>x.phrase===phrase); if(!c)return;
  const inp=document.getElementById('col-speak-answer'), box=document.getElementById('col-speak-feedback');
  const answer=(inp&&inp.value||'').trim();
  if(!answer){ box.innerHTML='<div class="quiz-feedback bad">Önce İngilizce cevap ver.</div>'; return; }
  if(!restoreApiKeyPersistent()){ box.innerHTML=apiKeyMissingMessage(); return; }
  box.innerHTML='<div class="hint">🤖 Ares değerlendiriyor…</div>';

  const system=`You are Ares, a friendly English speaking coach for an A2-B1 Turkish learner.
Evaluate communication, correct use of the target chunk, and naturalness.
Do NOT fail the learner for tiny article, punctuation, or minor preposition errors when meaning is clear.
Correct errors that change meaning, block understanding, or misuse the target structure.
Return EXACTLY five lines using these labels. Do NOT return JSON and do NOT use markdown:
SUCCESS: YES or NO
SCORE: integer 0-100
FEEDBACK_TR: short Turkish feedback
NATURAL: natural corrected English sentence
FOLLOW_UP: one short natural English follow-up question
Keep every field on a single line.`;

  const user=`Target chunk: ${c.phrase}
Meaning: ${c.meaning}
Situation: ${colSpeakScenario(c)}
Learner answer: ${answer}`;

  try{
    const raw=String(await callClaudeAPI(system,user,500)||'').trim();
    function line(label){
      const rx=new RegExp('^'+label+'\\s*:\\s*(.*)$','im');
      const m=raw.match(rx); return m?m[1].trim():'';
    }
    const success=/^(YES|TRUE|1)$/i.test(line('SUCCESS'));
    const score=Math.max(0,Math.min(100,parseInt(line('SCORE'),10)||0));
    const feedback=line('FEEDBACK_TR') || (success?'Cümlen doğal ve anlaşılır.':'Cümleyi bir kez daha deneyelim.');
    const natural=line('NATURAL') || answer;
    const follow=line('FOLLOW_UP') || 'Can you tell me a little more?';

    const st=colSpeakStat(c.phrase); st.attempts++; if(success)st.success++;
    if(st.success>=2)st.active=true;
    progress.collocationSpeakingStats[c.phrase]=st;
    progress.collocationSpeakingHistory.unshift({phrase:c.phrase,answer,success,score,date:new Date().toISOString()});
    progress.collocationSpeakingHistory=progress.collocationSpeakingHistory.slice(0,100);
    if(success) removeCollocationReview(c); else addCollocationReview(c);
    saveProgress(progress);

    box.innerHTML=`<div class="quiz-feedback ${success?'ok':'bad'}"><strong>${success?'✓ Güzel kullanım':'↻ Bir kez daha deneyelim'} · ${score}/100</strong><br>${esc(feedback)}<br><br><strong>Doğal hali:</strong> ${spk(natural)}${esc(natural)}</div>
      <div class="card" style="margin-top:10px;background:var(--paper);"><strong>🗣️ Ares:</strong> ${spk(follow)}${esc(follow)}<div class="hint" style="margin-top:6px">Takip sorusuna aşağıdaki kutuda doğal şekilde cevap verebilirsin. Hedef kalıbı tekrar kullanmak zorunda değilsin.</div></div>`;

    colSpeakConversation={phrase:c.phrase,meaning:c.meaning,scenario:colSpeakScenario(c),turns:[
      {role:'user',text:answer},{role:'assistant',text:follow}
    ]};
    colSpeakSay(follow);

    const status=document.getElementById('col-active-status');
    if(status) status.innerHTML=st.active?'🔥 <strong>Active Collocation</strong> — konuşmada en az iki kez başarıyla kullandın.':`Başarılı kullanım: <strong>${st.success}/2</strong> · 2 başarılı kullanımdan sonra Active olur.`;
  }catch(e){
    box.innerHTML=`<div class="quiz-feedback bad">Değerlendirme yapılamadı: ${esc(String(e.message||e))}</div>`;
  }
}
async function evaluateCollocationFollowup(){
  if(colSpeakActive) colSpeakFinish();
  const inp=document.getElementById('col-follow-answer'), box=document.getElementById('col-follow-feedback');
  const answer=colSpeakCleanTranscript((inp&&inp.value||'').trim()); if(!answer)return;
  if(inp) inp.value=answer;
  if(!restoreApiKeyPersistent()){box.innerHTML=apiKeyMissingMessage();return;}
  box.innerHTML='<div class="hint">🤖 Ares düşünüyor…</div>';
  if(!colSpeakConversation||!colSpeakConversation.turns) colSpeakConversation={phrase:'',meaning:'',scenario:'',turns:[]};
  colSpeakConversation.turns.push({role:'user',text:answer});
  const history=colSpeakConversation.turns.map(t=>(t.role==='user'?'Learner: ':'Ares: ')+t.text).join('\n');
  const system=`You are Ares, a friendly A2-B1 English conversation partner. Continue ONE mini role-play and never lose its context. Stay on the same topic until the learner chooses the next collocation. Interpret times, numbers, pronouns and short answers using the conversation context. Reply naturally in 1-2 short English sentences and usually ask ONE short logical follow-up question. Always finish the final sentence and question completely; never end mid-sentence. Do not force the target collocation again. Prioritize fluency and communication. Ignore tiny article, punctuation and minor preposition errors if meaning is clear. Only for an important error add a final Turkish line beginning "📝 Not:".`;
  const user=`TARGET COLLOCATION: ${colSpeakConversation.phrase}
MEANING: ${colSpeakConversation.meaning}
ROLE-PLAY SITUATION: ${colSpeakConversation.scenario}

CONVERSATION SO FAR:
${history}

Continue this exact conversation.`;
  try{
    let raw=String(await callClaudeAPI(system,user,700)||'').trim();
    // If the provider still cuts off mid-sentence, ask only for the missing completion.
    if(raw && !/[.!?]["']?$/.test(raw)){
      try{
        const completion=String(await callClaudeAPI(
          'Complete the unfinished English reply below. Return ONLY the missing continuation, maximum one short sentence. Do not repeat existing words.',
          raw,220)||'').trim();
        if(completion) raw=(raw+' '+completion).replace(/\s+/g,' ').trim();
      }catch(_){}
    }
    colSpeakConversation.turns.push({role:'assistant',text:raw});
    const visible=colSpeakConversation.turns.slice(2).map(t=>`<div style="margin:6px 0"><strong>${t.role==='user'?'👤 Sen':'🗣️ Ares'}:</strong> ${esc(t.text).replace(/\n/g,'<br>')}</div>`).join('');
    box.innerHTML=`<div class="card"><strong>💬 Mini Role-play</strong>${visible}</div>`;
    inp.value='';
    colSpeakSay(String(raw).split(/📝\s*Not:/i)[0]);
  }catch(e){
    if(colSpeakConversation.turns.length&&colSpeakConversation.turns[colSpeakConversation.turns.length-1].role==='user') colSpeakConversation.turns.pop();
    box.innerHTML=`<div class="quiz-feedback bad">${esc(String(e.message||e))}</div>`;
  }
}



function colV12Icon(name){
  const icons={
    mic:'<svg viewBox="0 0 24 24"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M9 21h6"/></svg>',
    stop:'<svg viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="2"/></svg>',
    send:'<svg viewBox="0 0 24 24"><path d="m3 11 18-8-8 18-2-8-8-2Z"/><path d="m11 13 5-5"/></svg>',
    volume:'<svg viewBox="0 0 24 24"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 9a4 4 0 0 1 0 6M17.5 6.5a8 8 0 0 1 0 11"/></svg>',
    check:'<svg viewBox="0 0 24 24"><path d="M20 6 9 17l-5-5"/></svg>'
  }; return '<span class="cv-icon">'+(icons[name]||'')+'</span>';
}
function colV12ScenarioExample(c){
  const p=normalizeAnswer(c&&c.phrase||''), s=String(colSpeakConversation&&colSpeakConversation.scenario||colSpeakScenario(c)||'').toLowerCase();
  if(p==='pick me up'){
    if(/otel|hotel/.test(s)) return 'Could you pick me up from the hotel tomorrow?';
    if(/airport|havaalan/.test(s)) return 'Could you pick me up from the airport?';
  }
  if(p==='drop me off'){
    if(/airport|havaalan/.test(s)) return 'Could you drop me off at the airport, please?';
    if(/hotel|otel/.test(s)) return 'Could you drop me off at the hotel, please?';
  }
  if(p==='get back to the hotel') return 'How can I get back to the hotel from here?';
  if(p==='get a taxi') return 'Can I get a taxi from here?';
  if(p==='take public transport') return 'Is it easy to take public transport from here?';
  if(p==='request a late check-out') return 'Could I request a late check-out, please?';
  return String(c&&c.examples&&c.examples[0]||c&&c.phrase||'');
}
function colV12Append(role,value){
  const chat=document.getElementById('col-v12-chat');if(!chat||!value)return;
  if(!(colSpeakConversation.turns||[]).length)chat.innerHTML='';
  const row=document.createElement('div');row.className='col-v12-row '+(role==='user'?'user':'ares');const b=document.createElement('div');b.className='col-v12-bubble';const s=document.createElement('strong');s.textContent=role==='user'?'Sen':'Ares';b.append(s,document.createElement('br'),document.createTextNode(value));row.appendChild(b);chat.appendChild(row);chat.scrollTop=chat.scrollHeight;
}
function colV12FriendlyError(e){const s=String(e&&e.message||e||'');return /\b503\b|UNAVAILABLE|high demand/i.test(s)?'Ares şu anda yoğun. Cevabın kaybolmadı; tekrar deneyebilirsin.':'Ares’e şu anda ulaşılamadı. Cevabın korunuyor; tekrar deneyebilirsin.'}
async function colV12ApiWithRetry(system,user,maxTokens){let last;for(let n=0;n<3;n++){try{return await callClaudeAPI(system,user,maxTokens)}catch(e){last=e;const s=String(e&&e.message||e||'');if(!(/\b503\b|UNAVAILABLE|high demand/i.test(s))||n===2)throw e;await new Promise(r=>setTimeout(r,700*(n+1)))}}throw last}
async function colV12Send(){
window.colV126LastFailedAction=function(){ colV12Send(); };
  if(colSpeakActive)colSpeakFinish();
  const inp=document.getElementById('col-v12-input'),status=document.getElementById('col-v12-status'),err=document.getElementById('col-v12-error');const answer=colSpeakCleanTranscript((inp&&inp.value||'').trim());if(!answer)return;if(!restoreApiKeyPersistent()){err.innerHTML=apiKeyMissingMessage();return}
  const c=window.colV12CurrentCollocation;if(!c){if(err)err.innerHTML='<div class="col-v12-error">Aktif collocation bulunamadı. Sayfayı yenileyip tekrar dene.</div>';return;}if(!colSpeakConversation||colSpeakConversation.phrase!==c.phrase)colSpeakConversation={phrase:c.phrase,meaning:c.meaning,scenario:colSpeakScenario(c),turns:[]};
  const last=colSpeakConversation.turns[colSpeakConversation.turns.length-1],already=last&&last.role==='user'&&last.text===answer;
  if(!already){colV12Append('user',answer);colSpeakConversation.turns.push({role:'user',text:answer})}
  if(status)status.textContent='🤖 Ares düşünüyor…';if(err)err.innerHTML='';
  try{
    const history=colSpeakConversation.turns.map(t=>(t.role==='user'?'Learner: ':'Ares: ')+t.text).join('\n');
    const system=`You are Ares, a friendly A2-B1 conversation partner continuing ONE practical role-play. Preserve all context, including times, places, pronouns and previous choices. Stay in character and on the same situation. The learner must do most of the speaking. Reply with ONE very short natural reaction plus ONE concrete follow-up question, normally 8-15 words total and never more than 20 words unless essential. Ask only ONE question at a time. Make difficulty come from the idea the learner must express, not from long wording. Never use generic filler such as "Can you tell me a little more?" when a specific practical question is possible. Do not correct mistakes during conversation; corrections come after the role-play. Never force the target collocation again after the first turn. Always finish the question completely.`;
    const user=`TARGET: ${c.phrase}\nMEANING: ${c.meaning}\nSITUATION: ${colSpeakConversation.scenario}\nCONVERSATION:\n${history}\nContinue this exact conversation.`;
    const reply=String(await colV12ApiWithRetry(system,user,750)||'').trim();colSpeakConversation.turns.push({role:'assistant',text:reply});colV12Append('ares',reply);colSpeakSay(reply);inp.value='';if(status)status.textContent='Devam et; hazır olduğunda konuşmayı bitirip topluca değerlendirebilirsin.';
  }catch(e){if(inp)inp.value=answer;if(err)err.innerHTML=`<div class="col-v12-error">${esc(colV12FriendlyError(e))} <button class="pill" onclick="colV12Send()" style="margin-left:8px">↻ Tekrar Dene</button></div>`;if(status)status.textContent='Cevabın korunuyor.'}
}
async function evaluateWholeCollocationConversation(){
window.colV126LastFailedAction=function(){ evaluateWholeCollocationConversation(); };
  const box=document.getElementById('col-conversation-review');
  if(!box)return;
  const conv=colSpeakConversation;
  if(!conv||!conv.turns||conv.turns.length<4){
    box.innerHTML='<div class="quiz-feedback bad">Önce mini role-play içinde en az birkaç tur konuş.</div>'; return;
  }
  if(!restoreApiKeyPersistent()){box.innerHTML=apiKeyMissingMessage();return;}
  box.innerHTML='<div class="hint">🤖 Ares bütün konuşmanı değerlendiriyor…</div>';
  const transcript=conv.turns.map(t=>(t.role==='user'?'Learner: ':'Ares: ')+t.text).join('\n');
  const system=`You are Ares, an accurate and encouraging English speaking coach for a Turkish A2-B1 learner.
Evaluate the learner's WHOLE mini role-play. Prioritize communication and fluency.
Do not penalize tiny article, punctuation, capitalization, or minor preposition errors if meaning is clear.
Focus on core grammar, natural spoken English, meaning-changing errors, and useful chunks/collocations.
If the learner used the TARGET collocation correctly, explicitly preserve it in any rewrite; never replace a correct target chunk merely with a synonym. Correct only the genuinely problematic part of the sentence. Infer the learner's intended meaning from the conversation before rewriting. For example, if "took public transport" is correct but the time clause is wrong, keep "took public transport" and repair only the time clause.
Natural rewrites must stay realistic A2-B1/B1 English, not advanced English.
Give at most 3 important corrections.
Scores must total 100: Fluency & Communication /30, Naturalness /25, Grammar /25, Vocabulary & Collocations /20.
Return exactly these single-line labels, no JSON and no markdown:
FLUENCY: 0-30
NATURALNESS: 0-25
GRAMMAR: 0-25
VOCAB: 0-20
STRENGTH1: Turkish
STRENGTH2: Turkish
STRENGTH3: Turkish or NONE
CORRECTION1_ORIGINAL: exact learner sentence or NONE
CORRECTION1_NATURAL: natural version or NONE
CORRECTION1_REASON_TR: short Turkish reason or NONE
CORRECTION2_ORIGINAL: exact learner sentence or NONE
CORRECTION2_NATURAL: natural version or NONE
CORRECTION2_REASON_TR: short Turkish reason or NONE
CORRECTION3_ORIGINAL: exact learner sentence or NONE
CORRECTION3_NATURAL: natural version or NONE
CORRECTION3_REASON_TR: short Turkish reason or NONE
ARES_COMMENT_TR: 1-2 short Turkish sentences.`;
  const user=`TARGET: ${conv.phrase}
MEANING: ${conv.meaning}
SITUATION: ${conv.scenario}
FULL CONVERSATION:
${transcript}
Evaluate only the learner's English.`;
  try{
    const raw=String(await colV12ApiWithRetry(system,user,1400)||'').trim();
    const get=label=>{const m=raw.match(new RegExp('^'+label+'\\s*:\\s*(.*)$','im'));return m?m[1].trim():''};
    const num=(label,max)=>Math.max(0,Math.min(max,parseInt(get(label),10)||0));
    const flu=num('FLUENCY',30),nat=num('NATURALNESS',25),gra=num('GRAMMAR',25),voc=num('VOCAB',20),total=flu+nat+gra+voc;
    const strengths=['STRENGTH1','STRENGTH2','STRENGTH3'].map(get).filter(x=>x&&!/^NONE$/i.test(x));
    const corrections=[];
    for(let i=1;i<=3;i++){
      const original=get('CORRECTION'+i+'_ORIGINAL'),natural=get('CORRECTION'+i+'_NATURAL'),reason=get('CORRECTION'+i+'_REASON_TR');
      if(original&&natural&&!/^NONE$/i.test(original)&&!/^NONE$/i.test(natural)) corrections.push({original,natural,reason});
    }
    const comment=get('ARES_COMMENT_TR')||'Konuşmayı sürdürebildin. Şimdi aynı doğallığı daha rahat kullanmaya odaklan.';
    const scores=[
      ['🗣️ Akıcılık & İletişim',flu,30],['🌿 Doğallık',nat,25],['🧩 Gramer',gra,25],['🧠 Kelime & Collocation',voc,20]
    ].map(x=>`<div class="card"><strong>${x[0]}</strong><div style="font-size:24px;margin-top:6px">${x[1]}/${x[2]}</div></div>`).join('');
    const good=strengths.length?strengths.map(x=>`<div style="margin:7px 0">✓ ${esc(x)}</div>`).join(''):'<div class="hint">İletişimi sürdürebilmen olumlu.</div>';
    const fixes=corrections.length?corrections.map(c=>`<div class="card" style="margin:9px 0"><div><strong>Sen:</strong> ${esc(c.original)}</div><div style="margin-top:6px"><strong>🌿 Daha doğal:</strong> ${spk(c.natural)}${esc(c.natural)}</div>${c.reason?`<div class="hint" style="margin-top:6px">📝 ${esc(c.reason)}</div>`:''}</div>`).join(''):'<div class="card">Önemli bir düzeltme gerekmiyor. 👍</div>';
    box.innerHTML=`<div class="card" style="border-width:2px">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><h3 style="margin:0">📊 Konuşma Sonu Değerlendirme</h3><span class="badge" style="font-size:18px"><strong>${total}/100</strong></span></div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin:12px 0">${scores}</div>
      <div class="card" style="margin-top:12px;background:var(--paper)"><strong>🟢 Güçlü Olduğun Noktalar</strong>${good}</div>
      <div style="margin-top:14px"><strong>🌿 Ben olsam nasıl söylerdim?</strong><div class="hint" style="margin:5px 0 8px">Sadece önemli yerleri, seviyene uygun daha doğal konuşma İngilizcesiyle düzelttim.</div>${fixes}</div>
      <div class="card" style="margin-top:14px;background:var(--paper)"><strong>🎯 Ares'in yorumu</strong><div style="margin-top:6px">${esc(comment)}</div></div>
      <div style="margin-top:14px"><button onclick="colSpeakReadNaturalCorrections()">🔊 Doğal Cümleleri Dinle</button></div>
    </div>`;
    window.colSpeakLastNaturalCorrections=corrections.map(c=>c.natural);
  }catch(e){box.innerHTML=`<div class="quiz-feedback bad">Toplu değerlendirme yapılamadı: ${esc(String(e.message||e))}</div>`}
}
function colSpeakReadNaturalCorrections(){
  const arr=window.colSpeakLastNaturalCorrections||[];
  if(arr.length) colSpeakSay(arr.join('. '));
}
