// ---- translation quiz (EN sentence -> pick correct TR) ----
let allSentencesCache = null;
function getAllSentences(){
  if(allSentencesCache) return allSentencesCache;
  const list = [];
  DATA.lessons.forEach(l=> l.sentences.forEach((s,sIdx)=> list.push({en:s[0], tr:s[1], lesson:l.no, sIdx})));
  allSentencesCache = list;
  return list;
}
let translateState = { current:null };
function nextTranslateQuiz(){
  const pool = applyDifficultyFilter(getAllSentences(), s=>s.en, sentenceDifficulty);
  const correct = pool[Math.floor(Math.random()*pool.length)];
  const distractors = pickCloseDistractors(getAllSentences(), correct, 'tr', 3);
  const options = shuffleArr([correct, ...distractors]);
  translateState.current = {correct, answered:false};
  const src = document.getElementById('tq-source');
  if(!src) return;
  src.textContent = `Kaynak: ${correct.lesson}. Ders`;
  document.getElementById('tq-sentence').innerHTML = `${spk(correct.en)}${esc(correct.en)}`;
  document.getElementById('tq-options').innerHTML = options.map(o=>
    `<div class="wq-opt" data-tr="${esc(o.tr)}" onclick="checkTranslateQuiz(this, '${escJs(o.tr)}')">${esc(o.tr)}</div>`
  ).join('');
  document.getElementById('tq-feedback').textContent='';
  document.getElementById('tq-feedback').className='quiz-feedback';
}
function checkTranslateQuiz(el, chosenTr){
  const st = translateState.current;
  if(st.answered) return;
  st.answered = true;
  progress.translateScore.total++;
  const fb = document.getElementById('tq-feedback');
  const correctTr = st.correct.tr;
  document.querySelectorAll('#tq-options .wq-opt').forEach(o=>{
    if(o.dataset.tr===correctTr) o.classList.add('correct');
    else if(o===el) o.classList.add('wrong');
  });
  if(chosenTr===correctTr){
    progress.translateScore.correct++;
    fb.textContent = '✓ Doğru!';
    fb.className='quiz-feedback ok';
    removeMistake(st.correct.en);
  } else {
    fb.textContent = '✕ Yanlış.';
    fb.className='quiz-feedback bad';
    addMistake(st.correct.en, st.correct.tr, 'çeviri');
  }
  recordLessonStat(st.correct.lesson, chosenTr===correctTr);
  recordDailyStat(chosenTr===correctTr);
  saveProgress(progress);
  updateMistakeBadge();
  document.getElementById('tq-correct').textContent = progress.translateScore.correct;
  document.getElementById('tq-total').textContent = progress.translateScore.total;
  document.getElementById('tq-rate').textContent = Math.round(100*progress.translateScore.correct/progress.translateScore.total)+'%';
}

