function initQuiz(){ nextQuiz(); }
// ---------- difficulty ----------
function sentenceDifficulty(en){
  const n = en.trim().split(/\s+/).length;
  if(n<=5) return 'easy';
  if(n<=10) return 'medium';
  return 'hard';
}
function wordDifficulty(en){
  const n = en.replace(/[^a-zA-Z]/g,'').length;
  if(n<=4) return 'easy';
  if(n<=7) return 'medium';
  return 'hard';
}
function applyDifficultyFilter(pool, textFn, diffFn){
  if(progress.quizDifficulty==='all') return pool;
  const f = pool.filter(x=>diffFn(textFn(x))===progress.quizDifficulty);
  return f.length ? f : pool;
}
function setDifficulty(level){
  progress.quizDifficulty = level;
  saveProgress(progress);
  render();
}
function difficultyRow(){
  const levels = [['all','Tümü'],['easy','Kolay'],['medium','Orta'],['hard','Zor']];
  return `<div class="tab-row">${levels.map(([k,label])=>
    `<button class="tab-btn ${progress.quizDifficulty===k?'active':''}" onclick="setDifficulty('${k}')">${label}</button>`).join('')}</div>`;
}
// Words that are almost never the "important" part of a sentence -> avoided as blanks
const STOPWORDS = new Set(['the','a','an','is','are','was','were','be','been','being','am',
  'i','you','he','she','it','we','they','me','him','her','us','them','my','your','his','its','our','their','mine','yours','hers','ours','theirs',
  'this','that','these','those','and','or','but','if','so','because','as','than','then','when','while','where','which','who','whom','whose','what',
  'to','of','in','on','at','by','for','with','about','against','between','into','through','during','before','after','above','below','from','up','down','out','off','over','under','again','further','once',
  'do','does','did','doing','done','have','has','had','having','will','would','shall','should','can','could','may','might','must','not','no','nor',
  'there','here','very','just','also','too','only','own','same','such']);
// Simple bigram Dice-coefficient string similarity, works fine for EN or TR text
function diceCoefficient(a, b){
  a = String(a||'').toLowerCase(); b = String(b||'').toLowerCase();
  if(a===b) return 1;
  if(a.length<2 || b.length<2) return 0;
  const bigrams = s=>{ const m={}; for(let i=0;i<s.length-1;i++){ const bg=s.substr(i,2); m[bg]=(m[bg]||0)+1; } return m; };
  const bgA = bigrams(a), bgB = bigrams(b);
  let intersection=0, totalA=0, totalB=0;
  for(const k in bgA) totalA += bgA[k];
  for(const k in bgB) totalB += bgB[k];
  for(const k in bgA){ if(bgB[k]) intersection += Math.min(bgA[k], bgB[k]); }
  return totalA+totalB ? (2*intersection)/(totalA+totalB) : 0;
}
// Picks the most "meaningful" (content) word of a sentence to blank out.
// Prefers a word that also appears in the lesson's own vocab list, since that's
// the word actually being taught; otherwise falls back to the longest non-stopword.
function pickWord(sentence, lessonWords){
  const raw = sentence.split(/\s+/);
  const candidates = raw.map(w=>({
    original: w,
    clean: w.replace(/[^a-zA-Z']/g,'')
  })).filter(w=> w.clean.length>=3 && !STOPWORDS.has(w.clean.toLowerCase()));
  if(!candidates.length) return null;
  if(lessonWords && lessonWords.length){
    const vocabSet = new Set(lessonWords.map(w=>(w[0]||'').toLowerCase().replace(/[^a-zA-Z' ]/g,'').trim()));
    const vocabHits = candidates.filter(w=> vocabSet.has(w.clean.toLowerCase()));
    if(vocabHits.length) return vocabHits[Math.floor(Math.random()*vocabHits.length)].original;
  }
  // No vocab match: weight toward longer (usually more meaningful) words,
  // but keep some randomness among the top candidates so it's not always the same word.
  const sorted = candidates.slice().sort((a,b)=> b.clean.length - a.clean.length);
  const topN = Math.max(1, Math.ceil(sorted.length/2));
  const pool = sorted.slice(0, topN);
  return pool[Math.floor(Math.random()*pool.length)].original;
}
// Picks distractor options that are close/plausible to the correct answer instead of
// totally random ones, so multiple-choice questions are meaningfully harder.
function pickCloseDistractors(pool, correctItem, key, count){
  const correctText = correctItem[key];
  const correctNorm = String(correctText).trim().toLowerCase();
  // Aynı metne sahip birden fazla aday olabilir (ör. farklı derslerde aynı çeviri).
  // Doğru cevapla veya birbirleriyle aynı metne sahip şıkların tekrar seçilmemesi için
  // önce metne göre tekilleştiriyoruz.
  const seen = new Set([correctNorm]);
  const candidates = [];
  pool.forEach(x=>{
    const norm = String(x[key]).trim().toLowerCase();
    if(seen.has(norm)) return;
    seen.add(norm);
    candidates.push(x);
  });
  const scored = candidates.map(x=>({ item:x, score: diceCoefficient(correctText, x[key]) }));
  scored.sort((a,b)=> b.score - a.score);
  const shortlist = scored.slice(0, Math.max(count*4, 12));
  return shuffleArr(shortlist).slice(0, count).map(s=>s.item);
}
function nextQuiz(){
  const basePool = applyDifficultyFilter(getAllSentences(), s=>s.en, sentenceDifficulty);
  const attempts = 30;
  for(let i=0;i<attempts;i++){
    const pair = basePool[Math.floor(Math.random()*basePool.length)];
    const pairLesson = DATA.lessons.find(x=>x.no===pair.lesson);
    const target = pickWord(pair.en, pairLesson ? pairLesson.words : null);
    if(!target) continue;
    const clean = target.replace(/[^a-zA-Z']/g,'');
    const blanked = pair.en.replace(target, '<span class="quiz-blank">…….</span>');
    quizState.current = {lesson: pair.lesson, en: pair.en, tr: pair.tr, answer: clean.toLowerCase(), blanked};
    break;
  }
  document.getElementById('quiz-source').textContent = `Kaynak: ${quizState.current.lesson}. Ders — "${quizState.current.tr}"`;
  document.getElementById('quiz-sentence').innerHTML = quizState.current.blanked;
  document.getElementById('quiz-input').value='';
  document.getElementById('quiz-feedback').textContent='';
  document.getElementById('quiz-feedback').className='quiz-feedback';
  document.getElementById('quiz-input').focus();
}
function checkQuiz(){
  const val = document.getElementById('quiz-input').value.trim().toLowerCase().replace(/[^a-zA-Z']/g,'');
  const fb = document.getElementById('quiz-feedback');
  progress.quizScore.total++;
  const isCorrect = val && val===quizState.current.answer;
  if(isCorrect){
    progress.quizScore.correct++;
    fb.innerHTML = spk(quizState.current.en)+'✓ Doğru! — '+esc(quizState.current.en);
    fb.className='quiz-feedback ok';
    removeMistake(quizState.current.en);
  } else {
    fb.innerHTML = spk(quizState.current.en)+'✕ Yanlış. Doğru cevap: "'+esc(quizState.current.answer)+'" — '+esc(quizState.current.en);
    fb.className='quiz-feedback bad';
    addMistake(quizState.current.en, quizState.current.tr, 'cümle');
  }
  recordLessonStat(quizState.current.lesson, isCorrect);
  recordDailyStat(isCorrect);
  saveProgress(progress);
  updateMistakeBadge();
  document.getElementById('q-correct').textContent = progress.quizScore.correct;
  document.getElementById('q-total').textContent = progress.quizScore.total;
  document.getElementById('q-rate').textContent = Math.round(100*progress.quizScore.correct/progress.quizScore.total)+'%';
}

