// Kullanıcının eklediği özel Malta kategorilerini ve cümlelerini sayfa her açıldığında geri ekler.
function applyCustomMaltaCategories(){
  progress.customMaltaCategories.forEach(cat=>{ MALTA_SURVIVAL.push({cat, items:[]}); });
}
applyCustomMaltaCategories();
function applyCustomMaltaSentences(){
  Object.keys(progress.customMaltaSentences).forEach(key=>{
    const group = MALTA_SURVIVAL[Number(key)];
    if(!group) return;
    progress.customMaltaSentences[key].forEach(pair=>{ group.items.push(pair.slice()); });
  });
}
applyCustomMaltaSentences();
function addMaltaSentence(gi){
  const group = MALTA_SURVIVAL[gi];
  if(!group) return;
  const newEn = prompt('Yeni cümle ekle (İngilizce) — '+group.cat+':');
  if(newEn===null) return;
  const en = newEn.trim();
  if(!en){ alert('Cümle boş bırakılamaz.'); return; }
  const newTr = prompt('Türkçe çevirisi:');
  if(newTr===null) return;
  const tr = newTr.trim();
  if(!tr){ alert('Çeviri boş bırakılamaz.'); return; }
  group.items.push([en, tr]);
  progress.customMaltaSentences[gi] = progress.customMaltaSentences[gi] || [];
  progress.customMaltaSentences[gi].push([en, tr]);
  saveProgress(progress);
  if(currentView==='maltaenglish') document.getElementById('content').innerHTML = viewMaltaEnglish();
}
function editMaltaSentence(gi, idx){
  const group = MALTA_SURVIVAL[gi];
  if(!group || !group.items[idx]) return;
  const current = group.items[idx];
  const newEn = prompt('İngilizce cümleyi düzenle:', current[0]);
  if(newEn===null) return;
  const newTr = prompt('Türkçe çevirisini düzenle:', current[1]);
  if(newTr===null) return;
  const en = newEn.trim(), tr = newTr.trim();
  if(!en || !tr){ alert('Cümle boş bırakılamaz.'); return; }
  const oldEn = current[0], oldTr = current[1];
  group.items[idx] = [en, tr];
  const arr = progress.customMaltaSentences[gi];
  if(arr){
    const ci = arr.findIndex(p=>p[0]===oldEn && p[1]===oldTr);
    if(ci>=0) arr[ci] = [en, tr];
  }
  saveProgress(progress);
  if(currentView==='maltaenglish') document.getElementById('content').innerHTML = viewMaltaEnglish();
}
function deleteMaltaSentence(gi, idx){
  const group = MALTA_SURVIVAL[gi];
  if(!group || !group.items[idx]) return;
  if(!confirm('Bu cümleyi silmek istediğine emin misin?')) return;
  const removed = group.items[idx];
  group.items.splice(idx,1);
  const arr = progress.customMaltaSentences[gi];
  if(arr){
    const ci = arr.findIndex(p=>p[0]===removed[0] && p[1]===removed[1]);
    if(ci>=0) arr.splice(ci,1);
  }
  saveProgress(progress);
  if(currentView==='maltaenglish') document.getElementById('content').innerHTML = viewMaltaEnglish();
}
function viewMaltaEnglish(){
  let html = `<div class="card hint" style="margin-bottom:20px;">Bunlar 42 çekirdek derste geçen genel/akademik cümlelerden farklı olarak, Malta'da gerçek hayatta karşılaşabileceğin senaryolara özel kalıplar. Her cümleyi dinleyip mikrofonla telaffuz pratiği yapabilirsin.</div>`;
  MALTA_SURVIVAL.forEach((group, gi)=>{
    html += `<div style="display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; margin-top:${gi===0?'0':'28px'};">
      <h3 class="section-title" style="margin:0 0 12px 0;">${esc(group.cat)}</h3>
      <button class="pill" style="margin-bottom:12px;" onclick="addMaltaSentence(${gi})">➕ Cümle Ekle</button>
    </div>`;
    html += `<table class="data"><tbody>`;
    group.items.forEach(([en,tr], ii)=>{
      html += `<tr><td class="en">${spk(en)}${esc(en)}</td><td class="tr">${esc(tr)}</td><td style="white-space:nowrap;"><button class="spk" title="Cümleyi düzenle" onclick="editMaltaSentence(${gi}, ${ii})">✏️</button><button class="spk" title="Cümleyi sil" onclick="deleteMaltaSentence(${gi}, ${ii})">🗑️</button></td></tr>`;
    });
    html += `</tbody></table>`;
  });
  html += `<div class="card" style="margin-top:20px;">
    <h3 class="section-title" style="margin-top:0;">Yeni Kategori Ekle</h3>
    <p class="hint">Yukarıdaki listede olmayan yeni bir senaryo (ör. "Market", "Plaj") için kendi kategorini oluşturabilirsin.</p>
    <button class="pill primary" onclick="addMaltaCategory()">➕ Yeni Kategori</button>
  </div>`;
  return html;
}
function addMaltaCategory(){
  const name = prompt('Yeni kategori adı (ör. Market):');
  if(name===null) return;
  const cat = name.trim();
  if(!cat){ alert('Kategori adı boş bırakılamaz.'); return; }
  MALTA_SURVIVAL.push({cat, items:[]});
  progress.customMaltaCategories.push(cat);
  saveProgress(progress);
  const gi = MALTA_SURVIVAL.length-1;
  addMaltaSentence(gi);
  if(currentView==='maltaenglish') document.getElementById('content').innerHTML = viewMaltaEnglish();
}

