function pickSpeakingQuestion(){
  const t = todayStr();
  if(progress.speaking.askedDates[t]) return progress.speaking.askedDates[t];
  const q = SPEAKING_QUESTIONS[Math.floor(Math.random()*SPEAKING_QUESTIONS.length)];
  progress.speaking.askedDates[t] = q;
  saveProgress(progress);
  return q;
}
function newSpeakingQuestion(){
  const q = SPEAKING_QUESTIONS[Math.floor(Math.random()*SPEAKING_QUESTIONS.length)];
  progress.speaking.askedDates[todayStr()] = q;
  saveProgress(progress);
  document.getElementById('content').innerHTML = viewSpeaking();
}
let speakingTimerId = null;
let speakingSecondsLeft = 30;
// Mikrofon/ses tanıma tarayıcı desteğini kontrol eden ortak yardımcı.
// iOS Safari ve bazı Android tarayıcıları SpeechRecognition API'sini desteklemez;
// bu durumda kullanıcıyı özelliği denemeden önce bilgilendirmek daha iyi bir deneyim sağlar.
function speechRecCompatNote(){
  const supported = !!(window.SpeechRecognition || window.webkitSpeechRecognition);
  if(supported) return '';
  return `<div class="card hint" style="border-left:4px solid var(--accent); margin-bottom:16px;">
    ⚠️ Bu tarayıcı/cihaz mikrofonla ses tanımayı desteklemiyor (özellikle iPad/iPhone'da Safari'de bu sık görülür). Zamanlayıcı ve soru listesi yine çalışır. Konuşmayı otomatik yazıya çevirme özelliği tarayıcıya ve internet bağlantısına bağlıdır. En iyi destek için güncel Chrome kullan.
  </div>`;
}

function ensureSpeakingAIState(){
  if(!progress.speaking.aiReviews) progress.speaking.aiReviews=[];
  if(!progress.speaking.lastTranscript) progress.speaking.lastTranscript='';
}
async function evaluateSpeakingChallenge(){
  ensureSpeakingAIState();
  if(isAppOffline()){ const fb=document.getElementById('speaking-ai-review'); if(fb) fb.innerHTML='<div class="quiz-feedback">✈️ Ares değerlendirmesi internet gerektirir. Offline ses kaydını dinleyip tekrar deneyebilirsin.</div>'; return; }
  const transcript=(speakingTranscript||progress.speaking.lastTranscript||'').trim();
  const q=pickSpeakingQuestion();
  const fb=document.getElementById('speaking-ai-review');
  if(!transcript){
    if(fb) fb.innerHTML='<div class="quiz-feedback">⚠️ Önce soruya sesli cevap ver. Konuşman metne dönüştükten sonra değerlendirebilirim.</div>';
    return;
  }
  if(fb) fb.innerHTML='<div class="hint">🐾 Ares konuşmanı değerlendiriyor…</div>';
  const prompt=`You are evaluating Erhan's ONE-MINUTE English speaking challenge. His level is A2-B1 and his goal is spontaneous fluency.
Question/topic: ${q}
Speech transcript: ${transcript}

IMPORTANT:
- Judge ONLY what is visible in the transcript. Do not invent pronunciation errors because this is speech-to-text.
- Be fair and conservative with scores; 8/10 means clearly strong performance for his target level, not encouragement.
- Ignore punctuation/capitalization caused by speech recognition.
- Identify at most 3 important grammar/word-choice/naturalness issues.
- If a phrase is valid informal English, do not "correct" it unnecessarily.
Reply in Turkish using EXACTLY this structure:
🎯 Akıcılık: X/10 — one short reason
🧩 Gramer: X/10 — one short reason
📚 Kelime: X/10 — one short reason
🗣️ Doğallık: X/10 — one short reason
📝 En önemli düzeltmeler:
1. ...
2. ...
3. ...
🔁 Tekrar hedefi: one concise instruction for a second attempt.`;
  try{
    const review=await callClaudeAPIChat(buildAICoachSystemPrompt(),[{role:'user',text:prompt}],700);
    progress.speaking.aiReviews.unshift({date:todayStr(),question:q,transcript,review});
    progress.speaking.lastTranscript=transcript;
    saveProgress(progress);
    if(fb) fb.innerHTML=`<div class="card" style="margin-top:12px;"><h3 class="section-title" style="margin-top:0;">🐾 Ares’in Değerlendirmesi</h3><div style="white-space:pre-wrap;line-height:1.65;">${esc(review)}</div><div style="margin-top:12px;"><button class="pill primary" onclick="retrySpeakingChallenge()">🔁 Aynı Konuyu Tekrar Dene</button></div></div>`;
  }catch(err){
    if(fb) fb.innerHTML=`<div class="quiz-feedback bad">⚠️ ${esc(friendlyApiErrorMessage(err))}</div>`;
  }
}
function retrySpeakingChallenge(){
  speakingTranscript='';
  progress.speaking.lastTranscript='';
  const t=document.getElementById('speaking-transcript'); if(t) t.textContent='';
  const r=document.getElementById('speaking-ai-review'); if(r) r.innerHTML='';
  speakingTimeLeft=60;
  const timer=document.getElementById('speaking-timer'); if(timer) timer.textContent='60';
  speakingChallengeActive=false; speakingManualStop=true; updateSpeakingButtons();
  window.scrollTo({top:0,behavior:'smooth'});
}

function viewSpeaking(){
  const q = pickSpeakingQuestion();
  const history = progress.speaking.history.slice().reverse().slice(0,10);
  let html = speechRecCompatNote();
  html += `<div class="card">
    <h3 class="section-title" style="margin-top:0;">Bugünün Sorusu</h3>
    <p style="font-family:var(--serif); font-size:20px; color:var(--accent); margin:6px 0 6px 0;">${spk(q)}${esc(q)}</p>
    <p class="hint">60 saniye boyunca İngilizce olarak sesli cevap ver. Mikrofonla kaydedersen söylediklerin yazıya dökülüp burada gösterilir, böylece kendini değerlendirebilirsin.</p>
    <div id="speaking-timer" style="font-family:var(--serif); font-size:44px; color:var(--ink); margin:14px 0;">00:30</div>
    <div class="btns" style="display:flex; gap:8px; flex-wrap:wrap;">
      <button class="pill primary" id="speaking-start-btn" onclick="startSpeakingTimer()">▶️ Başlat</button>
      <button class="pill" id="speaking-rec-btn" style="display:none;" onclick="toggleSpeakingRecording()">🎤 Kaydı Başlat</button>
      <button class="pill" onclick="newSpeakingQuestion()">🔀 Farklı Soru</button>
      <button class="pill good" onclick="logSpeakingAttempt(true)">✅ Konuştum</button>
    </div>
    <div class="quiz-feedback" id="speaking-transcript" style="margin-top:10px; font-style:italic;"></div>
      <div class="hint" style="margin-top:10px;">🎯 Amaç: ▶️ Başlat'a bir kez bas. Sayaç ve mikrofon birlikte başlar; aynı düğme ⏹️ Durdur olur. 60 saniye boyunca konuş. Chrome cümle aralarında dinlemeyi kapatırsa sistem otomatik yeniden başlatır. Bitince AI değerlendirmesini al.</div>
      <div style="margin-top:10px;"><button class="pill good" onclick="evaluateSpeakingChallenge()">🐾 Ares’e Değerlendir</button></div>
      <div id="speaking-ai-review"></div><div id="speaking-offline-audio"></div>
  </div>`;
  html += `<h3 class="section-title">Geçmiş Denemelerin (${progress.speaking.history.length})</h3>`;
  if(!history.length){
    html += `<div class="card hint">Henüz kayıtlı bir konuşma denemen yok.</div>`;
  } else {
    history.forEach(h=>{
      html += `<div class="card"><div class="hint">${esc(h.date)}${h.wordCount?' — '+h.wordCount+' kelime':''}</div><p style="margin:6px 0; font-size:14px;">${esc(h.question)}</p>${h.transcript?`<p style="margin:6px 0; font-size:14px; font-style:italic; color:var(--ink-soft);">"${esc(h.transcript)}"</p>`:''}</div>`;
    });
  }
  return html;
}
let speakingRec = null;
let speakingTranscript = '';
let speakingChallengeActive = false;
let speakingChallengeTimer = null;
let speakingTimeLeft = 60;
let speakingManualStop = false;

function updateSpeakingButtons(){
  const start=document.getElementById('speaking-start-btn');
  const rec=document.getElementById('speaking-rec-btn');
  if(start){
    start.textContent = speakingChallengeActive ? '⏹️ Durdur' : '▶️ Başlat';
    start.classList.toggle('bad', speakingChallengeActive);
  }
  // Keep old mic button hidden: Start now controls timer + microphone together.
  if(rec) rec.style.display='none';
}
function startSpeakingRecognitionContinuous(){
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR) return false;
  speakingManualStop=false;
  try{ speakingRec=new SR(); }catch(e){ return false; }
  speakingRec.lang='en-US';
  speakingRec.continuous=true;
  speakingRec.interimResults=true;
  speakingRec.maxAlternatives=3;
  speakingRec.onresult=(e)=>{
    let interim='';
    for(let i=e.resultIndex;i<e.results.length;i++){
      const txt=(e.results[i][0]&&e.results[i][0].transcript)||'';
      if(e.results[i].isFinal) speakingTranscript += txt+' ';
      else interim += txt+' ';
    }
    const el=document.getElementById('speaking-transcript');
    if(el) el.textContent=(speakingTranscript+interim).trim();
  };
  speakingRec.onerror=(e)=>{
    const msg=voiceErrorMessage(e.error);
    // 'no-speech' and 'aborted' are recoverable during a 60-sec challenge.
    if(speakingChallengeActive && (e.error==='no-speech' || e.error==='aborted')){
      return;
    }
    const el=document.getElementById('speaking-transcript');
    if(el) el.textContent=((speakingTranscript||'').trim()+' '+(msg?'⚠️ '+msg:'')).trim();
  };
  speakingRec.onend=()=>{
    speakingRec=null;
    // Android/Chrome may end recognition after a phrase even with continuous=true.
    // Restart it automatically while the 60-sec challenge is still active.
    if(speakingChallengeActive && !speakingManualStop){
      setTimeout(()=>{
        if(speakingChallengeActive && !speakingRec) startSpeakingRecognitionContinuous();
      },180);
    }else{
      ensureSpeakingAIState();
      if((speakingTranscript||'').trim()){
        progress.speaking.lastTranscript=speakingTranscript.trim();
        saveProgress(progress);
      }
    }
  };
  try{ speakingRec.start(); return true; }catch(e){ speakingRec=null; return false; }
}

let offlineSpeakingRecorder=null, offlineSpeakingStream=null, offlineSpeakingChunks=[], offlineSpeakingAudioUrl=null;
async function startOfflineSpeakingRecording(){
  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia || typeof MediaRecorder==='undefined'){
    alert('Bu cihaz yerel ses kaydını desteklemiyor.'); return false;
  }
  try{
    offlineSpeakingStream=await navigator.mediaDevices.getUserMedia({audio:true});
    offlineSpeakingChunks=[];
    offlineSpeakingRecorder=new MediaRecorder(offlineSpeakingStream);
    offlineSpeakingRecorder.ondataavailable=e=>{ if(e.data&&e.data.size) offlineSpeakingChunks.push(e.data); };
    offlineSpeakingRecorder.onstop=()=>{
      if(offlineSpeakingStream){ offlineSpeakingStream.getTracks().forEach(t=>t.stop()); offlineSpeakingStream=null; }
      if(offlineSpeakingAudioUrl) try{ URL.revokeObjectURL(offlineSpeakingAudioUrl); }catch(e){}
      if(offlineSpeakingChunks.length){
        const blob=new Blob(offlineSpeakingChunks,{type:offlineSpeakingRecorder.mimeType||'audio/webm'});
        offlineSpeakingAudioUrl=URL.createObjectURL(blob);
        const slot=document.getElementById('speaking-offline-audio');
        if(slot) slot.innerHTML=`<div class="card" style="margin-top:10px;"><b>✈️ Offline ses kaydın</b><br><audio controls src="${offlineSpeakingAudioUrl}" style="width:100%;margin-top:8px;"></audio><div class="hint">Kaydını dinleyip aynı konuyu tekrar deneyebilirsin. Ares değerlendirmesi internet geldiğinde kullanılabilir.</div></div>`;
      }
      offlineSpeakingRecorder=null;
    };
    offlineSpeakingRecorder.start(); return true;
  }catch(e){ alert('Mikrofon açılamadı. Tarayıcı mikrofon iznini kontrol et.'); return false; }
}
function stopOfflineSpeakingRecording(){
  if(offlineSpeakingRecorder && offlineSpeakingRecorder.state!=='inactive') try{offlineSpeakingRecorder.stop();}catch(e){}
}

function stopSpeakingChallenge(){
  speakingChallengeActive=false;
  speakingManualStop=true;
  stopOfflineSpeakingRecording();
  if(speakingChallengeTimer){ clearInterval(speakingChallengeTimer); speakingChallengeTimer=null; }
  if(speakingRec){ try{ speakingRec.stop(); }catch(e){} }
  const timer=document.getElementById('speaking-timer');
  if(timer) timer.textContent=String(speakingTimeLeft);
  ensureSpeakingAIState();
  if((speakingTranscript||'').trim()){
    progress.speaking.lastTranscript=speakingTranscript.trim();
    saveProgress(progress);
  }
  updateSpeakingButtons();
}
function startSpeakingTimer(){
  if(!voiceEnvironmentGuard()) return;
  if(speakingChallengeActive){ stopSpeakingChallenge(); return; }

  speakingTranscript='';
  speakingTimeLeft=60;
  speakingChallengeActive=true;
  speakingManualStop=false;
  const t=document.getElementById('speaking-transcript');
  if(t) t.textContent='🎤 Dinliyorum… 60 saniye boyunca konuş.';
  const review=document.getElementById('speaking-ai-review');
  if(review) review.innerHTML='';
  const timer=document.getElementById('speaking-timer');
  if(timer) timer.textContent='60';
  updateSpeakingButtons();

  if(isAppOffline()){
    startOfflineSpeakingRecording().then(ok=>{ if(!ok && speakingChallengeActive) stopSpeakingChallenge(); });
  }else if(!startSpeakingRecognitionContinuous()){
    speakingChallengeActive=false;
    updateSpeakingButtons();
    alert('Konuşma tanıma başlatılamadı. Mikrofon iznini ve Chrome desteğini kontrol et.');
    return;
  }
  speakingChallengeTimer=setInterval(()=>{
    speakingTimeLeft--;
    if(timer) timer.textContent=String(Math.max(0,speakingTimeLeft));
    if(speakingTimeLeft<=0){
      stopSpeakingChallenge();
      if(t && !(speakingTranscript||'').trim()) t.textContent='⚠️ Süre doldu ancak konuşma metne çevrilemedi. Tekrar deneyebilirsin.';
    }
  },1000);
}

function toggleSpeakingRecording(){ startSpeakingTimer(); }
function saveSpeakingTranscript(text){
  const t = todayStr();
  const q = progress.speaking.askedDates[t] || '';
  const wordCount = text.split(/\s+/).filter(Boolean).length;
  let entry = progress.speaking.history.find(h=>h.date===t && h.question===q);
  if(entry){ entry.transcript = text; entry.wordCount = wordCount; }
  else { progress.speaking.history.push({date:t, question:q, transcript:text, wordCount}); }
  saveProgress(progress);
  if(currentView==='speaking') document.getElementById('content').innerHTML = viewSpeaking();
}

function updateSpeakingTimerDisplay(){
  const el = document.getElementById('speaking-timer');
  if(!el) return;
  const m = String(Math.floor(Math.max(speakingSecondsLeft,0)/60)).padStart(2,'0');
  const s = String(Math.max(speakingSecondsLeft,0)%60).padStart(2,'0');
  el.textContent = m+':'+s;
}
function logSpeakingAttempt(manual){
  const t = todayStr();
  const q = progress.speaking.askedDates[t] || '';
  const already = progress.speaking.history.some(h=>h.date===t && h.question===q);
  if(!already){
    progress.speaking.history.push({date:t, question:q});
    saveProgress(progress);
  }
  if(manual){
    clearInterval(speakingTimerId);
    const btn = document.getElementById('speaking-start-btn');
    if(btn) btn.disabled = false;
  }
  if(currentView==='speaking') document.getElementById('content').innerHTML = viewSpeaking();
}

// ---------- Seviye Tespit Sınavı (Placement Test) ----------
// Sorular 6 zorluk katmanına ayrılmıştır (katman başına 6 soru = 36 soruluk havuz).
// Her test başlangıcında her katmandan rastgele 3 soru seçilir, şıklar karıştırılır;
// böylece 18 soruluk test her seferinde farklı ama yine artan zorlukta olur.
const PLACEMENT_TIERS = [
  // Katman 0 — Başlangıç (be fiili)
  [
    { q:"I ___ a student.", opts:["am","is","are","be"], a:0 },
    { q:"She ___ happy today.", opts:["am","is","are","isn't"], a:1 },
    { q:"___ you tired?", opts:["Is","Am","Are","Do"], a:2 },
    { q:"We ___ from Turkey.", opts:["is","am","are","be"], a:2 },
    { q:"It ___ cold outside.", opts:["am","is","are","were"], a:1 },
    { q:"They ___ my classmates.", opts:["is","am","are","be"], a:2 },
    { q:"My name ___ Erhan.", opts:["am","is","are","do"], a:1 },
    { q:"___ this your passport?", opts:["Am","Are","Is","Do"], a:2 }
  ],
  // Katman 1 — Temel (there is/are, present simple ifade)
  [
    { q:"There ___ a book on the table.", opts:["is","are","am","be"], a:0 },
    { q:"There ___ many students in the class.", opts:["is","am","are","was"], a:2 },
    { q:"I ___ to school every day.", opts:["go","goes","going","went"], a:0 },
    { q:"He ___ coffee every morning.", opts:["drink","drinks","drinking","drank"], a:1 },
    { q:"There ___ some milk in the fridge.", opts:["is","are","am","be"], a:0 },
    { q:"My sister ___ in a hospital.", opts:["work","works","is work","worked"], a:1 },
    { q:"Ares usually ___ near the window.", opts:["sleep","sleeps","is sleep","slept"], a:1 },
    { q:"There aren't ___ chairs in the room.", opts:["some","any","a","much"], a:1 }
  ],
  // Katman 2 — Alt-Orta (present simple soru, can, past simple)
  [
    { q:"___ you speak English?", opts:["Are","Do","Does","Is"], a:1 },
    { q:"I ___ swim very well.", opts:["can","am able","can to","am can"], a:0 },
    { q:"Yesterday I ___ to the market.", opts:["go","goes","went","gone"], a:2 },
    { q:"___ she like tea?", opts:["Do","Does","Is","Are"], a:1 },
    { q:"He ___ drive when he was 16.", opts:["can","could","was can","could to"], a:1 },
    { q:"We ___ a great movie last night.", opts:["watch","watches","watched","watching"], a:2 },
    { q:"What time ___ you get home yesterday?", opts:["do","did","were","have"], a:1 },
    { q:"She can't ___ us today.", opts:["joins","joined","joining","join"], a:3 }
  ],
  // Katman 3 — Orta (past simple, present continuous)
  [
    { q:"They ___ football last weekend.", opts:["play","played","plays","playing"], a:1 },
    { q:"I ___ TV right now.", opts:["watch","watched","am watching","watches"], a:2 },
    { q:"She ___ a letter when I called her.", opts:["writes","wrote","was writing","is writing"], a:2 },
    { q:"Look! It ___ outside.", opts:["rains","rained","is raining","rain"], a:2 },
    { q:"Did you ___ the homework yesterday?", opts:["finish","finished","finishing","finishes"], a:0 },
    { q:"We ___ dinner at 8 o'clock last night.", opts:["have","having","had","has"], a:2 },
    { q:"While I ___ to work, it started to rain.", opts:["walked","was walking","am walking","have walked"], a:1 },
    { q:"Why ___ you laughing now?", opts:["do","did","are","have"], a:2 }
  ],
  // Katman 4 — Orta-Üst (going to future, karşılaştırma)
  [
    { q:"We ___ go to the beach tomorrow.", opts:["are going to","goes to","went to","are go to"], a:0 },
    { q:"My car is ___ than yours.", opts:["fast","faster","fastest","more fast"], a:1 },
    { q:"This is the ___ movie I have ever seen.", opts:["good","better","best","most good"], a:2 },
    { q:"I think it ___ rain later.", opts:["is going to","go to","goes to","going"], a:0 },
    { q:"This exam is ___ than the last one.", opts:["difficult","more difficult","most difficult","difficulter"], a:1 },
    { q:"He is the ___ student in our class.", opts:["smart","smarter","smartest","most smart"], a:2 },
    { q:"We have decided. We ___ stay in Malta for three weeks.", opts:["are going to","will have","are","going"], a:0 },
    { q:"Travelling by train is often ___ than flying.", opts:["relaxing","more relaxing","most relaxing","relaxer"], a:1 }
  ],
  // Katman 5 — İleri (present perfect, edilgen, koşul cümlesi)
  [
    { q:"I ___ never ___ sushi before.", opts:["have / eaten","has / eat","did / eat","am / eating"], a:0 },
    { q:"The letter ___ by my mother yesterday.", opts:["wrote","was written","is written","has write"], a:1 },
    { q:"If I ___ more time, I would learn French too.", opts:["have","had","will have","having"], a:1 },
    { q:"She ___ already ___ her homework.", opts:["has / finished","have / finish","did / finished","is / finishing"], a:0 },
    { q:"This house ___ in 1920.", opts:["built","was built","is built","has built"], a:1 },
    { q:"If it rains tomorrow, we ___ the picnic.", opts:["cancel","will cancel","would cancel","canceled"], a:1 },
    { q:"By the time we arrived, the film ___.", opts:["started","has started","had started","was starting"], a:2 },
    { q:"I wish I ___ more confident when speaking English.", opts:["am","were","will be","have been"], a:1 }
  ]
];
// Her test başlangıcında her katmandan rastgele 3 soru seçip şıklarını karıştırarak
// 18 soruluk yeni bir set oluşturur (katman sırası korunur, böylece zorluk artan kalır).
function buildPlacementQuestions(){
  let set = [], signature = '';
  const lastSignature = progress.lastPlacementQuestionSet || '';
  for(let attempt=0;attempt<12;attempt++){
    set = [];
    PLACEMENT_TIERS.forEach((tier,tierIndex)=>{
      shuffleArr(tier).slice(0,3).forEach(orig=>{
        const correctText = orig.opts[orig.a];
        const shuffledOpts = shuffleArr(orig.opts);
        set.push({ q: orig.q, opts: shuffledOpts, a: shuffledOpts.indexOf(correctText), tier:tierIndex });
      });
    });
    signature = set.map(q=>q.q).join('|');
    if(signature!==lastSignature) break;
  }
  progress.lastPlacementQuestionSet = signature;
  saveProgress(progress);
  return set;
}
// Puana göre önerilen ders ve seviye etiketi.
const PLACEMENT_LEVELS = [
  { min:0,  max:3,  label:'Başlangıç',      lesson:1 },
  { min:4,  max:6,  label:'Temel',          lesson:6 },
  { min:7,  max:9,  label:'Alt-Orta',       lesson:11 },
  { min:10, max:12, label:'Orta',           lesson:18 },
  { min:13, max:15, label:'Orta-Üst',       lesson:27 },
  { min:16, max:18, label:'İleri',          lesson:36 }
];
let placementState = null;
function startPlacementTest(){
  placementState = { index:0, correct:0, answers:[], questions: buildPlacementQuestions() };
  document.getElementById('content').innerHTML = viewPlacementTest();
}
function viewPlacementTest(){
  if(!placementState){
    let html = `<div class="card">
      <h3 class="section-title" style="margin-top:0;">Seviyeni Öğren</h3>
      <p class="hint">18 kısa soruluk bu test, temel yapılardan ileri düzey yapılara doğru ilerler. Bitince sana hangi dersten çalışmaya başlaman gerektiğini söyleyeceğiz.</p>
      <button class="pill primary" onclick="startPlacementTest()">▶️ Teste Başla</button>
    </div>`;
    if(progress.placementTest){
      const pt = progress.placementTest;
      html += `<div class="card hint">Son sonucun (${esc(pt.date)}): <b>${pt.score}/${pt.total}</b> — Seviye: <b>${esc(pt.levelLabel)}</b> — Önerilen başlangıç: <b>${pt.recommendedLesson}. Ders</b>
        <div style="margin-top:8px;"><button class="pill" onclick="navigate('lesson', ${pt.recommendedLesson})">O derse git</button></div>
      </div>`;
    }
    return html;
  }
  if(placementState.index >= placementState.questions.length) return renderPlacementResult();
  const q = placementState.questions[placementState.index];
  let html = `<div class="card">
    <div class="hint">Soru ${placementState.index+1} / ${placementState.questions.length}</div>
    <p style="font-family:var(--serif); font-size:19px; margin:10px 0 14px 0;">${esc(q.q)}</p>
    <div class="btns" style="display:flex; flex-direction:column; gap:8px;">`;
  q.opts.forEach((opt,i)=>{
    html += `<button class="pill" style="text-align:left;" onclick="answerPlacement(${i})">${esc(opt)}</button>`;
  });
  html += `</div></div>`;
  return html;
}
function answerPlacement(i){
  const q = placementState.questions[placementState.index];
  if(i===q.a) placementState.correct++;
  placementState.answers.push({question:q.q, chosen:q.opts[i], correct:q.opts[q.a], isCorrect:i===q.a, tier:q.tier});
  placementState.index++;
  document.getElementById('content').innerHTML = viewPlacementTest();
}
function renderPlacementResult(){
  const total = placementState.questions.length;
  const score = placementState.correct;
  let level = PLACEMENT_LEVELS.find(l=> score>=l.min && score<=l.max) || PLACEMENT_LEVELS[0];
  const review = placementState.answers.filter(a=>!a.isCorrect);
  progress.placementTest = { date:todayStr(), score, total, levelLabel:level.label, recommendedLesson:level.lesson, review };
  saveProgress(progress);
  placementState = null;
  const reviewHtml = review.length ? `<div class="card" style="margin-top:16px;">
    <h3 class="section-title" style="margin-top:0;">Yanlışların (${review.length})</h3>
    <p class="hint">Soruyu, verdiğin cevabı ve doğru cevabı birlikte görebilirsin.</p>
    ${review.map((r,i)=>`<div style="padding:12px 0; border-top:1px solid var(--line);">
      <b>${i+1}. ${esc(r.question)}</b>
      <div style="margin-top:6px; color:var(--accent);">Senin cevabın: <b>${esc(r.chosen)}</b></div>
      <div style="margin-top:3px; color:var(--leaf);">Doğru cevap: <b>${esc(r.correct)}</b></div>
    </div>`).join('')}
  </div>` : `<div class="card" style="margin-top:16px; color:var(--leaf);"><b>Tebrikler, yanlışın yok.</b></div>`;
  return `<div class="card" style="border-left:4px solid var(--leaf);">
    <h3 class="section-title" style="margin-top:0;">Sonucun: ${score} / ${total}</h3>
    <p style="font-size:16px;">Seviyen: <b>${esc(level.label)}</b></p>
    <p class="hint">Bu sonuca göre en verimli çalışma, konuları tekrar tekrar baştan geçmek yerine, seviyene uygun yerden devam etmen. <b>${level.lesson}. dersten</b> itibaren çalışmanı öneririz.</p>
    <div class="btns" style="display:flex; gap:8px; flex-wrap:wrap;">
      <button class="pill primary" onclick="navigate('lesson', ${level.lesson})">${level.lesson}. Derse Git</button>
      <button class="pill" onclick="startPlacementTest()">🔁 Testi Tekrar Çöz</button>
    </div>
  </div>${reviewHtml}`;
}

// ---------- Serbest Konuşma (Rastgele Konu) — akıcılık için hazırlıksız konuşma pratiği ----------
const FREETALK_TOPICS = [
  "Talk about your weekend.",
  "Describe your hometown.",
  "Talk about your favourite food and why you like it.",
  "Describe a typical day in your life.",
  "Talk about your family.",
  "Describe your best friend.",
  "Talk about a place you want to visit.",
  "Describe your job or your studies.",
  "Talk about your hobbies.",
  "Describe the weather today.",
  "Talk about a memorable holiday.",
  "Describe your favourite movie or show.",
  "Talk about what you did yesterday.",
  "Describe your house or apartment.",
  "Talk about your plans for next year.",
  "Describe a person you admire.",
  "Talk about your favourite season and why.",
  "Describe how you learn English.",
  "Talk about a problem you solved recently.",
  "Describe your morning routine."
];
let freetalkDuration = 60;
let freetalkTimerId = null;
let freetalkSecondsLeft = 60;
let freetalkHesitations = 0;
let freetalkRec = null;
let freetalkTranscript = '';
function pickFreetalkTopic(){
  const t = todayStr();
  if(progress.freetalk.askedDates[t]) return progress.freetalk.askedDates[t];
  const topic = FREETALK_TOPICS[Math.floor(Math.random()*FREETALK_TOPICS.length)];
  progress.freetalk.askedDates[t] = topic;
  saveProgress(progress);
  return topic;
}
function newFreetalkTopic(){
  const topic = FREETALK_TOPICS[Math.floor(Math.random()*FREETALK_TOPICS.length)];
  progress.freetalk.askedDates[todayStr()] = topic;
  saveProgress(progress);
  freetalkHesitations = 0;
  document.getElementById('content').innerHTML = viewFreeTalk();
}
function setFreetalkDuration(sec){
  freetalkDuration = sec;
  freetalkSecondsLeft = sec;
  document.getElementById('content').innerHTML = viewFreeTalk();
}
function viewFreeTalk(){
  const topic = pickFreetalkTopic();
  freetalkSecondsLeft = freetalkDuration;
  const history = progress.freetalk.history.slice().reverse().slice(0,10);
  let html = speechRecCompatNote();
  html += `<div class="card">
    <h3 class="section-title" style="margin-top:0;">Bugünün Konusu</h3>
    <p style="font-family:var(--serif); font-size:20px; color:var(--accent); margin:6px 0 6px 0;">${esc(topic)}</p>
    <p class="hint">Hazırlanmadan, aklına geleni İngilizce anlat. Amaç doğru konuşmak değil, <b>durmadan</b> konuşmak. Süre bitene kadar devam etmeye çalış.</p>
    <div class="btns" style="display:flex; gap:8px; margin-bottom:8px;">
      <button class="pill ${freetalkDuration===30?'primary':''}" onclick="setFreetalkDuration(30)">30 sn</button>
      <button class="pill ${freetalkDuration===60?'primary':''}" onclick="setFreetalkDuration(60)">60 sn</button>
      <button class="pill ${freetalkDuration===90?'primary':''}" onclick="setFreetalkDuration(90)">90 sn</button>
    </div>
    <div id="freetalk-timer" style="font-family:var(--serif); font-size:44px; color:var(--ink); margin:14px 0;">00:${String(freetalkDuration).padStart(2,'0')}</div>
    <div class="btns" style="display:flex; gap:8px; flex-wrap:wrap;">
      <button class="pill primary" id="freetalk-start-btn" onclick="startFreetalkTimer()">▶️ Başlat</button>
      <button class="pill" id="freetalk-rec-btn" onclick="toggleFreetalkRecording()">🎤 Kaydı Başlat</button>
      <button class="pill" onclick="newFreetalkTopic()">🔀 Farklı Konu</button>
      <button class="pill" id="freetalk-hesitate-btn" onclick="logFreetalkHesitation()">😬 Duraksadım (<span id="freetalk-hes-count">${freetalkHesitations}</span>)</button>
    </div>
    <div class="quiz-feedback" id="freetalk-transcript" style="margin-top:10px; font-style:italic;"></div>
  </div>`;
  html += `<h3 class="section-title">Geçmiş Denemelerin (${progress.freetalk.history.length})</h3>`;
  if(!history.length){
    html += `<div class="card hint">Henüz kayıtlı bir serbest konuşma denemen yok.</div>`;
  } else {
    history.forEach(h=>{
      const wpm = h.duration ? Math.round((h.wordCount||0)/(h.duration/60)) : null;
      html += `<div class="card"><div class="hint">${esc(h.date)}${wpm?` — ~${wpm} kelime/dk`:''}${h.hesitations?` — 😬 ${h.hesitations} duraksama`:''}</div><p style="margin:6px 0; font-size:14px;">${esc(h.topic)}</p>${h.transcript?`<p style="margin:6px 0; font-size:14px; font-style:italic; color:var(--ink-soft);">"${esc(h.transcript)}"</p>`:''}</div>`;
    });
  }
  return html;
}
function logFreetalkHesitation(){
  freetalkHesitations++;
  const el = document.getElementById('freetalk-hes-count');
  if(el) el.textContent = freetalkHesitations;
}
function toggleFreetalkRecording(){
  const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  const btn = document.getElementById('freetalk-rec-btn');
  if(!SR){ alert('Tarayıcın ses tanımayı desteklemiyor.'); return; }
  if(window.isSecureContext===false){ alert('Mikrofon için dosyanın bir web sunucusundan (https) açılması gerekiyor.'); return; }
  if(freetalkRec){ freetalkRec.stop(); return; }
  freetalkTranscript = '';
  const tEl = document.getElementById('freetalk-transcript');
  if(tEl) tEl.textContent = '';
  try{ freetalkRec = new SR(); }catch(e){ return; }
  freetalkRec.lang = 'en-US';
  freetalkRec.continuous = true;
  freetalkRec.interimResults = true;
  freetalkRec.onresult = (e)=>{
    let interim = '';
    for(let i=e.resultIndex;i<e.results.length;i++){
      const txt = e.results[i][0].transcript;
      if(e.results[i].isFinal) freetalkTranscript += txt + ' ';
      else interim += txt;
    }
    const el = document.getElementById('freetalk-transcript');
    if(el) el.textContent = freetalkTranscript + interim;
  };
  freetalkRec.onerror = (e)=>{
    const el=document.getElementById('freetalk-transcript');
    const msg=voiceErrorMessage(e.error);
    if(el && e.error!=='aborted') el.textContent='⚠️ '+(msg||'Konuşma algılanamadı. Tekrar dene.');
    freetalkRec = null;
    if(btn) btn.textContent='🎤 Kaydı Başlat';
  };
  freetalkRec.onend = ()=>{
    freetalkRec = null;
    if(btn) btn.textContent = '🎤 Kaydı Başlat';
    if(freetalkTranscript.trim()) saveFreetalkTranscript(freetalkTranscript.trim());
  };
  try{ freetalkRec.start(); if(btn) btn.textContent = '⏹️ Kaydı Durdur'; }catch(e){}
}
function saveFreetalkTranscript(text){
  const t = todayStr();
  const topic = progress.freetalk.askedDates[t] || '';
  const wordCount = text.split(/\s+/).filter(Boolean).length;
  let entry = progress.freetalk.history.find(h=>h.date===t && h.topic===topic && !h.finalized);
  if(entry){ entry.transcript = text; entry.wordCount = wordCount; }
  else { progress.freetalk.history.push({date:t, topic, transcript:text, wordCount, duration:freetalkDuration, hesitations:freetalkHesitations}); }
  saveProgress(progress);
  if(currentView==='freetalk') document.getElementById('content').innerHTML = viewFreeTalk();
}
function startFreetalkTimer(){
  clearInterval(freetalkTimerId);
  freetalkSecondsLeft = freetalkDuration;
  freetalkHesitations = 0;
  const btn = document.getElementById('freetalk-start-btn');
  if(btn) btn.disabled = true;
  updateFreetalkTimerDisplay();
  freetalkTimerId = setInterval(()=>{
    freetalkSecondsLeft--;
    updateFreetalkTimerDisplay();
    if(freetalkSecondsLeft<=0){
      clearInterval(freetalkTimerId);
      if(btn) btn.disabled = false;
      if(freetalkRec) freetalkRec.stop();
      logFreetalkAttempt();
      try{ if('speechSynthesis' in window){ const u=new SpeechSynthesisUtterance('Time is up'); u.lang='en-US'; window.speechSynthesis.speak(u); } }catch(e){}
    }
  }, 1000);
}
function updateFreetalkTimerDisplay(){
  const el = document.getElementById('freetalk-timer');
  if(!el) return;
  const m = String(Math.floor(Math.max(freetalkSecondsLeft,0)/60)).padStart(2,'0');
  const s = String(Math.max(freetalkSecondsLeft,0)%60).padStart(2,'0');
  el.textContent = m+':'+s;
}
function logFreetalkAttempt(){
  const t = todayStr();
  const topic = progress.freetalk.askedDates[t] || '';
  const already = progress.freetalk.history.some(h=>h.date===t && h.topic===topic);
  if(!already){
    progress.freetalk.history.push({date:t, topic, duration:freetalkDuration, hesitations:freetalkHesitations});
    saveProgress(progress);
  }
  if(currentView==='freetalk') document.getElementById('content').innerHTML = viewFreeTalk();
}

// ---------- Kalıp Cümle Bankası (Chunking) — akıcılığı artıran hazır kalıplar ----------
const CHUNK_BANK = [
  { cat:'Fikir Belirtme', items:["I think that...","In my opinion...","As far as I know...","I guess...","It seems to me that..."] },
  { cat:'Katılma / Katılmama', items:["I totally agree.","I see your point, but...","That's true, but...","I'm not sure I agree.","I disagree because..."] },
  { cat:'Zaman Kazanma', items:["Well, let me think...","That's a good question.","How can I put this...","Actually...","You know..."] },
  { cat:'Yumuşatma', items:["I'm afraid that...","To be honest...","If you don't mind...","Sort of / kind of...","I was just wondering if..."] },
  { cat:'Geçiş İfadeleri', items:["On the other hand...","By the way...","Speaking of which...","Anyway...","In addition to that..."] },
  { cat:'Plan / Niyet', items:["I'm going to...","I'm planning to...","I'd like to...","I'm thinking about...","I might..."] },
  { cat:'Karşılaştırma', items:["Compared to...","Unlike...","The main difference is...","Both of them...","Neither of them..."] },
  { cat:'Sonuç Çıkarma', items:["In the end...","That's why...","As a result...","To sum up...","All in all..."] }

];

// Hazır Kalıp Cümle Bankası içeriği — her kalıp için Türkçe açıklama, kullanım tüyosu ve 3 doğal örnek.
// Kullanıcı daha önce bu kalıba kendi notunu eklediyse mevcut veri korunur; hazır içerik yalnızca ilk kez açılan kalıba eklenir.
const DEFAULT_CHUNK_NOTES = {
  '0_0': {explanations:['Anlam / kullanım: “I think that...” kişisel fikrini doğrudan ama doğal biçimde söylemek için kullanılır. Türkçede “Bence...” / “...diye düşünüyorum.” karşılığına yakındır.','Tüyo: Günlük konuşmada that çoğu zaman atılabilir: “I think it’s a good idea.” Bu, daha doğal ve akıcı duyulur.'], examples:['I think that learning a little every day is more effective.','I think we should leave a bit earlier tomorrow.','I think this exercise will help me speak more naturally.']},
  '0_1': {explanations:['Anlam / kullanım: “In my opinion...” kendi görüşünü biraz daha düzenli ve vurgulu biçimde ifade eder. “Bence / benim görüşüme göre...” demektir.','Tüyo: Tartışma, karşılaştırma veya fikir sorularında güçlü bir başlangıçtır. Ardından tam bir cümle getir.'], examples:['In my opinion, this restaurant is better than the one near the hotel.','In my opinion, speaking practice is the most important part of learning English.','In my opinion, we need a simpler plan.']},
  '0_2': {explanations:['Anlam / kullanım: “As far as I know...” bildiğin kadarıyla doğru olan bir bilgiyi aktarırken kullanılır. “Bildiğim kadarıyla...” demektir.','Tüyo: Kesin olmadığın bilgileri söylerken kullan; böylece cümleyi gereğinden fazla kesin göstermemiş olursun.'], examples:['As far as I know, the museum is closed on Mondays.','As far as I know, he is still working in Malta.','As far as I know, we do not need to book in advance.']},
  '0_3': {explanations:['Anlam / kullanım: “I guess...” tahmin, hafif fikir veya çok güçlü olmayan bir kanaat belirtir. “Sanırım / galiba...” anlamındadır.','Tüyo: “I think”ten biraz daha belirsizdir. Emin olmadığın gündelik durumlarda çok doğaldır.'], examples:['I guess we can take the bus from here.','I guess she is busy right now.','I guess I need more practice with this topic.']},
  '0_4': {explanations:['Anlam / kullanım: “It seems to me that...” gözlem veya izlenime dayanan bir fikri yumuşak biçimde ifade eder. “Bana öyle geliyor ki...” demektir.','Tüyo: Bir kişiyi ya da durumu doğrudan yargılamak istemediğinde kullan; daha nazik duyulur.'], examples:['It seems to me that the weather is getting better.','It seems to me that this lesson is easier than the previous one.','It seems to me that we are making good progress.']},

  '1_0': {explanations:['Anlam / kullanım: “I totally agree.” bir görüşe tamamen katıldığını güçlü biçimde söyler. “Kesinlikle katılıyorum.” demektir.','Tüyo: Ardından nedenini eklemek konuşmayı uzatır: “I totally agree because...”'], examples:['I totally agree. Practice is more useful than memorizing rules alone.','I totally agree with you about the new plan.','I totally agree; we should keep things simple.']},
  '1_1': {explanations:['Anlam / kullanım: “I see your point, but...” karşı tarafın fikrini anladığını gösterip ardından farklı bir görüş sunar. “Ne demek istediğini anlıyorum ama...” demektir.','Tüyo: Katılmadığın durumlarda doğrudan “You are wrong” demek yerine bunu kullan; daha nazik ve doğal olur.'], examples:['I see your point, but I think we need more time.','I see your point, but this option is too expensive for me.','I see your point, but I would prefer to try another way.']},
  '1_2': {explanations:['Anlam / kullanım: “That’s true, but...” önce bir noktayı kabul eder, sonra karşıt bir nokta ekler. “Bu doğru, ancak...” demektir.','Tüyo: “However” biraz daha düzenli ve kontrollü bir geçiştir. Günlük konuşmada “but” da kullanılabilir.'], examples:['That’s true, but we still have a few problems to solve.','That’s true, but the second option is more practical.','That’s true, but I do not think it will work for everyone.']},
  '1_3': {explanations:['Anlam / kullanım: “I’m not sure I agree.” bir görüşe tam katılmadığını veya şüphe duyduğunu nazikçe belirtir. “Bundan pek emin değilim.” demektir.','Tüyo: Sert bir itiraz yerine kullan. Ardından “because...” ile sebebini açıklarsan konuşma daha doğal olur.'], examples:['I’m not sure I agree because the price is quite high.','I’m not sure I agree. Maybe we should check again.','I’m not sure I agree with that idea, but I’m willing to try it.']},
  '1_4': {explanations:['Anlam / kullanım: “I disagree because...” açıkça katılmadığını söyler ve gerekçe vermeye hazırlar. “Katılmıyorum çünkü...” demektir.','Tüyo: “Because” sonrasında somut bir sebep ver; böylece itirazın daha yapıcı olur.'], examples:['I disagree because this plan takes too much time.','I disagree because everyone learns at a different pace.','I disagree because there is not enough evidence.']},

  '2_0': {explanations:['Anlam / kullanım: “Well, let me think...” cevap vermeden önce düşünmek için doğal biçimde zaman kazandırır. “Şey, bir düşüneyim...” gibi kullanılır.','Tüyo: Konuşmada sessiz kalmak yerine bu kalıbı söyle; hem akıcılığı korur hem de düşünmek için birkaç saniye kazandırır.'], examples:['Well, let me think... I would probably choose the second option.','Well, let me think... I went there about two years ago.','Well, let me think... The best part was probably the food.']},
  '2_1': {explanations:['Anlam / kullanım: “That’s a good question.” zor veya düşünmeyi gerektiren bir soruya cevap vermeden önce kullanılan doğal bir ifadedir. “Bu iyi bir soru.” demektir.','Tüyo: Tek başına söyleyip kısa bir duraklama yapabilirsin; ardından cevabını kurmaya başla.'], examples:['That’s a good question. I think I would choose Malta.','That’s a good question. I have never really thought about it.','That’s a good question. Let me give you an example.']},
  '2_2': {explanations:['Anlam / kullanım: “How can I put this...” söylemek istediğin şeyi nasıl ifade edeceğini düşünürken kullanılır. “Bunu nasıl ifade etsem...” anlamındadır.','Tüyo: Özellikle hassas, karmaşık veya açıklaması zor fikirlerde zaman kazandırır.'], examples:['How can I put this... The job was interesting but very stressful.','How can I put this... I liked the place, but I would not live there.','How can I put this... I need a little more time to decide.']},
  '2_3': {explanations:['Anlam / kullanım: “Actually...” bir düzeltme, beklenmedik bilgi veya karşıt gerçek eklerken sık kullanılır. “Aslında...” demektir.','Tüyo: Türkçedeki “aslında” gibi her yerde kullanma; özellikle önceki bilgiye küçük bir düzeltme veya farklılık getirirken daha doğal olur.'], examples:['Actually, I have been there before.','Actually, I do not drink coffee very often.','Actually, the meeting starts at three, not two.']},
  '2_4': {explanations:['Anlam / kullanım: “You know...” konuşmayı daha doğal hale getiren, ortak bilgiye veya açıklamaya geçiş yapan bir dolgu ifadesidir. “Hani / biliyorsun...” gibi düşünülebilir.','Tüyo: Fazla tekrar etme. Gerektiğinde kısa bir geçiş olarak kullanmak doğaldır.'], examples:['You know, I used to be very nervous when speaking English.','It was one of those days, you know, when nothing goes as planned.','You know, this place reminds me of my hometown.']},

  '3_0': {explanations:['Anlam / kullanım: “I’m afraid that...” kötü, olumsuz veya karşı tarafın hoşuna gitmeyecek bir bilgiyi nazikçe vermek için kullanılır. “Maalesef...” anlamına yaklaşır.','Tüyo: Buradaki “afraid” her zaman gerçekten korkmak demek değildir; nazik bir olumsuzluk yumuşatıcısıdır.'], examples:['I’m afraid that I cannot come tomorrow.','I’m afraid that the shop is already closed.','I’m afraid that we do not have enough time.']},
  '3_1': {explanations:['Anlam / kullanım: “To be honest...” samimi ve doğrudan bir fikir paylaşmadan önce kullanılır. “Dürüst olmak gerekirse...” demektir.','Tüyo: Özellikle beklenenden farklı veya kişisel bir görüş söylerken doğaldır. Çok sık kullanırsan gereksiz vurgu yaratabilir.'], examples:['To be honest, I was a little nervous at first.','To be honest, I prefer staying at home tonight.','To be honest, I did not understand the last part.']},
  '3_2': {explanations:['Anlam / kullanım: “If you don’t mind...” izin isterken veya hassas bir rica/soruya girerken cümleyi yumuşatır. “Sakıncası yoksa...” demektir.','Tüyo: Ardından isteğe göre farklı yapı gelir: “If you don’t mind, I’d like to...” veya “If you don’t mind me asking...”'], examples:['If you don’t mind, I’d like to sit by the window.','If you don’t mind, could we talk about this later?','If you don’t mind me asking, how long have you lived here?']},
  '3_3': {explanations:['Anlam / kullanım: “Sort of / kind of...” bir şeyi tam kesin söylemeden yaklaşık veya yumuşak biçimde anlatır. “Bir nevi / biraz...” anlamındadır.','Tüyo: Günlük konuşmada çok yaygındır. Resmî yazıda daha net ifadeler tercih etmek daha iyidir.'], examples:['I’m kind of tired today.','It was sort of difficult at the beginning.','The two places are kind of similar.']},
  '3_4': {explanations:['Anlam / kullanım: “I was just wondering if...” özellikle rica veya soru sorarken çok nazik bir giriş kalıbıdır. “Acaba ... mümkün mü diye merak ediyordum.” gibi kullanılır.','Tüyo: Otel, restoran, iş veya hizmet ortamında rica ederken çok kullanışlıdır.'], examples:['I was just wondering if you had a table for two.','I was just wondering if I could change my reservation.','I was just wondering if you could help me with this form.']},

  '4_0': {explanations:['Anlam / kullanım: “On the other hand...” bir konunun diğer yönünü veya zıt tarafını sunar. “Öte yandan...” demektir.','Tüyo: Önce bir avantaj veya görüş söyle, sonra bununla karşılaştırılan diğer noktaya geçmek için kullan.'], examples:['The hotel is expensive. On the other hand, the location is excellent.','Working from home is convenient. On the other hand, it can feel lonely.','The course is difficult. On the other hand, I am learning a lot.']},
  '4_1': {explanations:['Anlam / kullanım: “By the way...” ana konudan kısa süreli başka bir konuya geçerken kullanılır. “Bu arada...” demektir.','Tüyo: Konuyu tamamen değiştirmek yerine sohbet içinde ek bir bilgi veya soru eklemek için çok doğaldır.'], examples:['By the way, did you book the restaurant?','By the way, I saw your message this morning.','By the way, what time does the bus leave?']},
  '4_2': {explanations:['Anlam / kullanım: “Speaking of which...” az önce bahsedilen bir şeyden bağlantılı yeni bir konuya geçer. “Hazır ondan söz etmişken...” demektir.','Tüyo: Önceki cümledeki konu ile yeni cümle arasında açık bir bağlantı olmalı.'], examples:['We were talking about Malta. Speaking of which, have you booked your flight?','I need to buy some coffee. Speaking of which, do you want anything from the shop?','She mentioned the new project. Speaking of which, when does it start?']},
  '4_3': {explanations:['Anlam / kullanım: “Anyway...” konuyu toparlamak, eski konuya dönmek veya gereksiz ayrıntıyı kapatmak için kullanılır. “Neyse / her neyse...” demektir.','Tüyo: Sohbet dağıldığında ana noktaya dönmek için güçlü bir akıcılık kalıbıdır.'], examples:['Anyway, let’s get back to the main question.','Anyway, I had a great time there.','Anyway, we can decide tomorrow.']},
  '4_4': {explanations:['Anlam / kullanım: “In addition to that...” önceki bilgiye başka bir nokta ekler. “Buna ek olarak...” demektir.','Tüyo: Konuşmada biraz daha düzenli ve açıklayıcı bir geçiştir. Daha gündelik alternatif olarak “also” da kullanılabilir.'], examples:['The hotel is close to the beach. In addition to that, it has a good restaurant.','I practice speaking every day. In addition to that, I listen to English podcasts.','The job offers good pay. In addition to that, the hours are flexible.']},

  '5_0': {explanations:['Anlam / kullanım: “I’m going to...” önceden verilmiş karar veya güçlü planı anlatır. “...yapacağım / ...yapmayı planlıyorum.” demektir.','Tüyo: “Going to + fiilin yalın hâli” kullanılır: “I’m going to visit...”.'], examples:['I’m going to practice English for twenty minutes tonight.','I’m going to visit Valletta this weekend.','I’m going to call the hotel tomorrow morning.']},
  '5_1': {explanations:['Anlam / kullanım: “I’m planning to...” belirli bir plan veya niyeti anlatır. “...yapmayı planlıyorum.” demektir.','Tüyo: Ardından fiilin yalın hâli gelir: “planning to travel / study / meet”.'], examples:['I’m planning to stay in Malta for a few weeks.','I’m planning to study a little every morning.','I’m planning to meet some friends after work.']},
  '5_2': {explanations:['Anlam / kullanım: “I’d like to...” istek veya arzuyu nazikçe ifade eder. “...isterdim / ...istiyorum.” demektir.','Tüyo: Sipariş, rezervasyon ve rica ortamlarında “I want” yerine daha nazik bir seçenektir.'], examples:['I’d like to book a room for three nights.','I’d like to try the local food.','I’d like to improve my speaking skills.']},
  '5_3': {explanations:['Anlam / kullanım: “I’m thinking about...” henüz kesinleşmemiş bir düşünce veya olası planı anlatır. “...yapmayı düşünüyorum.” demektir.','Tüyo: “about”tan sonra çoğunlukla isim veya -ing gelir: “thinking about moving / taking a course”.'], examples:['I’m thinking about taking an English course.','I’m thinking about changing my travel dates.','I’m thinking about buying a new laptop.']},
  '5_4': {explanations:['Anlam / kullanım: “I might...” düşük veya orta ihtimali belirtir. “Belki ... yapabilirim / ... olabilir.” anlamındadır.','Tüyo: “Might”tan sonra fiilin yalın hâli gelir; “to” kullanılmaz: “I might go.”'], examples:['I might go to the beach this afternoon.','I might stay home if it rains.','I might ask him for some advice.']},

  '6_0': {explanations:['Anlam / kullanım: “Compared to...” iki şey arasında karşılaştırma yaparken bir referans noktası oluşturur. “...ile karşılaştırıldığında...” demektir.','Tüyo: Ardından isim veya isim öbeği getir; sonra ana farkı söyle.'], examples:['Compared to last year, my English is much better.','Compared to the city center, this area is much quieter.','Compared to the first lesson, this one feels easier.']},
  '6_1': {explanations:['Anlam / kullanım: “Unlike...” iki kişi veya şey arasındaki farklılığı doğrudan gösterir. “...dan farklı olarak...” demektir.','Tüyo: “Unlike + isim” yapısını kullan: “Unlike my brother, I...”'], examples:['Unlike my brother, I enjoy getting up early.','Unlike the first hotel, this one is close to the beach.','Unlike yesterday, the weather is sunny today.']},
  '6_2': {explanations:['Anlam / kullanım: “The main difference is...” iki seçenek arasındaki en önemli farkı açıklamak için kullanılır. “Temel fark...” demektir.','Tüyo: Ardından “that...” veya isim öbeği getirebilirsin: “The main difference is that...”'], examples:['The main difference is that this room has a balcony.','The main difference is the price.','The main difference is that one course focuses more on speaking.']},
  '6_3': {explanations:['Anlam / kullanım: “Both of them...” iki kişi veya şey için ortak olan özelliği belirtir. “İkisi de...” demektir.','Tüyo: İki seçenek hakkında konuştuğundan emin ol. Ardından çoğul fiil kullanılır: “Both of them are...”'], examples:['Both of them are good options.','Both of them have a lot of experience.','Both of them are within walking distance of the hotel.']},
  '6_4': {explanations:['Anlam / kullanım: “Neither of them...” iki seçenekten hiçbirinin belirli bir özelliğe sahip olmadığını söyler. “İkisi de değil / hiçbirisi...” demektir.','Tüyo: Konuşmada “Neither of them is...” yapısı güvenli ve yaygındır.'], examples:['Neither of them is very expensive.','Neither of them speaks Turkish.','Neither of them is available this weekend.']},

  '7_0': {explanations:['Anlam / kullanım: “In the end...” olayların veya düşüncenin sonunda ne olduğunu özetler. “Sonuçta / en sonunda...” demektir.','Tüyo: Hikâye anlatırken karar veya sonuç bölümüne geçmek için kullan.'], examples:['In the end, we decided to stay another night.','In the end, everything worked out well.','In the end, I chose the cheaper option.']},
  '7_1': {explanations:['Anlam / kullanım: “That’s why...” önce söylenen sebebin sonucunu verir. “İşte bu yüzden...” demektir.','Tüyo: Önce nedeni söyle, sonra “That’s why + sonuç” yapısını kullan.'], examples:['I want to speak more confidently. That’s why I practice every day.','The buses were on strike. That’s why we took a taxi.','I did not sleep well. That’s why I am tired today.']},
  '7_2': {explanations:['Anlam / kullanım: “As a result...” bir nedenin doğurduğu sonucu daha düzenli biçimde ifade eder. “Sonuç olarak...” demektir.','Tüyo: “That’s why”a göre biraz daha resmîdir; anlatım ve yazıda çok kullanışlıdır.'], examples:['I practiced consistently. As a result, I became more confident.','The flight was delayed. As a result, we arrived after midnight.','The shop lowered its prices. As a result, more people came in.']},
  '7_3': {explanations:['Anlam / kullanım: “To sum up...” birkaç noktayı kısa bir sonuç hâlinde toparlar. “Özetlemek gerekirse...” demektir.','Tüyo: Uzun bir açıklamanın sonunda ana fikri tek veya iki cümlede tekrar etmek için kullan.'], examples:['To sum up, the trip was expensive but worth it.','To sum up, we need more practice and a clear routine.','To sum up, both options have advantages and disadvantages.']},
  '7_4': {explanations:['Anlam / kullanım: “All in all...” genel değerlendirme veya son kanaati verir. “Her şeyi hesaba katarsak / genel olarak...” demektir.','Tüyo: Bir deneyimin artılarını ve eksilerini anlattıktan sonra nihai görüşünü söylemek için çok doğaldır.'], examples:['All in all, I had a very good experience.','All in all, the hotel was a good choice.','All in all, I think we made the right decision.']}
};

let chunkCatIndex = 0;
let chunkItemIndex = 0;
function viewChunks(){
  const cat = CHUNK_BANK[chunkCatIndex];
  const chunk = cat.items[chunkItemIndex];
  const chunkId = chunkCatIndex+'_'+chunkItemIndex;
  const practiced = progress.chunkProgress[chunkId] || 0;
  const note = getChunkNote();
  const explanations = Array.isArray(note.explanations) ? note.explanations : [];
  const examples = Array.isArray(note.examples) ? note.examples : [];
  const totalChunks = CHUNK_BANK.reduce((a,c)=>a+c.items.length,0);
  const practicedTotal = Object.keys(progress.chunkProgress).length;
  let html = `<div class="card hint">Bu kalıpları hazır cümle başlangıcı olarak ezberle — konuşurken cümleyi sıfırdan kurmak yerine bu kalıplardan biriyle başlarsan çok daha akıcı konuşursun. Her kalıba birden fazla <b>açıklama / tüyo</b> ve <b>örnek cümle</b> ekleyebilir; eklediklerini düzenleyebilir veya silebilirsin. İlerleme: ${practicedTotal}/${totalChunks} kalıp pratiği yapıldı.</div>`;
  html += `<div class="tab-row">`;
  CHUNK_BANK.forEach((c,i)=>{ html += `<button class="tab-btn ${i===chunkCatIndex?'active':''}" onclick="selectChunkCat(${i})">${esc(c.cat)}</button>`; });
  html += `</div>`;
  html += `<div class="card">
    <div class="hint">${esc(cat.cat)} — ${chunkItemIndex+1}/${cat.items.length}${practiced?` — ${practiced} kez pratik yapıldı`:''}</div>
    <p style="font-family:var(--serif); font-size:22px; color:var(--accent); margin:14px 0;">${spk(chunk)}${esc(chunk)}</p>
    ${explanations.length ? `<div style="margin:10px 0 14px;"><div class="hint" style="margin-bottom:7px;">📝 Açıklamalar / Tüyolar</div>${explanations.map((x,i)=>`<div style="display:flex; gap:8px; align-items:flex-start; margin:7px 0; padding:9px 10px; border:1px solid var(--line); border-radius:10px; background:var(--panel2, rgba(127,127,127,.08));"><div style="flex:1; white-space:pre-wrap;">${esc(x)}</div><button class="pill" style="padding:4px 8px;" onclick="editChunkExplanation(${i})" title="Açıklamayı düzenle">✏️</button><button class="pill" style="padding:4px 8px;" onclick="deleteChunkExplanation(${i})" title="Açıklamayı sil">🗑️</button></div>`).join('')}</div>` : ''}
    ${examples.length ? `<div style="margin:10px 0 14px;"><div class="hint" style="margin-bottom:7px;">💬 Örnek Cümleler</div>${examples.map((x,i)=>`<div style="display:flex; gap:8px; align-items:flex-start; margin:7px 0; padding:9px 10px; border:1px solid var(--line); border-radius:10px;"><div style="flex:1;">${spk(x)}${esc(x)}</div><button class="pill" style="padding:4px 8px;" onclick="editChunkExample(${i})" title="Örneği düzenle">✏️</button><button class="pill" style="padding:4px 8px;" onclick="deleteChunkExample(${i})" title="Örneği sil">🗑️</button></div>`).join('')}</div>` : ''}
    <div class="btns" style="display:flex; gap:8px; flex-wrap:wrap;">
      <button class="pill primary" onclick="playChunk('${esc(chunk).replace(/'/g,"\\'")}')">🔊 Dinle</button>
      <button class="pill good" onclick="markChunkPracticed()">✅ Söyledim</button>
      <button class="pill" onclick="addChunkExplanation()">➕ Açıklama / Tüyo</button>
      <button class="pill" onclick="addChunkExample()">➕ Örnek Cümle</button>
      <button class="pill primary" onclick="startChunkTraining()">🧠 Hafızaya Kazı</button>
      <button class="pill" onclick="nextChunk()">➡️ Sıradaki</button>
    </div>
  </div>`;
  return html;
}
function selectChunkCat(i){ chunkCatIndex=i; chunkItemIndex=0; document.getElementById('content').innerHTML=viewChunks(); }
function playChunk(text){ speak(text); }
function getChunkNote(){
  const chunkId=chunkCatIndex+'_'+chunkItemIndex;
  if(!progress.chunkNotes[chunkId]){
    const preset=DEFAULT_CHUNK_NOTES[chunkId] || {explanations:[],examples:[]};
    progress.chunkNotes[chunkId]={
      explanations:Array.isArray(preset.explanations)?preset.explanations.slice():[],
      examples:Array.isArray(preset.examples)?preset.examples.slice():[]
    };
    saveProgress(progress);
  }
  const note=progress.chunkNotes[chunkId];
  // v6.9 verisini kaybetmeden yeni çoklu açıklama yapısına taşı
  if(!Array.isArray(note.explanations)) note.explanations=[];
  if(typeof note.explanation==='string' && note.explanation.trim() && !note.explanations.length) note.explanations.push(note.explanation.trim());
  if('explanation' in note) delete note.explanation;
  if(!Array.isArray(note.examples)) note.examples=[];
  return note;
}
function addChunkExplanation(){
  const note=getChunkNote();
  const val=prompt('Bu kalıpla ilgili yeni bir anlam, kullanım notu veya tüyo yaz:');
  if(val===null || !val.trim()) return;
  note.explanations.push(val.trim()); saveProgress(progress); document.getElementById('content').innerHTML=viewChunks();
}
function editChunkExplanation(i){
  const note=getChunkNote(); if(i<0||i>=note.explanations.length)return;
  const val=prompt('Açıklama / tüyoyu düzenle:',note.explanations[i]);
  if(val===null || !val.trim()) return;
  note.explanations[i]=val.trim(); saveProgress(progress); document.getElementById('content').innerHTML=viewChunks();
}
function deleteChunkExplanation(i){
  const note=getChunkNote(); if(i<0||i>=note.explanations.length)return;
  if(!confirm('Bu açıklama / tüyoyu silmek istiyor musun?'))return;
  note.explanations.splice(i,1); saveProgress(progress); document.getElementById('content').innerHTML=viewChunks();
}
function addChunkExample(){
  const note=getChunkNote(); const val=prompt('Bu kalıp için bir örnek cümle yaz:');
  if(val===null||!val.trim())return;
  note.examples.push(val.trim()); saveProgress(progress); document.getElementById('content').innerHTML=viewChunks();
}
function editChunkExample(i){
  const note=getChunkNote(); if(i<0||i>=note.examples.length)return;
  const val=prompt('Örnek cümleyi düzenle:',note.examples[i]);
  if(val===null||!val.trim())return;
  note.examples[i]=val.trim(); saveProgress(progress); document.getElementById('content').innerHTML=viewChunks();
}
function deleteChunkExample(i){
  const note=getChunkNote(); if(i<0||i>=note.examples.length)return;
  if(!confirm('Bu örnek cümleyi silmek istiyor musun?'))return;
  note.examples.splice(i,1); saveProgress(progress); document.getElementById('content').innerHTML=viewChunks();
}
function markChunkPracticed(){
  const chunkId = chunkCatIndex+'_'+chunkItemIndex;
  progress.chunkProgress[chunkId] = (progress.chunkProgress[chunkId]||0)+1;
  saveProgress(progress);
  nextChunk();
}
function nextChunk(){
  const cat = CHUNK_BANK[chunkCatIndex];
  chunkItemIndex = (chunkItemIndex+1) % cat.items.length;
  document.getElementById('content').innerHTML = viewChunks();
}


// v62: Hafızaya Kazı artık kategori tahmin ettirmez; her kalıp için benzersiz iletişim niyeti verir.
const CHUNK_TRAINING_CUES = {
'0_0':'Kendi fikrini doğrudan söyle: “Bence / ... diye düşünüyorum.”',
'0_1':'Kendi görüşünü biraz daha düzenli ve vurgulu biçimde belirt: “Benim görüşüme göre...”',
'0_2':'Kesin olmadığın bir bilgiyi “Bildiğim kadarıyla...” diyerek aktar.',
'0_3':'Emin olmadığın bir tahmini “Sanırım / galiba...” diye başlat.',
'0_4':'Bir izlenimi yumuşak biçimde “Bana öyle geliyor ki...” diye ifade et.',
'1_0':'Bir görüşe tamamen katıldığını güçlü biçimde söyle.',
'1_1':'Karşı tarafın fikrini anladığını göster, ardından farklı düşündüğünü belirt.',
'1_2':'Önce karşı tarafın noktasını kabul et, sonra “ama” diyerek farklı bir nokta ekle.',
'1_3':'Bir görüşe tam katılmadığını nazikçe “Katıldığımdan emin değilim” anlamında söyle.',
'1_4':'Bir görüşe katılmadığını söyle ve hemen gerekçe vermeye başla.',
'2_0':'Cevap vermeden önce doğal biçimde “bir düşüneyim” diyerek zaman kazan.',
'2_1':'Düşünmek için zaman kazanırken sorunun iyi bir soru olduğunu söyle.',
'2_2':'Bir şeyi nasıl ifade edeceğini düşünürken “Bunu nasıl ifade etsem...” de.',
'2_3':'Söyleyeceğin şeyi düzeltmek, netleştirmek veya beklenmedik bir bilgi eklemek için “Aslında...” diye başla.',
'2_4':'Konuşurken doğal bir dolgu / ortak bilgi işareti olarak “Hani / biliyorsun...” kullan.',
'3_0':'Olumsuz veya hassas bir şeyi nazikçe söylemeye “Korkarım ki...” diye başla.',
'3_1':'Dürüst veya açık bir görüşe “Dürüst olmak gerekirse...” diye başla.',
'3_2':'Nazikçe izin isterken “Sakıncası yoksa...” de.',
'3_3':'Bir şeyi kesin olmayan biçimde “biraz / bir nevi...” diye yumuşat.',
'3_4':'Nazik bir rica veya soru sormaya “Merak ediyordum da...” diye başla.',
'4_0':'Bir konunun diğer tarafını göstermek için “Öte yandan...” diye geçiş yap.',
'4_1':'Konuyu hafifçe değiştirirken “Bu arada...” de.',
'4_2':'Az önce söylenen şeyle bağlantılı yeni bir noktaya “Hazır konusu açılmışken...” diye geç.',
'4_3':'Ana konuya dönmek veya önceki kısmı kapatmak için “Neyse...” de.',
'4_4':'Mevcut noktaya ek bilgi eklerken “Buna ek olarak...” diye başla.',
'5_0':'Önceden karar verilmiş bir gelecek planını söyle.',
'5_1':'Bir planın olduğunu açıkça “... yapmayı planlıyorum” diye söyle.',
'5_2':'Bir isteğini / yapmak istediğin şeyi nazikçe söyle.',
'5_3':'Henüz kesinleşmemiş bir fikri “... yapmayı düşünüyorum” diye belirt.',
'5_4':'Kesin olmayan bir olasılığı “Belki ... yapabilirim” diye söyle.',
'6_0':'Bir şeyi başka bir şeyle doğrudan karşılaştırmaya “... ile karşılaştırıldığında” diye başla.',
'6_1':'İki şey arasındaki zıtlığı “...den farklı olarak” diye belirt.',
'6_2':'İki seçenek arasındaki en önemli farkı söylemeye başla.',
'6_3':'İki şey için de aynı durumun geçerli olduğunu söyle.',
'6_4':'İki şeyden hiçbirisi için durumun geçerli olmadığını söyle.',
'7_0':'Bir sürecin veya hikâyenin nihai sonucunu “Sonunda...” diye özetle.',
'7_1':'Bir sonucu sebebine bağlarken “İşte bu yüzden...” de.',
'7_2':'Bir nedenin sonucunu “Sonuç olarak...” diye belirt.',
'7_3':'Konuşmanın ana noktalarını kısa bir sonuçla özetlemeye başla.',
'7_4':'Genel değerlendirme / sonuç verirken “Genel olarak...” diye başla.'
};
function chunkCue(r){ return CHUNK_TRAINING_CUES[r.id] || ('Bu kalıbın iletişim amacını İngilizce ifade et: '+r.cat); }
function chunkAnswerVariants(r){
  const phrase=(r.phrase||'').replace(/\.\.\.$/,'').trim();
  if(r.id==='3_3') return ['Sort of','kind of'];
  return [phrase];
}
function chunkRecallMatches(r,raw){
  const got=normChunk(raw);
  return chunkAnswerVariants(r).some(v=>got===normChunk(v));
}
function chunkProductionUsesTarget(r,txt){
  const normalized=normChunk(txt);
  return chunkAnswerVariants(r).some(v=>{const base=normChunk(v); return !!base && normalized.length>=base.length+2 && normalized.includes(base);});
}

// ---------- Kalıp Hafıza Antrenmanı ----------
let chunkTrainingState = {queue:[], pos:0, score:0, answered:false, mode:''};
function allChunkRecords(){
  const out=[];
  CHUNK_BANK.forEach((cat,ci)=>cat.items.forEach((phrase,ii)=>{
    const id=ci+'_'+ii;
    const preset=DEFAULT_CHUNK_NOTES[id]||{explanations:[],examples:[]};
    const n=progress.chunkNotes[id]||{};
    out.push({id,ci,ii,cat:cat.cat,phrase,
      explanations:Array.isArray(n.explanations)&&n.explanations.length?n.explanations:[...(preset.explanations||[])],
      examples:Array.isArray(n.examples)&&n.examples.length?n.examples:[...(preset.examples||[])]});
  }));
  return out;
}
function shuffleArr(a){ a=[...a]; for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; }
function chunkWeight(r){ const st=progress.chunkTraining[r.id]||{}; return 6-(st.streak||0)+Math.min((st.wrong||0),4)+(r.examples.length?2:0)+(r.explanations.length?1:0); }
function startChunkTraining(){
  const records=allChunkRecords();
  // Kullanıcının not/örnek eklediği kalıplara öncelik ver; sonra zayıf kalıpları getir.
  let weighted=[]; records.forEach(r=>{for(let k=0;k<Math.max(1,chunkWeight(r));k++) weighted.push(r);});
  weighted=shuffleArr(weighted);
  const seen=new Set(), q=[];
  for(const r of weighted){ if(!seen.has(r.id)){seen.add(r.id);q.push(r);} if(q.length>=10)break; }
  chunkTrainingState={queue:q,pos:0,score:0,answered:false,mode:''};
  document.getElementById('content').innerHTML=viewChunkTraining();
}
function chunkTrainingHeader(){
  const s=chunkTrainingState;
  return `<div class="card hint"><b>🧠 Hafızaya Kazı</b> — kalıbı kategori tahmin ederek değil, gerçek iletişim niyetinden geri çağır: hatırla → tanı → boşluk doldur → üret. Yazımda büyük-küçük harf, noktalama ve apostrof önemsenmez; hedef kalıbı geri çağırman beklenir. Yanlış yaptığın kalıplar sonraki turlarda daha sık gelir. Tur: ${Math.min(s.pos+1,s.queue.length)}/${s.queue.length} · Puan: ${s.score}</div>`;
}
function normChunk(x){return (x||'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();}
function chunkBlankExample(r){
  const target=normChunk(r.phrase.replace(/\.\.\.$/,''));
  for(const ex of r.examples){
    const low=normChunk(ex); if(target && low.includes(target)){
      const words=r.phrase.replace(/\.\.\.$/,'').trim().split(/\s+/).filter(Boolean);
      let masked=ex;
      const escaped=r.phrase.replace(/\.\.\.$/,'').trim().replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      masked=masked.replace(new RegExp(escaped,'i'),'_____');
      if(masked!==ex) return masked;
    }
  }
  return '';
}
function viewChunkTraining(){
  const st=chunkTrainingState;
  if(!st.queue.length) return `<div class="card"><h3>Henüz çalışılacak kalıp yok.</h3><button class="pill" onclick="navigate('chunks')">← Kalıp Bankasına dön</button></div>`;
  if(st.pos>=st.queue.length){
    return `<div class="card"><h2>🏁 Tur tamamlandı</h2><p><b>${st.score}/${st.queue.length}</b> doğru.</p><p class="hint">Amaç tek seferde puan değil: kalıbı aralıklı olarak tekrar tekrar <b>hatırlayabilmek</b>. Yanlışların bir sonraki turda daha yüksek öncelik alır.</p><div class="btns"><button class="pill primary" onclick="startChunkTraining()">🔁 Yeni 10'lu Tur</button><button class="pill" onclick="navigate('chunks')">← Kalıp Bankası</button></div></div>`;
  }
  const r=st.queue[st.pos];
  const modes=['recall','choice','cloze','produce'];
  let mode=modes[st.pos%modes.length];
  if(mode==='cloze' && !chunkBlankExample(r)) mode='recall';
  st.mode=mode;
  let body='';
  if(mode==='recall'){
    body=`<div class="hint">1 · HATIRLA — aşağıdaki iletişim niyetini İngilizce bir kalıpla söyle.</div><h3>${esc(r.cat)}</h3><div class="card hint" style="margin:10px 0;"><b>Durum / niyet:</b> ${esc(chunkCue(r))}</div><input id="chunk-train-input" class="quiz-input" autocomplete="off" placeholder="Uygun İngilizce kalıbı yaz…"><button class="pill primary" onclick="checkChunkRecall()">Kontrol Et</button>`;
  } else if(mode==='choice'){
    let opts=shuffleArr([r,...shuffleArr(allChunkRecords().filter(x=>x.id!==r.id)).slice(0,3)]);
    const clue=chunkCue(r);
    body=`<div class="hint">2 · TANIMA — ipucuna en uygun kalıbı seç.</div><p style="font-size:18px;"><b>${esc(clue)}</b></p><div class="btns" style="display:grid;gap:8px;">${opts.map(o=>`<button class="pill" onclick="answerChunkChoice('${o.id}')">${esc(o.phrase)}</button>`).join('')}</div>`;
  } else if(mode==='cloze'){
    body=`<div class="hint">3 · BOŞLUK DOLDUR — kendi eklediğin örnek cümleden kalıbı geri çağır.</div><p style="font-size:19px;">${esc(chunkBlankExample(r))}</p><input id="chunk-train-input" class="quiz-input" autocomplete="off" placeholder="Eksik kalıbı yaz…"><button class="pill primary" onclick="checkChunkRecall()">Kontrol Et</button>`;
  } else {
    body=`<div class="hint">4 · ÜRET — gerçek öğrenme burada. Kalıbı kullanarak <b>yeni</b> bir cümle kur.</div><p style="font-family:var(--serif);font-size:22px;color:var(--accent);">${spk(r.phrase)}${esc(r.phrase)}</p>${r.explanations.length?`<p class="hint">${esc(r.explanations[0])}</p>`:''}<textarea id="chunk-produce-input" class="quiz-input" placeholder="Bu kalıpla kendi cümleni yaz…"></textarea><button class="pill primary" onclick="checkChunkProduction()">Cümlemi Kontrol Et</button>`;
  }
  return chunkTrainingHeader()+`<div class="card">${body}<div id="chunk-train-feedback" style="margin-top:12px;"></div></div>`;
}
function recordChunkTraining(ok){
  const r=chunkTrainingState.queue[chunkTrainingState.pos];
  const st=progress.chunkTraining[r.id]||(progress.chunkTraining[r.id]={correct:0,wrong:0,streak:0,lastSeen:''});
  if(ok){st.correct++;st.streak++;chunkTrainingState.score++;}else{st.wrong++;st.streak=0;}
  st.lastSeen=todayStr(); saveProgress(progress);
}
function feedbackChunk(ok,extra=''){
  const r=chunkTrainingState.queue[chunkTrainingState.pos];
  const el=document.getElementById('chunk-train-feedback'); if(!el)return;
  el.innerHTML=`<div class="card" style="margin:0;border-color:${ok?'var(--good, #3a6)':'var(--warn, #c86)'}"><b>${ok?'✅ Doğru!':'❌ Henüz değil.'}</b><div style="margin-top:6px;">Doğru kalıp: <b>${esc(r.phrase)}</b> ${spk(r.phrase)}</div>${extra?`<div class="hint" style="margin-top:6px;">${esc(extra)}</div>`:''}<button class="pill primary" style="margin-top:10px;" onclick="nextChunkTrainingQuestion()">Devam →</button></div>`;
}
function checkChunkRecall(){
  if(chunkTrainingState.answered)return;
  const r=chunkTrainingState.queue[chunkTrainingState.pos];
  const inp=document.getElementById('chunk-train-input');
  const raw=(inp?inp.value:'').trim();
  const el=document.getElementById('chunk-train-feedback');
  if(!raw){
    if(el) el.innerHTML='<div class="card" style="margin:0;border-color:var(--warn, #c86)"><b>⚠️ Önce bir cevap yaz.</b><div class="hint" style="margin-top:6px;">Boş cevap doğru/yanlış olarak kaydedilmez.</div></div>';
    if(inp) inp.focus();
    return;
  }
  // v62: soru artık benzersiz iletişim niyeti verir. Noktalama/büyük-küçük harf önemsenmez.
  // Birden fazla yazımı olan kalıplarda (örn. sort of / kind of) doğal varyantlar kabul edilir.
  const ok=chunkRecallMatches(r,raw);
  chunkTrainingState.answered=true; recordChunkTraining(ok); feedbackChunk(ok, r.explanations[0]||'');
}
function answerChunkChoice(id){
  if(chunkTrainingState.answered)return; const r=chunkTrainingState.queue[chunkTrainingState.pos]; const ok=id===r.id;
  chunkTrainingState.answered=true; recordChunkTraining(ok); feedbackChunk(ok,r.explanations[0]||'');
}
function checkChunkProduction(){
  if(chunkTrainingState.answered)return;
  const r=chunkTrainingState.queue[chunkTrainingState.pos];
  const inp=document.getElementById('chunk-produce-input');
  const txt=(inp?inp.value:'').trim();
  const el=document.getElementById('chunk-train-feedback');
  if(!txt){
    if(el) el.innerHTML='<div class="card" style="margin:0;border-color:var(--warn, #c86)"><b>⚠️ Önce bir cümle yaz.</b><div class="hint" style="margin-top:6px;">Boş cevap doğru/yanlış olarak kaydedilmez.</div></div>';
    if(inp) inp.focus();
    return;
  }
  const ok=chunkProductionUsesTarget(r,txt);
  chunkTrainingState.answered=true; recordChunkTraining(ok);
  feedbackChunk(ok, ok?'Güzel: kalıbı hazır cevap olarak değil, kendi cümlenin içinde ürettin.':'Kalıbı cümlenin içinde aynen kullanıp tekrar dene.');
}
function nextChunkTrainingQuestion(){ chunkTrainingState.pos++; chunkTrainingState.answered=false; document.getElementById('content').innerHTML=viewChunkTraining(); }

