function microPickTasks(oldSeen=[]){
  const pool=microTaskPool(), kinds=['BUILD','TRANSFORM','REACT'], picked=[];
  kinds.forEach(kind=>{let opts=pool.filter(x=>x.kind===kind&&!oldSeen.includes(x.id));if(!opts.length)opts=pool.filter(x=>x.kind===kind);picked.push(opts[Math.floor(Math.random()*opts.length)]);});
  return picked;
}
function microTaskData(){
  const t=todayStr(), contentVersion='daily-micro-v4';
  progress.microHistory=progress.microHistory||{seen:[],useful:[],notUseful:[]};
  if(!progress.microTask||progress.microTask.date!==t||progress.microTask.contentVersion!==contentVersion){
    const recent=(progress.mistakes||[]).find(m=>m&&m.en&&String(m.en).split(/\s+/).length>=3);
    const tasks=microPickTasks(progress.microHistory.seen||[]);
    progress.microHistory.seen=(progress.microHistory.seen||[]).concat(tasks.map(x=>x.id)).slice(-40);
    progress.microTask={date:t,contentVersion,sentences:tasks,doneIdx:[],hints:{},revealed:{},startedAt:{},bonusDone:false,realLife:null,personal:recent?{en:recent.en,tr:recent.tr||'Bu eski hatanı daha doğal biçimde yeniden söyle.'}:null};
    saveProgress(progress);
  }
  progress.microTask.hints=progress.microTask.hints||{}; progress.microTask.revealed=progress.microTask.revealed||{}; progress.microTask.startedAt=progress.microTask.startedAt||{};
  return progress.microTask;
}
function microTaskCurrentIndex(mt){for(let i=0;i<mt.sentences.length;i++)if(!mt.doneIdx.includes(i))return i;return mt.sentences.length;}
function microMasteryLabel(){
  const mt=microTaskData(), tries=Number(mt.tries||0), hints=Object.values(mt.hints||{}).reduce((a,b)=>a+Number(b||0),0);
  if(tries<=3&&hints<=1)return 'Can say'; if(hints<=3)return 'Can build'; return 'Recognise → review';
}
