// Odak konusuna göre "5 Kelime" adımı için kart havuzu üretir.
// Her aktivite kendi ilgili veri kaynağından kart döndürür (o gün seçilen konuyla alakasız
// hep aynı ders kelimeleri gelmesin diye).
function dpWordSourceLabel(activity){
  const meta = dpActivityMeta(activity);
  return activity==='lesson' ? '5 Kelime' : '5 Kelime — '+meta.label;
}
function buildDpWordCards(activity, l){
  if(activity==='flashcards'){
    let pool = getDueWords();
    if(!pool.length) pool = getAllWords();
    return shuffleArr(pool).slice(0,5).map(w=>[w.en, w.tr]);
  }
  if(activity==='irregular'){
    return shuffleArr(DATA.irregular.slice()).slice(0,5).map(r=>[r.v1, 'V2: '+r.v2+' — V3: '+r.v3+' — '+r.meaning]);
  }
  if(activity==='collocations'){
    const pool = progress.collocations || [];
    if(!pool.length) return [];
    return shuffleArr(pool.slice()).slice(0,5).map(c=>[c.phrase, c.meaning]);
  }
  // lesson, quiz, dictation, builder, journal, tensequiz, shadowing, speaking:
  // bu bölümlerin kendine özgü kelime havuzu yok, o günün dersinden devam ediyoruz.
  return shuffleArr(l.words.slice()).slice(0,5);
}
function dpStepWords(){
  const activity = (progress.dailyPlan && progress.dailyPlan.activity) || 'lesson';
  const l = DATA.lessons.find(x=>x.no===dailyPlanState.lessonNo);
  if(!dailyPlanState.words) dailyPlanState.words = buildDpWordCards(activity, l);
  let html = `<div class="card"><h3 class="section-title" style="margin-top:0;">${esc(dpWordSourceLabel(activity))}</h3>
    <p class="hint">Kelimelere tıklayarak Türkçesini gör.</p>`;
  if(!dailyPlanState.words.length){
    html += `<p class="hint">Bu bölüm için henüz yeterli kayıtlı içerik yok, bu adımı geçebilirsin.</p>`;
  } else {
    dailyPlanState.words.forEach(w=>{ html += dpFlipCardHtml('<b>'+spk(w[0])+esc(w[0])+'</b>', esc(w[1])); });
  }
  html += `<button class="pill primary" style="margin-top:10px;" onclick="dpNext()">Devam Et ›</button></div>`;
  return html;
}
// Odak konusuna göre "5 Pratik Soru" adımı için çoktan seçmeli soru havuzu üretir.
// Tüm sorular checkDpQuiz'in beklediği ortak {prompt, options, answer, en, tr} biçiminde döner.
function buildWordMCQFromPool(pool, count){
  let items = [];
  shuffleArr(pool.slice()).forEach(w=>{
    if(!w.en || !w.tr) return;
    const distractors = pickCloseDistractors(getAllWords(), {tr:w.tr}, 'tr', 3).map(x=>x.tr);
    if(distractors.length<3) return;
    const options = shuffleArr([w.tr, ...distractors]);
    items.push({type:'choice', prompt:w.en, options, answer:w.tr, en:w.en, tr:w.tr});
  });
  return items.slice(0,count);
}
function buildDpQuizQuestions(activity, l, count){
  if(activity==='flashcards'){
    let pool = getDueWords();
    if(!pool.length) pool = getAllWords();
    return buildWordMCQFromPool(pool, count);
  }
  if(activity==='irregular'){
    let items = [];
    shuffleArr(DATA.irregular.slice()).forEach(r=>{
      const distractors = pickCloseDistractors(DATA.irregular, {meaning:r.meaning}, 'meaning', 3).map(x=>x.meaning);
      if(distractors.length<3) return;
      const options = shuffleArr([r.meaning, ...distractors]);
      items.push({type:'choice', prompt:r.v1+' — V2/V3?', options, answer:r.meaning, en:r.v1, tr:r.meaning});
    });
    return items.slice(0,count);
  }
  if(activity==='collocations'){
    const pool=getStudyCollocations();
    if(pool.length<4) return [];
    return shuffleArr(pool.slice()).slice(0,count).map(c=>{
      const others=shuffleArr(pool.filter(x=>x.phrase!==c.phrase)).slice(0,3).map(x=>x.meaning);
      return {type:'choice',prompt:c.phrase,options:shuffleArr([c.meaning,...others]),answer:c.meaning,en:c.phrase,tr:c.meaning};
    });
  }
  // lesson, quiz, dictation, builder, journal, tensequiz, shadowing, speaking:
  // bu bölümler için ayrı bir çoktan seçmeli havuz yok, o günün dersinden devam ediyoruz.
  return buildLessonTestQuestions(l, 15).filter(q=>q.type==='choice').slice(0,count);
}
function dpStepQuiz(){
  const activity = (progress.dailyPlan && progress.dailyPlan.activity) || 'lesson';
  const l = DATA.lessons.find(x=>x.no===dailyPlanState.lessonNo);
  const meta = dpActivityMeta(activity);
  const title = activity==='lesson' ? '5 Pratik Soru' : '5 Pratik Soru — '+meta.label;
  if(!dailyPlanState.quiz.questions.length){
    dailyPlanState.quiz.questions = buildDpQuizQuestions(activity, l, 5);
    dailyPlanState.quiz.index = 0;
    dailyPlanState.quiz.correct = 0;
  }
  const st = dailyPlanState.quiz;
  if(!st.questions.length){
    return `<div class="card"><h3 class="section-title" style="margin-top:0;">${esc(title)}</h3>
      <p class="hint">Bu bölüm için yeterli soru oluşturulamadı, bu adımı geçebilirsin.</p>
      <button class="pill primary" onclick="dpNext()">Devam Et ›</button></div>`;
  }
  if(st.index >= st.questions.length){
    return `<div class="card"><h3 class="section-title" style="margin-top:0;">Pratik Soru Sonucu</h3>
      <p>Doğru: <b>${st.correct}</b> / ${st.questions.length}</p>
      <button class="pill primary" onclick="dpNext()">Devam Et ›</button></div>`;
  }
  const q = st.questions[st.index];
  return `<div class="quiz-box card">
    <div class="hint">${esc(title)} — Soru ${st.index+1} / ${st.questions.length}</div>
    <div class="quiz-sentence">${spk(q.prompt)}${esc(q.prompt)}</div>
    <div class="wq-options" id="dp-options">${q.options.map(o=>`<div class="wq-opt" data-val="${esc(o)}" onclick="checkDpQuiz(this,'${escJs(o)}')">${esc(o)}</div>`).join('')}</div>
    <div class="quiz-feedback" id="dp-feedback"></div>
    <div class="btns" style="display:flex; gap:8px; margin-top:10px;">
      <button class="pill" id="dp-next" style="display:none;" onclick="nextDpQuiz()">Sonraki ›</button>
    </div>
  </div>`;
}
function checkDpQuiz(el, chosen){
  const st = dailyPlanState.quiz;
  const q = st.questions[st.index];
  document.querySelectorAll('#dp-options .wq-opt').forEach(o=>{
    o.onclick=null;
    if(o.dataset.val===q.answer) o.classList.add('correct');
    else if(o===el) o.classList.add('wrong');
  });
  const fb = document.getElementById('dp-feedback');
  const isCorrect = chosen===q.answer;
  if(isCorrect){ st.correct++; fb.textContent='✓ Doğru!'; fb.className='quiz-feedback ok'; removeMistake(q.en); }
  else { fb.textContent='✕ Yanlış. Doğru cevap: '+q.answer; fb.className='quiz-feedback bad'; addMistake(q.en, q.tr, 'günlük plan'); }
  recordLessonStat(dailyPlanState.lessonNo, isCorrect);
  recordDailyStat(isCorrect);
  saveProgress(progress);
  updateMistakeBadge();
  document.getElementById('dp-next').style.display='inline-flex';
}
function nextDpQuiz(){
  dailyPlanState.quiz.index++;
  document.getElementById('content').innerHTML = viewDailyPlan();
}
